function newsLabGoogleDiscoverySource(category = "top", query = "", index = 0) {
  const encoded = encodeURIComponent(`${query} when:1d`);
  const label = category === "top" ? "Top" : category.charAt(0).toUpperCase() + category.slice(1);
  return {
    name: `${label} Discovery ${index + 1}`,
    category,
    discovery: true,
    generated: true,
    homepage: `https://news.google.com/search?q=${encodeURIComponent(query)}`,
    feed: `https://news.google.com/rss/search?q=${encoded}&hl=en-US&gl=US&ceid=US:en`
  };
}

function newsLabGeneratedDiscoverySources(target = newsLabSourcePoolTarget) {
  const generated = [];
  Object.entries(newsLabDiscoveryTopics).forEach(([category, topics]) => {
    topics.forEach((topic, index) => generated.push(newsLabGoogleDiscoverySource(category, topic, index)));
  });
  const localMarketGenerated = localMarkets.flatMap((market, index) => ([
    newsLabGoogleDiscoverySource("local", `${market} breaking local news`, index * 3),
    newsLabGoogleDiscoverySource("local", `${market} public safety weather schools`, index * 3 + 1),
    newsLabGoogleDiscoverySource("local", `${market} city county government`, index * 3 + 2)
  ]));
  const combined = [...generated, ...localMarketGenerated];
  return combined.slice(0, Math.max(0, target));
}

