function newsDataLatestUrl(category = "top") {
  if (!newsDataApiKey) return "";
  const params = new URLSearchParams({
    apikey: newsDataApiKey,
    language: "en",
    country: "us"
  });
  const normalized = String(category || "top").toLowerCase();
  if (["top", "world", "politics", "business", "technology", "sports", "entertainment"].includes(normalized)) {
    params.set("category", normalized);
  }
  if (normalized === "local") {
    params.set("q", "local weather police city county school community");
  }
  return `https://newsdata.io/api/1/latest?${params.toString()}`;
}

function newsDataSourcesForCategories(categories = newsLabPublicCategories) {
  if (!newsDataApiKey) return [];
  return categories
    .map(category => ({
      name: `NewsData ${category === "top" ? "Top" : category[0].toUpperCase() + category.slice(1)}`,
      category,
      homepage: "https://newsdata.io/",
      feed: newsDataLatestUrl(category),
      newsData: true,
      discovery: true,
      limit: category === "top" ? 15 : 12
    }))
    .filter(source => source.feed);
}

const newsDataSources = newsDataSourcesForCategories();
const expandedDiscoverySources = newsLabGeneratedDiscoverySources(newsLabSourcePoolTarget);
const feedSources = [
  ...newsDataSources,
  ...majorSources,
  ...businessTechnologySources,
  ...worldSources,
  ...politicsSources,
  ...entertainmentSources,
  ...sportsSources,
  ...directLocalSources,
  ...localSources,
  ...expandedDiscoverySources
].filter((source, index, all) => all.findIndex(item => item.feed === source.feed) === index);

function newsLabCollectorCategories() {
  return newsLabPublicCategories;
}

function newsLabCollectorCacheFile(category = "top") {
  return path.join(newsLabCollectorDir, `${String(category || "top").replace(/[^a-z0-9-]/gi, "-")}.json`);
}

function newsLabCollectorStatusFile(category = "top") {
  return path.join(newsLabCollectorDir, `${String(category || "top").replace(/[^a-z0-9-]/gi, "-")}.status.json`);
}

function newsLabCollectorSourcesForCategory(category = "top") {
  const normalized = String(category || "top").toLowerCase();
  if (normalized === "top") {
    return [
      ...newsDataSources,
      ...majorSources,
      ...worldSources.slice(0, 4),
      ...politicsSources.slice(0, 4),
      ...businessTechnologySources.slice(0, 8),
      ...sportsSources.slice(0, 5),
      ...entertainmentSources.slice(0, 5),
      ...expandedDiscoverySources.filter(source => ["world", "politics", "business", "technology", "sports", "entertainment"].includes(source.category)).slice(0, 80)
    ].filter((source, index, all) => all.findIndex(item => item.feed === source.feed) === index);
  }
  if (normalized === "business") {
    return [
      ...newsDataSources.filter(source => source.category === "business"),
      ...businessTechnologySources.filter(source => source.category === "business"),
      ...marketTickerSources.map(source => ({ ...source, category: "business", marketTicker: true })),
      ...expandedDiscoverySources.filter(source => source.category === "business")
    ].filter((source, index, all) => all.findIndex(item => item.feed === source.feed) === index);
  }
  if (normalized === "technology") {
    return [
      ...newsDataSources.filter(source => source.category === "technology"),
      ...businessTechnologySources.filter(source => source.category === "technology"),
      ...expandedDiscoverySources.filter(source => source.category === "technology")
    ].filter((source, index, all) => all.findIndex(item => item.feed === source.feed) === index);
  }
  if (normalized === "world") return [...newsDataSources.filter(source => source.category === "world"), ...worldSources, ...expandedDiscoverySources.filter(source => source.category === "world")];
  if (normalized === "politics") return [...newsDataSources.filter(source => source.category === "politics"), ...politicsSources, ...expandedDiscoverySources.filter(source => source.category === "politics")];
  if (normalized === "sports") return [...newsDataSources.filter(source => source.category === "sports"), ...sportsSources, ...expandedDiscoverySources.filter(source => source.category === "sports")];
  if (normalized === "entertainment") return [...newsDataSources.filter(source => source.category === "entertainment"), ...entertainmentSources, ...expandedDiscoverySources.filter(source => source.category === "entertainment")];
  if (normalized === "local") return [...newsDataSources.filter(source => source.category === "local"), ...directLocalSources, ...localSources, ...expandedDiscoverySources.filter(source => source.category === "local")];
  return feedSources.filter(source => source.category === normalized);
}

function newsLabCollectorBackfillSourcesForCategory(category = "top") {
  const normalized = String(category || "top").toLowerCase();
  const categorySources = newsLabCollectorSourcesForCategory(normalized);
  const broader = [
    ...newsDataSources.filter(source => normalized === "top" || source.category === normalized),
    ...majorSources,
    ...expandedDiscoverySources.filter(source => normalized === "top" || source.category === normalized),
    ...feedSources.filter(source => {
      if (normalized === "top") return true;
      const text = `${source.name || ""} ${source.category || ""} ${source.homepage || ""} ${source.feed || ""}`;
      return source.category === normalized || newsLabCollectorTabTerms(normalized).test(text);
    })
  ];
  return [...categorySources, ...broader]
    .filter((source, index, all) => all.findIndex(item => item.feed === source.feed) === index);
}

