function isTransientNetworkError(error) {
  const code = String(error?.code || error?.cause?.code || "");
  const message = String(error?.message || error?.cause?.message || "");
  const stack = String(error?.stack || "");
  return code === "UND_ERR_SOCKET"
    || code === "ERR_HTTP2_SESSION_ERROR"
    || code === "ERR_HTTP2_STREAM_ERROR"
    || /other side closed/i.test(message)
    || /http2.*session|session closed|stream closed|stream error/i.test(message)
    || /ClientHttp2Stream/i.test(stack)
    || /onHttp2SocketEnd|ERR_HTTP2_SESSION_ERROR|ERR_HTTP2_STREAM_ERROR/i.test(stack);
}

function isHttp2SessionError(error) {
  const code = String(error?.code || error?.cause?.code || "");
  const message = String(error?.message || error?.cause?.message || "");
  const stack = String(error?.stack || "");
  return code === "ERR_HTTP2_SESSION_ERROR"
    || code === "ERR_HTTP2_STREAM_ERROR"
    || /http2.*session|session closed|stream closed|stream error/i.test(message)
    || /ERR_HTTP2_SESSION_ERROR|ERR_HTTP2_STREAM_ERROR|ClientHttp2Stream|onHttp2SocketEnd/i.test(stack);
}

function recordTransientNetworkError(error, source = "process") {
  const message = error?.message || error?.cause?.message || "Transient upstream network error";
  runtimeState.transientNetworkErrorCount = Number(runtimeState.transientNetworkErrorCount || 0) + 1;
  runtimeState.lastTransientNetworkErrorAt = new Date().toISOString();
  runtimeState.lastTransientNetworkError = `${source}: ${message}`.slice(0, 500);
  runtimeState.lastError = runtimeState.lastTransientNetworkError;
  try {
    saveFrameworkLearningProofEntry({
      category: "runtime-resilience",
      event: "Transient upstream socket error contained",
      plainEnglish: "A remote feed/source closed a socket unexpectedly. The runtime captured it as a site-resilience signal instead of letting the website crash.",
      realWorldData: {
        source,
        code: error?.code || error?.cause?.code || "",
        message,
        transientNetworkErrorCount: runtimeState.transientNetworkErrorCount
      },
      decisionMeasurement: {
        trigger: "process-level transient network error",
        decision: "contain and log instead of crash",
        confidenceScore: 92,
        governanceDecision: "safe runtime protection"
      },
      proceduralMemory: {
        rule: "When UND_ERR_SOCKET, HTTP/2 stream close, or remote feed socket-close errors appear, classify them as transient upstream network failures, keep the site alive, log proof, and let feed diagnostics identify the failing source."
      },
      resultMetric: {
        siteStayedOnline: true,
        crashPrevented: true
      },
      evidence: ["Render log showed UND_ERR_SOCKET other side closed from undici ClientHttp2Stream.", "Process handler recorded the event in runtimeState and framework proof log."],
      tags: ["runtime", "feed-reliability", "subsystem", "meta-execution", "crash-prevention"]
    });
  } catch {
    // If data storage is not ready yet, runtimeState still carries the evidence for /api/health.
  }
}

function recordFatalRuntimeError(error, source = "process") {
  const message = error?.message || "Unhandled runtime error";
  runtimeState.lastFatalErrorAt = new Date().toISOString();
  runtimeState.lastFatalError = `${source}: ${message}`.slice(0, 500);
  runtimeState.lastError = runtimeState.lastFatalError;
}

process.on("uncaughtException", error => {
  if (isTransientNetworkError(error)) {
    recordTransientNetworkError(error, "uncaughtException");
    console.warn("Contained transient upstream network error:", error?.code || "", error?.message || error);
    return;
  }
  recordFatalRuntimeError(error, "uncaughtException");
  console.error(error);
  process.exit(1);
});

process.on("unhandledRejection", reason => {
  const error = reason instanceof Error ? reason : new Error(String(reason || "Unhandled rejection"));
  if (isTransientNetworkError(error)) {
    recordTransientNetworkError(error, "unhandledRejection");
    console.warn("Contained transient upstream network rejection:", error?.code || "", error?.message || error);
    return;
  }
  recordFatalRuntimeError(error, "unhandledRejection");
  console.error(error);
});

function decodeEntities(value = "") {
  const named = {
    amp: "&",
    apos: "'",
    hellip: "...",
    gt: ">",
    lt: "<",
    nbsp: " ",
    ndash: "-",
    mdash: "-",
    quot: '"',
    rsquo: "'",
    lsquo: "'",
    rdquo: '"',
    ldquo: '"'
  };
  return String(value || "")
    .replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1")
    .replace(/&amp;(#x?[0-9a-f]+;)/gi, "&$1")
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(parseInt(code, 10)))
    .replace(/&([a-z]+);/gi, (match, name) => Object.prototype.hasOwnProperty.call(named, name.toLowerCase()) ? named[name.toLowerCase()] : match)
    .replace(/&#(?=[\u2018\u2019\u201c\u201d'"A-Za-z$])/g, "")
    .replace(/&#x?[0-9a-f]+\b/gi, "")
    .replace(/&amp;/g, "&")
    .replace(/&lt;/g, "<")
    .replace(/&gt;/g, ">");
}

function stripTags(value = "") {
  return decodeEntities(value)
    .replace(/<[^>]*>/g, " ")
    .replace(/\s+/g, " ")
    .replace(/\b(and|or|the|a|an|to|of|in|on|for|with|mo)\.?$/i, "")
    .trim();
}

function removeNonArticleHtml(value = "") {
  return String(value || "")
    .replace(/<script[\s\S]*?<\/script>/gi, " ")
    .replace(/<style[\s\S]*?<\/style>/gi, " ")
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, " ")
    .replace(/<svg[\s\S]*?<\/svg>/gi, " ")
    .replace(/<template[\s\S]*?<\/template>/gi, " ");
}

function looksLikeScriptJunk(value = "") {
  const text = String(value || "");
  return /fetch-start|fetch-done|function\s*\(|=>|var\s+\w+|window\.|document\.|addEventListener|newrelic|datadog|gtag|googletag|ezstandalone|34\|\||\{[^}]{0,80}headers[^}]{0,80}\}/i.test(text)
    || (/[{}[\];=]/.test(text) && (text.match(/[{}[\];=]/g) || []).length > 8)
    || /[a-z]\?[a-z]\[/.test(text);
}

function cleanEncodingArtifacts(value = "") {
  const leftSingle = String.fromCharCode(226, 8364, 732);
  const rightSingle = String.fromCharCode(226, 8364, 8482);
  const leftDouble = String.fromCharCode(226, 8364, 339);
  const rightDouble = String.fromCharCode(226, 8364, 157);
  const dash = String.fromCharCode(226, 8364, 8220);
  const longDash = String.fromCharCode(226, 8364, 8221);
  return String(value || "")
    .split(leftSingle).join("'")
    .split(rightSingle).join("'")
    .split(leftDouble).join('"')
    .split(rightDouble).join('"')
    .split(dash).join("-")
    .split(longDash).join("-")
    .replace(/ÃƒÂ¢Ã¢â€šÂ¬Ã‹Å“|ÃƒÂ¢Ã¢â€šÂ¬Ã¢â€žÂ¢|ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¡|ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Âº/g, "'")
    .replace(/ÃƒÂ¢Ã¢â€šÂ¬Ã…â€œ|ÃƒÂ¢Ã¢â€šÂ¬Ã‚Â|ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¾|ÃƒÂ¢Ã¢â€šÂ¬Ã…Â¸/g, '"')
    .replace(/ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Å“|ÃƒÂ¢Ã¢â€šÂ¬Ã¢â‚¬Â/g, "-")
    .replace(/\u00e2\u20ac[\u02dc\u2122\u0153\u009d]?/g, "'")
    .replace(/\u00e2\u20ac[\u009c\u009d]/g, '"')
    .replace(/\u00c3[\u0080-\u00bf]?/g, "")
    .replace(/\u00c2[\u0080-\u00bf]?/g, "")
    .replace(/\u00ef\u00bf\u00bd/g, "")
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .replace(/[\u0080-\u009f\u00a0-\u00ff\ufffd]/g, "")
    .replace(/&amp;(#x?[0-9a-f]+;)/gi, "&$1")
    .replace(/&#x([0-9a-f]+);/gi, (_, hex) => String.fromCodePoint(parseInt(hex, 16)))
    .replace(/&#(\d+);/g, (_, code) => String.fromCodePoint(parseInt(code, 10)))
    .replace(/&#x?[0-9a-f]+\b/gi, "")
    .replace(/&nbsp;|&#160;/gi, " ")
    .replace(/&#x27;/g, "'")
    .replace(/\.\.\.+/g, ".")
    .replace(/\s+/g, " ")
    .trim();
}

function cleanArticleText(value = "", limit = 640) {
  const cleaned = cleanEncodingArtifacts(decodeHtmlEntities(stripTags(removeNonArticleHtml(value))))
    .replace(/\bADVERTISEMENT\b/gi, " ")
    .replace(/\bAdvertisement\b/g, " ")
    .replace(/\s+/g, " ")
    .trim();
  if (!cleaned || looksLikeScriptJunk(cleaned)) return "";
  return trimToCompleteSentence(cleaned, limit);
}

function trimToCompleteSentence(value = "", limit = 640) {
  const text = cleanEncodingArtifacts(value).replace(/\s+/g, " ").trim();
  if (!text || text.length <= limit) return text;
  const sliced = text.slice(0, limit);
  const sentence = sliced.match(/^([\s\S]*[.!?])(?:\s|$)/)?.[1]?.trim();
  if (sentence && sentence.length >= 60) return sentence;
  return sliced.replace(/\s+\S*$/, "").replace(/[,:;]+$/g, "").trim();
}

function tagValue(block, tagName) {
  const match = block.match(new RegExp(`<${tagName}[^>]*>([\\s\\S]*?)<\\/${tagName}>`, "i"));
  return match ? decodeEntities(match[1]).trim() : "";
}

function attrValue(block, tagName, attrName) {
  const match = block.match(new RegExp(`<${tagName}[^>]*\\s${attrName}=["']([^"']+)["'][^>]*>`, "i"));
  return match ? decodeEntities(match[1]).trim() : "";
}

function stripGoogleRedirect(url) {
  if (!url) return "";
  try {
    const parsed = new URL(url);
    return parsed.searchParams.get("url") || url;
  } catch {
    return url;
  }
}

function absoluteUrl(value, base) {
  try {
    return new URL(value, base).href;
  } catch {
    return "";
  }
}

function itemSourceUrl(block) {
  return attrValue(block, "source", "url");
}

function itemSourceName(block) {
  return stripTags(tagValue(block, "source"));
}

function publisherNameFromUrl(url = "") {
  try {
    const host = new URL(url).hostname.replace(/^www\./, "");
    const label = host.split(".").slice(0, -1).join(" ") || host;
    return label
      .split(/[\s-]+/)
      .filter(Boolean)
      .map(word => word.length <= 3 ? word.toUpperCase() : `${word[0].toUpperCase()}${word.slice(1)}`)
      .join(" ");
  } catch {
    return "";
  }
}

