function readJsonFile(filePath, fallback) {
  ensureDataFiles();
  const readStarted = apiProfilerNow();
  let raw = "";
  try {
    raw = fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, "");
    const readMs = apiProfilerNow() - readStarted;
    const parseStarted = apiProfilerNow();
    const parsed = JSON.parse(raw);
    const parseMs = apiProfilerNow() - parseStarted;
    apiProfilerRecordFile(filePath, readMs, parseMs, Buffer.byteLength(raw, "utf8"), true);
    return parsed;
  } catch {
    apiProfilerRecordFile(filePath, apiProfilerNow() - readStarted, 0, raw ? Buffer.byteLength(raw, "utf8") : 0, false);
    return fallback;
  }
}

function compactNewsLabPublicImage(image = null) {
  if (!image || typeof image !== "object") return image || null;
  return {
    primary: image.primary || image.url || image.src || "",
    fallback: image.fallback || "",
    url: image.url || image.primary || image.src || "",
    src: image.src || image.primary || image.url || "",
    alt: image.alt || "",
    credit: image.credit || "",
    query: image.query || image.originalQuery || "",
    source: image.source || "",
    photographer: image.photographer || "",
    license: image.license || "",
    provenance: image.provenance || null,
    relevance: image.relevance || null
  };
}

function compactNewsLabPublicStory(story = {}) {
  const keep = [
    "id", "topicKey", "eventId", "slug", "url", "title", "originalHeadline", "category", "tab", "source",
    "publishedAt", "originalPublishedAt", "updatedAt", "generatedAt", "savedAt", "summary", "dek", "lead",
    "body", "paragraphs", "updates", "storyUpdates", "sources", "reportingTrail", "relatedArticles",
    "storyDossier", "storyEvolution", "sourceAgreement", "contradictionDetection", "brainConfidence",
    "confidence", "popularity", "publicationTier", "qualityGate", "editorEnforcement", "contentLaneQuality",
    "headlineAudit", "publicArticle", "publicHeadlineRepaired", "fallbackCoverage", "isBreaking", "status"
  ];
  const compacted = {};
  keep.forEach(key => {
    if (story[key] !== undefined && story[key] !== null) compacted[key] = story[key];
  });
  compacted.image = compactNewsLabPublicImage(story.image || null);
  compacted.imageProvenance = story.imageProvenance || compacted.image?.provenance || null;
  return compacted;
}

function compactNewsLabPublishedPayload(value) {
  if (!value || typeof value !== "object" || !Array.isArray(value.ownedStories)) return value;
  return {
    generatedAt: value.generatedAt || new Date().toISOString(),
    status: value.status || "published",
    purpose: value.purpose || "Publish original Censored Expressions news tiles.",
    policy: value.policy || undefined,
    sourceStoryCount: value.sourceStoryCount || 0,
    dossierSourceStoryCount: value.dossierSourceStoryCount || 0,
    clusteredStoryCount: value.clusteredStoryCount || 0,
    writingClusterCount: value.writingClusterCount || 0,
    tabSubsystems: value.tabSubsystems || undefined,
    brainInfrastructure: value.brainInfrastructure || undefined,
    durablePublication: value.durablePublication || undefined,
    savedAt: value.savedAt || new Date().toISOString(),
    ownedStories: value.ownedStories.map(compactNewsLabPublicStory)
  };
}

function writeJsonFile(filePath, value) {
  ensureDataFiles();
  fs.mkdirSync(path.dirname(filePath), { recursive: true });
  const valueToWrite = filePath === newsLabPublishedPayloadFile ? compactNewsLabPublishedPayload(value) : value;
  const finalText = `${JSON.stringify(valueToWrite, null, 2)}\n`;
  const tempPath = `${filePath}.${process.pid}.${Date.now()}.tmp`;
  fs.writeFileSync(tempPath, finalText);
  fs.renameSync(tempPath, filePath);
}

function defaultKnowledgeDistillationPolicy() {
  return {
    version: "20260722-knowledge-distillation-policy-v1",
    updatedAt: new Date().toISOString(),
    purpose: "Retain reusable knowledge instead of keeping every raw workflow experience forever.",
    mode: "non-destructive-first-pass",
    layers: [
      {
        id: "working-memory",
        purpose: "Short-lived operational material such as active feeds, current story drafts, dossiers, editor reviews, image prompts, and pending patches.",
        lifetime: "minutes-to-seven-days-unless-active-or-public",
        retentionRule: "Keep while active; distill lessons and compact after publication, abandonment, or learning extraction."
      },
      {
        id: "episodic-memory",
        purpose: "Compressed lessons from events, rejections, repairs, source failures, and publication outcomes.",
        lifetime: "rolling-history",
        retentionRule: "Store what happened, why it mattered, and what changed; avoid retaining full article text unless needed for visible publication or audit."
      },
      {
        id: "semantic-memory",
        purpose: "Generalized topic, writing, evidence, source, and editorial knowledge that improves future behavior.",
        lifetime: "long-term",
        retentionRule: "Promote repeated successful lessons into compact rules with confidence and usage evidence."
      },
      {
        id: "pattern-memory",
        purpose: "Reusable statistical observations such as first-pass approval patterns, headline failures, image fit, and source reliability trends.",
        lifetime: "long-term",
        retentionRule: "Store pattern, confidence, evidence count, use-when, and avoid-when. Do not store raw article text as the pattern."
      },
      {
        id: "experience-memory",
        purpose: "Only significant decisions, failures, breakthroughs, and owner-approved capability changes.",
        lifetime: "rolling-significant-history",
        retentionRule: "Store decision, reason, outcome, improvement, and future confidence; discard ordinary raw experience after distillation gates pass."
      },
      {
        id: "skills",
        purpose: "Reusable operational procedures such as source isolation, headline repair, reject-repair-resubmit, payload visibility checks, and memory compaction.",
        lifetime: "long-term",
        retentionRule: "Keep as named capabilities only while verification evidence shows they still work."
      },
      {
        id: "identity",
        purpose: "Owner intent, editorial boundaries, legal policy, brand standards, architecture rules, and governance expectations.",
        lifetime: "permanent",
        retentionRule: "Never delete through cleanup; update only through explicit owner or framework-approved change."
      }
    ],
    deletionPolicy: {
      enabled: false,
      reason: "First pass classifies and distills only. Raw deletion/compaction requires proven public visibility and learning preservation.",
      futureGate: "A raw item can be deleted only after it is not active, not public-facing, not needed for audit, and its reusable lesson has been written to semantic or skill memory."
    }
  };
}

