function defaultMemoryConsolidationActions() {
  return {
    version: "20260722-memory-consolidation-actions-v1",
    generatedAt: new Date().toISOString(),
    purpose: "Concrete non-destructive consolidation actions: merge duplicate lessons, promote verified capabilities, retire stale patterns, and mark temporary raw artifacts after safety gates.",
    deletionEnabled: false,
    summary: {},
    mergeActions: [],
    promoteActions: [],
    retireActions: [],
    temporaryFileActions: [],
    preserveActions: [],
    blockedDeleteActions: []
  };
}

function normalizeConsolidationKey(value = "") {
  return String(value || "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, " ")
    .trim()
    .split(/\s+/)
    .filter(word => word.length > 2 && !/^(the|and|for|with|from|that|this|into|onto|after|before|update|story|news|report|reports)$/i.test(word))
    .slice(0, 8)
    .join(" ");
}

function clusterConsolidationItems(items = [], getText = item => item.id || item.key || item.observation || "") {
  const clusters = new Map();
  items.forEach(item => {
    const key = normalizeConsolidationKey(getText(item));
    if (!key) return;
    if (!clusters.has(key)) clusters.set(key, []);
    clusters.get(key).push(item);
  });
  return [...clusters.entries()]
    .filter(([, group]) => group.length > 1)
    .map(([key, group]) => ({ key, count: group.length, examples: group.slice(0, 5).map(getText) }));
}

function buildMemoryConsolidationActions(reason = "manual", inputs = {}) {
  const semanticMemory = inputs.semanticMemory || defaultSemanticMemory();
  const skillMemory = inputs.skillMemory || defaultSkillMemory();
  const patternMemory = inputs.patternMemory || defaultPatternMemory();
  const experienceMemory = inputs.experienceMemory || defaultExperienceMemory();
  const retentionLedger = inputs.retentionLedger || buildKnowledgeDistillationLedger();
  const deletionEnabled = process.env.CE_KNOWLEDGE_DISTILLATION_DELETE === "true";
  const now = new Date().toISOString();
  const patterns = Array.isArray(patternMemory.patterns) ? patternMemory.patterns : [];
  const skills = Array.isArray(skillMemory.skills) ? skillMemory.skills : [];
  const experiences = Array.isArray(experienceMemory.experiences) ? experienceMemory.experiences : [];
  const mergeActions = [
    ...clusterConsolidationItems(patterns, item => `${item.domain || ""} ${item.observation || item.id || ""}`).map(cluster => ({ ...cluster, memory: "pattern-memory", action: "merge-duplicate-patterns" })),
    ...clusterConsolidationItems(experiences, item => `${item.decision || ""} ${item.improvement || ""}`).map(cluster => ({ ...cluster, memory: "experience-memory", action: "merge-similar-experiences" }))
  ];
  const promoteActions = patterns
    .filter(pattern => Number(pattern.confidence || 0) >= 0.86)
    .map(pattern => ({
      id: pattern.id,
      sourceMemory: "pattern-memory",
      targetMemory: /image/.test(pattern.domain || "") ? "skill-memory" : "semantic-memory",
      action: "promote-if-current-validator-confirms",
      confidence: pattern.confidence,
      reason: pattern.observation,
      useWhen: pattern.useWhen || "",
      avoidWhen: pattern.avoidWhen || ""
    }));
  const retireActions = patterns
    .filter(pattern => Number(pattern.confidence || 0) < 0.6)
    .map(pattern => ({
      id: pattern.id,
      action: "do-not-promote-yet",
      confidence: pattern.confidence,
      reason: "Low confidence means this stays as monitored learning instead of a permanent rule."
    }));
  const ledgerItems = [...(retentionLedger.files || []), ...(retentionLedger.directories || [])];
  const temporaryFileActions = ledgerItems
    .filter(item => /working-memory/.test(item.layer || "") && /distill|compact|archive/.test(item.action || "") && !/public|visible|active|repair|audit/i.test(item.reason || ""))
    .map(item => ({ label: item.label, path: item.path, bytes: item.bytes, action: deletionEnabled ? "eligible-for-compaction-after-gates" : "mark-temporary-after-distillation", deletionEnabled }));
  const preserveActions = ledgerItems
    .filter(item => /public|visible|active|repair|audit|story objects/i.test(`${item.label || ""} ${item.reason || ""}`) || /preserve/.test(item.action || ""))
    .map(item => ({ label: item.label, path: item.path, bytes: item.bytes, action: "preserve", reason: item.reason }));
  const blockedDeleteActions = ledgerItems
    .filter(item => Number(item.bytes || 0) > 1024 * 1024)
    .map(item => ({
      label: item.label,
      path: item.path,
      bytes: item.bytes,
      blockedBecause: deletionEnabled ? "needs-per-file-active-public-audit-verification" : "global-deletion-disabled",
      requiredGate: "not active, not public/searchable, not under repair, not audit-required, reusable lesson written to long-term memory"
    }));
  return {
    version: "20260722-memory-consolidation-actions-v1",
    generatedAt: now,
    reason,
    purpose: "Concrete non-destructive consolidation actions: merge duplicate lessons, promote verified capabilities, retire stale patterns, and mark temporary raw artifacts after safety gates.",
    deletionEnabled,
    summary: {
      duplicateLessonClusters: mergeActions.length,
      promoteCandidates: promoteActions.length,
      retireCandidates: retireActions.length,
      temporaryCandidates: temporaryFileActions.length,
      preserveCount: preserveActions.length,
      blockedDeletes: blockedDeleteActions.length,
      skillsTracked: skills.length,
      semanticDomains: Object.keys(semanticMemory.domains || {}).length
    },
    mergeActions,
    promoteActions,
    retireActions,
    temporaryFileActions,
    preserveActions,
    blockedDeleteActions,
    workerRule: "Workers should emit distilled lessons at task completion. The consolidation worker clusters and promotes the lesson, not the raw file, unless legal/public/audit value requires retention."
  };
}

