function fileOrDirectoryStat(targetPath, label, layer, action, reason) {
  try {
    if (!fs.existsSync(targetPath)) {
      return { label, path: targetPath, exists: false, layer, action, reason, bytes: 0, itemCount: 0 };
    }
    const stat = fs.statSync(targetPath);
    if (!stat.isDirectory()) {
      return {
        label,
        path: targetPath,
        exists: true,
        layer,
        action,
        reason,
        bytes: stat.size,
        itemCount: 1,
        modifiedAt: stat.mtime.toISOString()
      };
    }
    const stack = [targetPath];
    let bytes = 0;
    let itemCount = 0;
    while (stack.length) {
      const current = stack.pop();
      fs.readdirSync(current, { withFileTypes: true }).forEach(entry => {
        const child = path.join(current, entry.name);
        if (entry.isDirectory()) {
          stack.push(child);
          return;
        }
        try {
          const childStat = fs.statSync(child);
          bytes += childStat.size;
          itemCount += 1;
        } catch {
          // Skip files that disappear during the scan.
        }
      });
    }
    return { label, path: targetPath, exists: true, layer, action, reason, bytes, itemCount };
  } catch (error) {
    return { label, path: targetPath, exists: false, layer, action: "review", reason: error.message || String(error), bytes: 0, itemCount: 0 };
  }
}

function readSmallJsonForDistillation(filePath, fallback = {}) {
  try {
    if (!fs.existsSync(filePath)) return fallback;
    const stat = fs.statSync(filePath);
    if (stat.size > 12 * 1024 * 1024) {
      return { skipped: true, reason: "file-too-large-for-inline-distillation", bytes: stat.size };
    }
    return JSON.parse(fs.readFileSync(filePath, "utf8").replace(/^\uFEFF/, ""));
  } catch (error) {
    return { skipped: true, reason: "json-read-failed", error: error.message || String(error) };
  }
}

function distillObjectKeys(value, max = 20) {
  if (!value || typeof value !== "object") return [];
  return Object.keys(value).slice(0, max);
}

function buildKnowledgeDistillationLedger() {
  const fileEntries = [
    fileOrDirectoryStat(newsLabStoryObjectsFile, "News Lab story objects", "working-memory", "preserve-and-distill", "Current and historical story objects are required for public visibility, repair, updates, and audit."),
    fileOrDirectoryStat(newsLabPublishedPayloadFile, "News Lab public payload", "working-memory", "preserve", "Visible public shelf must remain intact; compact only expired non-visible article history."),
    fileOrDirectoryStat(newsLabApprovalRecoveryQueueFile, "Approval recovery queue", "working-memory", "distill-then-compact", "Retain active repairs; distill rejection patterns and remove resolved duplicate records later."),
    fileOrDirectoryStat(newsLabHeadlineRepairQueueFile, "Headline repair queue", "working-memory", "distill-then-compact", "Retain active headline repair evidence; promote repeated fixes to headline skill memory."),
    fileOrDirectoryStat(newsLabArticleApprovalIntelligenceFile, "Article approval intelligence", "episodic-memory", "distill-and-retain-summary", "Approval and rejection reasons should become behavior-changing editorial lessons."),
    fileOrDirectoryStat(dailyArticleMemoryFile, "Daily article memory", "working-memory", "distill-then-archive", "Raw article memory can grow quickly; retain only public articles, active dossiers, and extracted knowledge."),
    fileOrDirectoryStat(frameworkLearningProofFile, "Framework learning proof log", "episodic-memory", "summarize-and-archive", "Proof logs are audit evidence but should be periodically summarized into capability memory."),
    fileOrDirectoryStat(frameworkActionLogFile, "Framework action log", "episodic-memory", "summarize-and-archive", "Action logs should feed capability and skill outcomes rather than grow without bound."),
    fileOrDirectoryStat(adaptiveWeightProofFile, "Adaptive weight proof log", "episodic-memory", "summarize-and-archive", "Adaptive-weight evidence should become confidence updates and compact proofs."),
    fileOrDirectoryStat(frameworkPatchDirectionDir, "Patch directions for Codex", "working-memory", "distill-then-compact", "Old teaching prompts should be reduced to reusable patch skills after resolved."),
    fileOrDirectoryStat(newsLabCollectorDir, "News Lab collector outputs", "working-memory", "preserve-active-distill-old", "Collector data should remain available for active dossiers and become source coverage lessons after use.")
  ];
  const files = fileEntries.filter(entry => !entry.path || (!entry.path.endsWith("patch-directions-for-codex") && !entry.path.endsWith("news-lab-collectors")));
  const directories = fileEntries.filter(entry => entry.path && (entry.path.endsWith("patch-directions-for-codex") || entry.path.endsWith("news-lab-collectors")));
  const totalBytesReviewed = fileEntries.reduce((sum, entry) => sum + Number(entry.bytes || 0), 0);
  return {
    version: "20260722-memory-retention-ledger-v1",
    updatedAt: new Date().toISOString(),
    purpose: "Classify large or high-churn files by memory layer before any cleanup is attempted.",
    nonDestructive: true,
    totalBytesReviewed,
    files,
    directories,
    recommendations: [
      "Do not count raw storage growth as learning. Distill rejection, repair, source, and writing outcomes into compact semantic and skill memory.",
      "Do not delete story objects or public payload records that are visible, searchable, under repair, or needed for story updates.",
      "Compact queues only after each record is resolved, lesson extraction is complete, and the public payload or archive owns the final article state.",
      "Archive proof and action logs after they are summarized into capability, semantic, and skill memory."
    ]
  };
}

