function recordNewsLabWorkerSyncLedger(event = {}) {
  const ledger = readJsonFile(newsLabWorkerSyncLedgerFile, defaultNewsLabWorkerSyncLedger()) || defaultNewsLabWorkerSyncLedger();
  const nextEvent = { ...event, at: new Date().toISOString() };
  const events = [...(Array.isArray(ledger.events) ? ledger.events : []), nextEvent].slice(-80);
  const acceptedKeys = Array.isArray(event.acceptedKeys) ? event.acceptedKeys : [];
  const rejectedKeys = Array.isArray(event.rejectedKeys) ? event.rejectedKeys : [];
  const nextLedger = {
    ...ledger,
    version: "20260724-news-lab-worker-sync-v1",
    updatedAt: new Date().toISOString(),
    lastSyncAt: nextEvent.at,
    lastReason: event.reason || "worker-sync",
    acceptedCount: acceptedKeys.length,
    rejectedCount: rejectedKeys.length,
    acceptedKeys,
    rejectedKeys,
    lastSource: event.source || "worker",
    events
  };
  writeJsonFile(newsLabWorkerSyncLedgerFile, nextLedger);
  return nextLedger;
}

async function handleNewsLabWorkerSync(request, response) {
  const syncStarted = apiProfilerNow();
  if (!isAdminRequest(request)) {
    sendPrivateNotFound(response);
    return;
  }
  const bodyStarted = apiProfilerNow();
  const body = await readLargeJsonRequestBody(request, Number(process.env.CE_WORKER_SYNC_BODY_LIMIT_BYTES || 16 * 1024 * 1024)).catch(error => ({ parseError: error.message || String(error) }));
  const bodyMs = Math.max(0, apiProfilerNow() - bodyStarted);
  if (body.parseError) {
    sendPrivateJson(response, 400, { ok: false, error: body.parseError, syncDiagnostics: { bodyMs, totalMs: Math.max(0, apiProfilerNow() - syncStarted) } });
    return;
  }
  const allowlist = newsLabWorkerSyncAllowlist();
  const files = Array.isArray(body.files) ? body.files : [];
  const accepted = [];
  const rejected = [];
  let writeMsTotal = 0;
  let acceptedBytes = 0;
  for (const file of files) {
    const key = String(file?.key || "").trim();
    const targetPath = allowlist[key];
    if (!targetPath) {
      rejected.push({ key: key || "missing-key", reason: "not-allowed" });
      continue;
    }
    if (!file || typeof file.payload !== "object" || file.payload === null) {
      rejected.push({ key, reason: "payload-must-be-json-object-or-array" });
      continue;
    }
    const fileStarted = apiProfilerNow();
    writeJsonFile(targetPath, file.payload);
    const writeMs = Math.max(0, apiProfilerNow() - fileStarted);
    const bytes = Number(file.bytes || 0) || Buffer.byteLength(JSON.stringify(file.payload), "utf8");
    writeMsTotal += writeMs;
    acceptedBytes += bytes;
    accepted.push({ key, bytes, writeMs, mtimeMs: Number(file.mtimeMs || 0) });
  }
  const ledgerStarted = apiProfilerNow();
  const ledger = recordNewsLabWorkerSyncLedger({
    reason: body.reason || "worker-sync",
    source: body.source || "background-worker",
    generatedAt: body.generatedAt || "",
    deltaSync: Boolean(body.deltaSync),
    acceptedKeys: accepted.map(item => item.key),
    rejectedKeys: rejected.map(item => item.key),
    accepted,
    rejected,
    bodyMs,
    writeMsTotal,
    acceptedBytes,
    totalMs: Math.max(0, apiProfilerNow() - syncStarted)
  });
  const ledgerMs = Math.max(0, apiProfilerNow() - ledgerStarted);
  const totalMs = Math.max(0, apiProfilerNow() - syncStarted);
  sendPrivateJson(response, 200, {
    ok: true,
    generatedAt: new Date().toISOString(),
    acceptedCount: accepted.length,
    rejectedCount: rejected.length,
    accepted,
    rejected,
    syncDiagnostics: {
      deltaSync: Boolean(body.deltaSync),
      fileCount: files.length,
      bodyMs,
      writeMsTotal,
      ledgerMs,
      totalMs,
      acceptedBytes,
      slow: totalMs >= Number(process.env.CE_WORKER_SYNC_SLOW_MS || 5000)
    },
    ledger: { lastSyncAt: ledger.lastSyncAt, lastReason: ledger.lastReason }
  });
}
function safeFileAgeMs(filePath = "") {
  try {
    const stat = fs.statSync(filePath);
    return Date.now() - stat.mtimeMs;
  } catch {
    return null;
  }
}

function newsLabObservabilityFreshness(value = "") {
  const time = Date.parse(value || "");
  if (!time) return { ageMs: null, fresh: false, label: "unknown" };
  const ageMs = Date.now() - time;
  return {
    ageMs,
    fresh: ageMs >= 0 && ageMs < 2 * 60 * 1000,
    label: ageMs < 60000 ? `${Math.max(0, Math.round(ageMs / 1000))}s ago` : `${Math.round(ageMs / 60000)}m ago`
  };
}

function buildNewsLabObservabilityReport(reason = "api-request") {
  const generatedAt = new Date().toISOString();
  const persistedWorker = readJsonFile(newsLabObservabilityFile, defaultNewsLabObservability()) || defaultNewsLabObservability();
  const productivity = newsLabProductivitySummary();
  const productivityRaw = readJsonFile(newsLabProductivityFile, {}) || {};
  const approval = readJsonFile(newsLabArticleApprovalIntelligenceFile, {}) || {};
  const worker = readNewsLabWorkerStatus();
  const apiWorker = readNewsLabApiWorkerStatus();
  const stuckWorker = readNewsLabStuckRescueWorkerStatus();
  const imageWorker = readJsonFile(newsLabImageWorkerStatusFile, {}) || {};
  const evolutionWorker = readJsonFile(path.join(dataDir, "framework-evolution-engine-worker-status.json"), {}) || {};
  const workerSync = readJsonFile(newsLabWorkerSyncLedgerFile, defaultNewsLabWorkerSyncLedger()) || defaultNewsLabWorkerSyncLedger();
  const collectorSummary = newsLabCollectorWorkerStatusSummary();
  const payload = readNewsLabPublishedPayload() || { ownedStories: [] };
  const visibleStories = Array.isArray(payload.ownedStories) ? payload.ownedStories.length : 0;
  const activePayload = newsLabApplyCurrentBoardPolicy({ ownedStories: payload.ownedStories || [] });
  const activeStories = Array.isArray(activePayload.ownedStories) ? activePayload.ownedStories : [];
  const categoryCounts = newsLabPublicCategories.reduce((counts, category) => {
    counts[category] = category === "top"
      ? Math.min(newsLabTopNewsLimit, activeStories.length)
      : activeStories.filter(story => String(story.category || "").toLowerCase() === category || (Array.isArray(story.secondaryCategories) && story.secondaryCategories.map(item => String(item).toLowerCase()).includes(category))).length;
    return counts;
  }, {});
  const headlineQueue = newsLabHeadlineRepairQueueSummary();
  const approvalQueue = newsLabApprovalRecoveryQueueSummary();
  const totals = productivityRaw.totals || {};
  const lastHour = productivity.lastHour || productivityRaw.lastHour || {};
  const editorialReviews = Number(totals.editorialReviews || approval.totals?.reviewed || 0);
  const approvedArticles = Number(totals.approvedArticles || approval.totals?.approved || 0);
  const rejectedArticles = Math.max(0, editorialReviews - approvedArticles);
  const publishedArticles = Number(totals.publishedArticles || 0);
  const approvalRate = editorialReviews ? Number(((approvedArticles / editorialReviews) * 100).toFixed(2)) : 0;
  const publishRate = Number(lastHour.publishedArticles || lastHour.published || 0);
  const fetchedPerMinute = Number(((collectorSummary.totalCollectedStories || 0) / Math.max(1, newsLabCollectorCategories().length)).toFixed(2));
  const workers = {
    orchestrator: {
      active: Boolean(persistedWorker.orchestrator?.active),
      pid: Number(persistedWorker.orchestrator?.pid || 0),
      heartbeatAt: persistedWorker.orchestrator?.heartbeatAt || persistedWorker.generatedAt || "",
      freshness: newsLabObservabilityFreshness(persistedWorker.orchestrator?.heartbeatAt || persistedWorker.generatedAt || ""),
      activeRoles: Number(persistedWorker.orchestrator?.activeRoles || 0),
      roles: persistedWorker.orchestrator?.roles || []
    },
    production: { active: Boolean(worker.active), status: worker.lastStatus || "", lastRun: worker.lastFinishedAt || worker.generatedAt || "", freshness: newsLabObservabilityFreshness(worker.lastFinishedAt || worker.generatedAt || ""), pid: Number(worker.workerPid || worker.pid || 0) },
    apiResponse: { active: Boolean(apiWorker.active), status: apiWorker.lastStatus || "", lastRun: apiWorker.finishedAt || apiWorker.generatedAt || "", freshness: newsLabObservabilityFreshness(apiWorker.finishedAt || apiWorker.generatedAt || ""), pid: Number(apiWorker.workerPid || apiWorker.pid || 0) },
    stuckRescue: { active: Boolean(stuckWorker.active), status: stuckWorker.lastStatus || "", lastRun: stuckWorker.finishedAt || stuckWorker.generatedAt || "", freshness: newsLabObservabilityFreshness(stuckWorker.finishedAt || stuckWorker.generatedAt || ""), pid: Number(stuckWorker.workerPid || stuckWorker.pid || 0) },
    image: { active: Boolean(imageWorker.active), status: imageWorker.lastStatus || "", lastRun: imageWorker.finishedAt || imageWorker.startedAt || "", freshness: newsLabObservabilityFreshness(imageWorker.finishedAt || imageWorker.startedAt || "") },
    evolution: { active: Boolean(evolutionWorker.active), status: evolutionWorker.lastStatus || "", lastRun: evolutionWorker.finishedAt || evolutionWorker.generatedAt || "", freshness: newsLabObservabilityFreshness(evolutionWorker.finishedAt || evolutionWorker.generatedAt || "") },
    sync: { active: Boolean(workerSync.lastSyncAt), status: workerSync.lastReason || "not-synced-yet", lastRun: workerSync.lastSyncAt || "", freshness: newsLabObservabilityFreshness(workerSync.lastSyncAt || ""), acceptedCount: Number(workerSync.acceptedCount || 0), rejectedCount: Number(workerSync.rejectedCount || 0), acceptedKeys: workerSync.acceptedKeys || [], rejectedKeys: workerSync.rejectedKeys || [] }
  };
  const findings = [];
  if (!workers.orchestrator.freshness.fresh) findings.push("background worker orchestrator heartbeat is stale or missing");
  if (collectorSummary.underfilledCategories?.length) findings.push(`underfilled tabs: ${collectorSummary.underfilledCategories.join(", ")}`);
  if (approvalRate && approvalRate < 20) findings.push(`low editorial approval rate: ${approvalRate}%`);
  if (Number(approvalQueue.active?.length || 0) > 0) findings.push(`${approvalQueue.active.length} approval recovery items are active`);
  if (Number(headlineQueue.active?.length || 0) > 0) findings.push(`${headlineQueue.active.length} headline repair items are active`);
  const report = {
    version: "20260724-news-lab-observability-v1",
    generatedAt,
    reason,
    queues: {
      headlineRepair: { active: headlineQueue.active?.length || 0, totals: headlineQueue.totals || {}, topReasons: (headlineQueue.reasonRanking || []).slice(0, 6), recoveryRates: headlineQueue.recoveryRates || {}, fileAgeMs: safeFileAgeMs(newsLabHeadlineRepairQueueFile) },
      approvalRecovery: { active: approvalQueue.active?.length || 0, totals: approvalQueue.totals || {}, topReasons: (approvalQueue.reasonRanking || []).slice(0, 6), stageRanking: (approvalQueue.stageRanking || []).slice(0, 6), recoveryRates: approvalQueue.recoveryRates || {}, fileAgeMs: safeFileAgeMs(newsLabApprovalRecoveryQueueFile) }
    },
    workers,
    collectors: {
      activeCount: collectorSummary.activeCount,
      totalCollectedStories: collectorSummary.totalCollectedStories,
      fetchedPerMinuteEstimate: fetchedPerMinute,
      underfilledCategories: collectorSummary.underfilledCategories || [],
      categories: collectorSummary.categories || []
    },
    throughput: {
      lastHour,
      cycles: Number(totals.cycles || 0),
      builds: Number(totals.builds || 0),
      skippedCycles: Number(totals.skippedCycles || 0),
      storiesFetchedPerMinuteEstimate: fetchedPerMinute,
      publishRateLastHour: publishRate
    },
    editorial: {
      reviews: editorialReviews,
      approved: approvedArticles,
      rejected: rejectedArticles,
      approvalRate,
      topBlockers: (approval.topBlockers || approval.currentCycle?.topBlockers || []).slice(0, 8),
      passFailLastHour: { approved: Number(lastHour.approvedArticles || 0), rejected: Number(lastHour.finalBlocked || lastHour.rejected || 0) }
    },
    publishing: {
      visibleStories,
      activeBoardStories: activeStories.length,
      categoryCounts,
      publishedCounter: publishedArticles,
      publishConversionRate: approvedArticles ? Number(((visibleStories / approvedArticles) * 100).toFixed(2)) : 0,
      boardPolicy: activePayload.boardDatePolicy || null
    },
    health: {
      status: findings.length ? "attention" : "ok",
      findings,
      lastSuccessfulRun: worker.lastFinishedAt || apiWorker.finishedAt || stuckWorker.finishedAt || "",
      rule: "Watch queue depth, collector freshness, editorial pass/fail, publish conversion, and worker heartbeats before public output degrades."
    }
  };
  writeJsonFile(newsLabObservabilityFile, { ...persistedWorker, ...report, orchestrator: persistedWorker.orchestrator || {}, workerEvents: (persistedWorker.workerEvents || []).slice(-80) });
  return report;
}
