function newsLabProductivitySummary(ledger = readJsonFile(newsLabProductivityFile, null) || defaultNewsLabProductivityLedger()) {
  const recent = Array.isArray(ledger.recentCycles) ? ledger.recentCycles : [];
  const hourAgo = Date.now() - 60 * 60 * 1000;
  const recentHour = recent.filter(cycle => {
    const time = new Date(cycle.finishedAt || cycle.startedAt || cycle.generatedAt || 0).getTime();
    return Number.isFinite(time) && time >= hourAgo;
  });
  const published = recentHour.reduce((sum, cycle) => sum + Number(cycle.publishedArticles || 0), 0);
  const latencies = recentHour.map(cycle => Number(cycle.publicationLatencyMs || 0)).filter(Boolean);
  return {
    updatedAt: ledger.updatedAt || "",
    totals: ledger.totals || {},
    lastHour: {
      cycles: recentHour.length,
      skippedCycles: recentHour.filter(cycle => cycle.status === "skipped-build-already-active").length,
      builds: recentHour.filter(cycle => cycle.buildPerformed).length,
      editorialReviews: recentHour.reduce((sum, cycle) => sum + Number(cycle.editorialReviews || 0), 0),
      approvedArticles: recentHour.reduce((sum, cycle) => sum + Number(cycle.approvedArticles || 0), 0),
      rejectedDrafts: recentHour.reduce((sum, cycle) => sum + Number(cycle.rejectedDrafts || 0), 0),
      publishedArticles: published,
      highQualityPublishedArticlesPerHour: published,
      averagePublicationLatencyMs: latencies.length ? Math.round(latencies.reduce((sum, value) => sum + value, 0) / latencies.length) : 0,
      preEditorRepairedDrafts: recentHour.reduce((sum, cycle) => sum + Number(cycle.preEditorRepairedDrafts || 0), 0),
      preEditorHeldDrafts: recentHour.reduce((sum, cycle) => sum + Number(cycle.preEditorHeldDrafts || 0), 0),
      usefulDraftsForEditor: recentHour.reduce((sum, cycle) => sum + Number(cycle.usefulDraftsForEditor || 0), 0),
      uselessDraftsPrevented: recentHour.reduce((sum, cycle) => sum + Number(cycle.uselessDraftsPrevented || 0), 0)
    },
    recentCycles: recent.slice(-20),
    rule: ledger.rule || "Optimize high-quality published articles per hour, not cycles per minute."
  };
}

function recordNewsLabProductivityCycle(cycle = {}) {
  const ledger = readJsonFile(newsLabProductivityFile, null) || defaultNewsLabProductivityLedger();
  const honestPublishedArticles = Number(
    cycle.newVisibleStoriesAdded
    ?? cycle.publicationOutcomeAudit?.counters?.newStoriesAdded
    ?? cycle.currentBatchPublishedCount
    ?? (Number(cycle.visiblePublishedArticles || 0) > Number(cycle.previousVisiblePublishedArticles || 0)
      ? Number(cycle.visiblePublishedArticles || 0) - Number(cycle.previousVisiblePublishedArticles || 0)
      : 0)
  );
  const record = {
    generatedAt: new Date().toISOString(),
    ...cycle,
    publishedArticles: Math.max(0, honestPublishedArticles),
    publicationAccountingRule: "PublishedArticles counts only newly visible public payload stories. Updates, preserved shelf items, and duplicates do not increase this counter."
  };
  const recentCycles = [...(Array.isArray(ledger.recentCycles) ? ledger.recentCycles : []), record].slice(-240);
  const totals = { ...(ledger.totals || {}) };
  totals.cycles = Number(totals.cycles || 0) + 1;
  if (record.status === "skipped-build-already-active") totals.skippedCycles = Number(totals.skippedCycles || 0) + 1;
  if (record.buildPerformed) totals.builds = Number(totals.builds || 0) + 1;
  totals.editorialReviews = Number(totals.editorialReviews || 0) + Number(record.editorialReviews || 0);
  totals.approvedArticles = Number(totals.approvedArticles || 0) + Number(record.approvedArticles || 0);
  totals.rejectedDrafts = Number(totals.rejectedDrafts || 0) + Number(record.rejectedDrafts || 0);
  totals.publishedArticles = Number(totals.publishedArticles || 0) + Number(record.publishedArticles || 0);
  totals.sourceStoriesCollected = Number(totals.sourceStoriesCollected || 0) + Number(record.sourceStoriesCollected || 0);
  totals.storyClusters = Number(totals.storyClusters || 0) + Number(record.storyClusters || 0);
  totals.dossiersCompleted = Number(totals.dossiersCompleted || 0) + Number(record.dossiersCompleted || 0);
  totals.firstPassEditorialApprovals = Number(totals.firstPassEditorialApprovals || 0) + Number(record.firstPassEditorialApprovals || 0);
  totals.preEditorRepairedDrafts = Number(totals.preEditorRepairedDrafts || 0) + Number(record.preEditorRepairedDrafts || 0);
  totals.preEditorHeldDrafts = Number(totals.preEditorHeldDrafts || 0) + Number(record.preEditorHeldDrafts || 0);
  totals.usefulDraftsForEditor = Number(totals.usefulDraftsForEditor || 0) + Number(record.usefulDraftsForEditor || 0);
  totals.uselessDraftsPrevented = Number(totals.uselessDraftsPrevented || 0) + Number(record.uselessDraftsPrevented || 0);
  const next = {
    ...ledger,
    updatedAt: new Date().toISOString(),
    totals,
    recentCycles
  };
  next.lastHour = newsLabProductivitySummary(next).lastHour;
  writeJsonFile(newsLabProductivityFile, next);
  return next;
}


