function normalizeMerchList(value) {
  if (Array.isArray(value)) return value.map(item => String(item || "").trim()).filter(Boolean).slice(0, 24);
  return String(value || "").split(",").map(item => item.trim()).filter(Boolean).slice(0, 24);
}

function normalizeMerchProduct(input = {}, existing = {}) {
  const title = String(input.title ?? existing.title ?? "").trim();
  const sku = String(input.sku ?? existing.sku ?? "").trim();
  const id = String(input.id || existing.id || merchSlug(`${sku || title}-${Date.now()}`)).trim();
  const statusInput = String(input.status ?? existing.status ?? "active").trim();
  const status = ["active", "draft", "hidden", "sold_out"].includes(statusInput) ? statusInput : "active";
  const product = {
    id,
    sku,
    title,
    category: String(input.category ?? existing.category ?? "Merchandise").trim(),
    price: String(input.price ?? existing.price ?? "Request quote").trim(),
    image: String(input.image ?? existing.image ?? "./assets/logo.png").trim(),
    description: String(input.description ?? existing.description ?? "").trim(),
    colors: normalizeMerchList(input.colors ?? existing.colors ?? []),
    sizes: normalizeMerchList(input.sizes ?? existing.sizes ?? []),
    featured: Boolean(input.featured ?? existing.featured ?? false),
    status,
    sortOrder: Number(input.sortOrder ?? existing.sortOrder ?? 999),
    createdAt: existing.createdAt || new Date().toISOString(),
    updatedAt: new Date().toISOString()
  };
  const errors = [];
  if (!product.title) errors.push("Product title is required.");
  if (!product.sku) errors.push("SKU is required.");
  if (!product.description) errors.push("Description is required.");
  return { product, errors };
}

function readMerchProducts(includeHidden = false) {
  const products = readJsonFile(merchProductsFile, defaultMerchProducts());
  const normalized = (Array.isArray(products) ? products : defaultMerchProducts())
    .map((item, index) => normalizeMerchProduct({ ...item, sortOrder: item.sortOrder ?? index * 10 }, item).product)
    .sort((a, b) => Number(a.sortOrder || 999) - Number(b.sortOrder || 999) || a.title.localeCompare(b.title));
  return includeHidden ? normalized : normalized.filter(product => product.status === "active");
}

function saveMerchProduct(input = {}) {
  const products = readMerchProducts(true);
  const existingIndex = products.findIndex(product => product.id === input.id || product.sku === input.sku);
  const existing = existingIndex >= 0 ? products[existingIndex] : {};
  const { product, errors } = normalizeMerchProduct(input, existing);
  if (errors.length) return { ok: false, errors };
  const next = existingIndex >= 0
    ? products.map((item, index) => index === existingIndex ? product : item)
    : [product, ...products];
  writeJsonFile(merchProductsFile, next);
  return { ok: true, product, products: readMerchProducts(true) };
}

function removeMerchProduct(input = {}) {
  const id = String(input.id || "").trim();
  const products = readMerchProducts(true);
  const existing = products.find(product => product.id === id || product.sku === id);
  if (!existing) return { ok: false, error: "Product was not found." };
  const next = products.map(product => product.id === existing.id ? { ...product, status: "hidden", updatedAt: new Date().toISOString() } : product);
  writeJsonFile(merchProductsFile, next);
  return { ok: true, product: { ...existing, status: "hidden" }, products: readMerchProducts(true) };
}

function merchRegionFromLocation(location = "", request = null) {
  const value = String(location || "").trim();
  if (value) return value.slice(0, 90);
  const cfCountry = request?.headers?.["cf-ipcountry"];
  return cfCountry ? String(cfCountry).slice(0, 90) : "Unknown";
}

function merchProductLookup(input = {}) {
  const products = readMerchProducts(true);
  return products.find(product =>
    product.id === input.productId
    || product.sku === input.sku
    || product.title === input.product
    || product.title === input.title
  ) || {};
}

function normalizeMerchEvent(input = {}, request = null) {
  const product = merchProductLookup(input);
  const eventType = ["view", "order_request", "sale"].includes(String(input.eventType || "")) ? String(input.eventType) : "order_request";
  const quantity = Math.max(0, Math.min(999, Number(input.quantity || (eventType === "view" ? 0 : 1)) || 0));
  return {
    id: `merch_${Date.now()}_${Math.random().toString(16).slice(2)}`,
    at: new Date().toISOString(),
    eventType,
    productId: product.id || String(input.productId || "").trim(),
    sku: product.sku || String(input.sku || "").trim(),
    product: product.title || String(input.product || input.title || "").trim(),
    category: product.category || String(input.category || "Merchandise").trim(),
    size: String(input.size || "").trim() || "Unspecified",
    color: String(input.color || "").trim() || "Unspecified",
    quantity,
    amount: Number(input.amount || 0) || 0,
    contactEmail: String(input.email || "").trim().toLowerCase(),
    location: merchRegionFromLocation(input.location, request),
    notes: String(input.notes || "").trim().slice(0, 500),
    source: String(input.source || "merch-shop").trim(),
    userAgent: String(request?.headers?.["user-agent"] || "").slice(0, 180)
  };
}

function merchRevenue(event = {}) {
  return Number(event.amount || 0) || 0;
}

function merchUnitCount(event = {}) {
  if (event.eventType === "view") return 0;
  return Math.max(0, Number(event.quantity || 0));
}

function summarizeMerchEvents(events = []) {
  const byProduct = {};
  const byCategory = {};
  const bySize = {};
  const byColor = {};
  const byRegion = {};
  const add = (bucket, key, event) => {
    const safeKey = key || "Unknown";
    bucket[safeKey] ||= { key: safeKey, units: 0, orderRequests: 0, confirmedSales: 0, views: 0, revenue: 0 };
    bucket[safeKey].units += merchUnitCount(event);
    bucket[safeKey].orderRequests += event.eventType === "order_request" ? 1 : 0;
    bucket[safeKey].confirmedSales += event.eventType === "sale" ? 1 : 0;
    bucket[safeKey].views += event.eventType === "view" ? 1 : 0;
    bucket[safeKey].revenue = Number((bucket[safeKey].revenue + merchRevenue(event)).toFixed(2));
  };
  events.forEach(event => {
    add(byProduct, event.product || event.sku || event.productId, event);
    add(byCategory, event.category, event);
    add(bySize, event.size, event);
    add(byColor, event.color, event);
    add(byRegion, event.location, event);
  });
  const sorted = bucket => Object.values(bucket).sort((a, b) => b.units - a.units || b.orderRequests - a.orderRequests || b.views - a.views);
  return {
    totalEvents: events.length,
    totalUnits: events.reduce((sum, event) => sum + merchUnitCount(event), 0),
    totalOrderRequests: events.filter(event => event.eventType === "order_request").length,
    totalConfirmedSales: events.filter(event => event.eventType === "sale").length,
    totalViews: events.filter(event => event.eventType === "view").length,
    totalRevenue: Number(events.reduce((sum, event) => sum + merchRevenue(event), 0).toFixed(2)),
    byProduct: sorted(byProduct),
    byCategory: sorted(byCategory),
    bySize: sorted(bySize),
    byColor: sorted(byColor),
    byRegion: sorted(byRegion)
  };
}

function merchWeeklyReport(now = new Date()) {
  const events = readJsonFile(merchSalesFile, []);
  const end = now.getTime();
  const weekStart = end - 7 * 24 * 60 * 60 * 1000;
  const priorStart = end - 14 * 24 * 60 * 60 * 1000;
  const inRange = (event, start, finish) => {
    const at = Date.parse(event.at || "");
    return Number.isFinite(at) && at >= start && at < finish;
  };
  const currentWeek = events.filter(event => inRange(event, weekStart, end));
  const priorWeek = events.filter(event => inRange(event, priorStart, weekStart));
  const last24h = events.filter(event => inRange(event, end - 24 * 60 * 60 * 1000, end));
  const current = summarizeMerchEvents(currentWeek);
  const prior = summarizeMerchEvents(priorWeek);
  const recent = summarizeMerchEvents(last24h);
  const spikes = recent.byProduct
    .map(item => {
      const priorItem = current.byProduct.find(product => product.key === item.key) || { units: 0, orderRequests: 0, views: 0 };
      const baselineDailyUnits = Math.max(0.15, (priorItem.units - item.units) / 6);
      const spikeScore = Number((item.units / baselineDailyUnits).toFixed(2));
      return { ...item, baselineDailyUnits: Number(baselineDailyUnits.toFixed(2)), spikeScore };
    })
    .filter(item => item.units >= 2 && item.spikeScore >= 2)
    .slice(0, 5);
  return {
    generatedAt: now.toISOString(),
    window: {
      currentWeekStart: new Date(weekStart).toISOString(),
      currentWeekEnd: new Date(end).toISOString(),
      priorWeekStart: new Date(priorStart).toISOString(),
      priorWeekEnd: new Date(weekStart).toISOString()
    },
    currentWeek: current,
    priorWeek: prior,
    last24h: recent,
    spikes,
    recommendations: [
      spikes.length ? `Feature ${spikes[0].key}; it is showing a ${spikes[0].spikeScore}x recent unit spike.` : "No product has crossed the automatic spike threshold yet.",
      current.byRegion.length ? `Watch regional demand led by ${current.byRegion[0].key}.` : "Regional demand will appear after order requests or sales include location.",
      current.bySize.length ? `Stock planning should pay attention to ${current.bySize[0].key} sizes.` : "Size demand will appear after shoppers choose sizes."
    ]
  };
}

function applyMerchFeatureDecision(event = {}) {
  if (!["order_request", "sale"].includes(event.eventType)) return null;
  const report = merchWeeklyReport();
  const spike = report.spikes.find(item => item.key === event.product);
  if (!spike) return null;
  const products = readMerchProducts(true);
  const until = new Date(Date.now() + 72 * 60 * 60 * 1000).toISOString();
  const next = products.map(product => product.title === event.product || product.id === event.productId
    ? {
        ...product,
        featured: true,
        autoFeaturedUntil: until,
        featureReason: `Auto-featured after ${spike.units} recent units and ${spike.spikeScore}x spike score.`,
        updatedAt: new Date().toISOString()
      }
    : product
  );
  writeJsonFile(merchProductsFile, next);
  return { product: event.product, autoFeaturedUntil: until, spike };
}

function recordMerchEvent(input = {}, request = null) {
  const event = normalizeMerchEvent(input, request);
  if (!event.product) return { ok: false, error: "Product is required." };
  const events = readJsonFile(merchSalesFile, []);
  const next = [...events, event].slice(-10000);
  writeJsonFile(merchSalesFile, next);
  const featureDecision = applyMerchFeatureDecision(event);
  return {
    ok: true,
    event,
    featureDecision,
    report: merchWeeklyReport()
  };
}

function parsePriceCents(value = "") {
  const match = String(value || "").match(/\$?(\d+(?:\.\d{1,2})?)/);
  if (!match) return 0;
  return Math.round(Number(match[1]) * 100);
}

function readMerchOrders(limit = 500) {
  const orders = readJsonFile(merchOrdersFile, []);
  return Array.isArray(orders) ? orders.slice(-limit) : [];
}

function saveMerchOrder(order) {
  const orders = readMerchOrders(5000);
  const index = orders.findIndex(item => item.id === order.id || (order.checkoutSessionId && item.checkoutSessionId === order.checkoutSessionId));
  const next = index >= 0 ? orders.map((item, i) => i === index ? { ...item, ...order } : item) : [...orders, order];
  writeJsonFile(merchOrdersFile, next.slice(-5000));
  return order;
}

function stripeConfigured() {
  return Boolean(process.env.STRIPE_SECRET_KEY);
}

function stripeWebhookConfigured() {
  return Boolean(process.env.STRIPE_WEBHOOK_SECRET);
}

function stripeFormEncode(params) {
  const body = new URLSearchParams();
  const append = (key, value) => {
    if (value === undefined || value === null) return;
    if (typeof value === "object" && !Array.isArray(value)) {
      Object.entries(value).forEach(([childKey, childValue]) => append(`${key}[${childKey}]`, childValue));
      return;
    }
    body.append(key, String(value));
  };
  Object.entries(params).forEach(([key, value]) => append(key, value));
  return body;
}

function normalizeCheckoutItem(input = {}) {
  const product = merchProductLookup(input);
  const quantity = Math.max(1, Math.min(99, Number(input.quantity || 1) || 1));
  const rawAmountCents = Number(input.amountCents || parsePriceCents(product.price || input.price)) || 0;
  const amountCents = rawAmountCents > 0 ? Math.max(50, rawAmountCents) : 0;
  const errors = [];
  if (!product.title && !input.product) errors.push("A valid product is required.");
  if (!amountCents) errors.push("A fixed product price is required before digital checkout can be used.");
  return {
    errors,
    item: {
      productId: product.id || String(input.productId || "").trim(),
      sku: product.sku || String(input.sku || "").trim(),
      product: product.title || String(input.product || "").trim(),
      category: product.category || String(input.category || "Merchandise").trim(),
      price: product.price || String(input.price || "").trim(),
      amountCents,
      size: String(input.size || "").trim() || "Unspecified",
      color: String(input.color || "").trim() || "Unspecified",
      quantity,
      email: String(input.email || "").trim().toLowerCase(),
      location: String(input.location || "").trim(),
      notes: String(input.notes || "").trim().slice(0, 500)
    }
  };
}

async function createStripeCheckoutSession(input = {}, request = null) {
  const { item, errors } = normalizeCheckoutItem(input);
  if (errors.length) return { ok: false, errors };
  if (!stripeConfigured()) {
    return { ok: false, provider: "stripe", status: "provider_not_configured", errors: ["STRIPE_SECRET_KEY is not configured."] };
  }
  const siteUrl = (process.env.PUBLIC_SITE_URL || "https://censoredexpressions.com").replace(/\/$/, "");
  const orderId = `order_${Date.now()}_${Math.random().toString(16).slice(2)}`;
  const order = {
    id: orderId,
    at: new Date().toISOString(),
    status: "pending_checkout",
    provider: "stripe",
    paymentStatus: "unpaid",
    ...item,
    amount: Number((item.amountCents * item.quantity / 100).toFixed(2)),
    region: merchRegionFromLocation(item.location, request)
  };
  saveMerchOrder(order);
  const params = stripeFormEncode({
    mode: "payment",
    success_url: `${siteUrl}/merch.html?checkout=success&order=${encodeURIComponent(orderId)}`,
    cancel_url: `${siteUrl}/merch.html?checkout=cancel&order=${encodeURIComponent(orderId)}`,
    customer_email: item.email || undefined,
    "line_items[0][quantity]": item.quantity,
    "line_items[0][price_data][currency]": process.env.STRIPE_CURRENCY || "usd",
    "line_items[0][price_data][unit_amount]": item.amountCents,
    "line_items[0][price_data][product_data][name]": item.product,
    "line_items[0][price_data][product_data][description]": `${item.size} / ${item.color}`,
    "metadata[orderId]": orderId,
    "metadata[product]": item.product,
    "metadata[sku]": item.sku,
    "metadata[size]": item.size,
    "metadata[color]": item.color,
    "metadata[location]": item.location
  });
  const stripeResponse = await fetch("https://api.stripe.com/v1/checkout/sessions", {
    method: "POST",
    headers: {
      authorization: `Bearer ${process.env.STRIPE_SECRET_KEY}`,
      "content-type": "application/x-www-form-urlencoded"
    },
    body: params
  });
  const payload = await stripeResponse.json().catch(() => ({}));
  if (!stripeResponse.ok) {
    saveMerchOrder({ ...order, status: "checkout_failed", providerError: payload.error?.message || "Stripe checkout failed.", updatedAt: new Date().toISOString() });
    return { ok: false, provider: "stripe", status: "checkout_failed", errors: [payload.error?.message || "Stripe checkout failed."] };
  }
  saveMerchOrder({
    ...order,
    checkoutSessionId: payload.id,
    checkoutUrl: payload.url,
    status: "checkout_created",
    updatedAt: new Date().toISOString()
  });
  return { ok: true, provider: "stripe", orderId, checkoutSessionId: payload.id, checkoutUrl: payload.url };
}

function verifyStripeSignature(rawBody, signatureHeader = "", secret = "") {
  if (!secret || !signatureHeader) return false;
  const parts = signatureHeader.split(",").map(part => {
    const [key, value] = part.split("=");
    return { key, value };
  });
  const timestamp = parts.find(part => part.key === "t")?.value;
  const signatures = parts.filter(part => part.key === "v1" && part.value).map(part => part.value);
  if (!timestamp || !signatures.length) return false;
  const payload = `${timestamp}.${rawBody.toString("utf8")}`;
  const expected = crypto.createHmac("sha256", secret).update(payload).digest("hex");
  const expectedBuffer = Buffer.from(expected, "hex");
  return signatures.some(signature => {
    const actualBuffer = Buffer.from(signature, "hex");
    return expectedBuffer.length === actualBuffer.length && crypto.timingSafeEqual(expectedBuffer, actualBuffer);
  });
}

function confirmPaidMerchOrder(session = {}, request = null) {
  const metadata = session.metadata || {};
  const orders = readMerchOrders(5000);
  const existing = orders.find(order => order.id === metadata.orderId || order.checkoutSessionId === session.id) || {};
  const amount = Number(session.amount_total || existing.amountCents || 0) / 100;
  const quantity = Number(existing.quantity || 1);
  const order = {
    ...existing,
    id: existing.id || metadata.orderId || `order_${Date.now()}`,
    checkoutSessionId: session.id,
    status: "paid",
    paymentStatus: session.payment_status || "paid",
    paidAt: new Date().toISOString(),
    amount: Number(amount.toFixed(2)),
    customerEmail: session.customer_details?.email || session.customer_email || existing.email || "",
    updatedAt: new Date().toISOString()
  };
  saveMerchOrder(order);
  return recordMerchEvent({
    eventType: "sale",
    productId: order.productId,
    sku: order.sku || metadata.sku,
    product: order.product || metadata.product,
    category: order.category,
    size: order.size || metadata.size,
    color: order.color || metadata.color,
    quantity,
    amount: order.amount,
    email: order.customerEmail,
    location: order.location || metadata.location || order.region,
    source: "stripe-webhook"
  }, request);
}

function readAdaptiveWeightProofLog(limit = 50) {
  const log = readJsonFile(adaptiveWeightProofFile, []);
  return Array.isArray(log) ? log.slice(-limit) : [];
}

function causalImprovementChain(input = {}) {
  const weightChange = String(input.weightChange || input.weightChangeSummary || "").trim();
  const selectedPath = String(input.selectedPath || input.optimizationPath || input.decisionPath || "").trim();
  const measuredResult = String(input.measuredResult || input.result || input.metricResult || "").trim();
  const verification = String(input.verification || input.verifiedBy || "").trim();
  const chain = [
    {
      step: "weight-change",
      label: "Weight adjustment",
      value: weightChange || "No weight movement; signal was recorded or saturated."
    },
    {
      step: "path-selection",
      label: "Optimization path selected",
      value: selectedPath || "Framework kept the current path or moved to monitoring."
    },
    {
      step: "measured-result",
      label: "Measured result",
      value: measuredResult || "Result metric pending future verification."
    },
    {
      step: "verification",
      label: "Verification",
      value: verification || "Verification not complete yet."
    }
  ];
  return {
    chain,
    summary: chain.map(item => item.value).join(" -> ")
  };
}

function metricImprovementAssessment(beforeMetric = {}, afterMetric = {}) {
  const checks = [];
  const numericCheck = (key, label, lowerIsBetter = true) => {
    const before = Number(beforeMetric?.[key]);
    const after = Number(afterMetric?.[key]);
    if (!Number.isFinite(before) || !Number.isFinite(after)) return;
    const delta = Number((after - before).toFixed(3));
    const improved = lowerIsBetter ? after < before : after > before;
    checks.push({ key, label, before, after, delta, improved });
  };
  numericCheck("lastRefreshMs", "Feed refresh latency", true);
  numericCheck("apiNewsMs", "Public news API latency", true);
  numericCheck("newsPayloadBytes", "News payload size", true);
  numericCheck("consecutiveRefreshFailures", "Consecutive refresh failures", true);
  numericCheck("storyCount", "Available public stories", false);
  numericCheck("findingCount", "High-priority findings captured", false);
  if (beforeMetric?.status === "fallback" && afterMetric?.status && afterMetric.status !== "fallback") {
    checks.push({ key: "status", label: "Feed status", before: beforeMetric.status, after: afterMetric.status, delta: 0, improved: true });
  }
  if (beforeMetric?.hadDiagnostics === true && afterMetric?.hadDiagnostics === false) {
    checks.push({ key: "diagnosticsCache", label: "Stale diagnostics cache", before: "present", after: "cleared", delta: 0, improved: true });
  }
  if (Array.isArray(afterMetric?.lessonEvidence) && afterMetric.lessonEvidence.length) {
    checks.push({ key: "lessonEvidence", label: "Reusable diagnostic lessons", before: beforeMetric?.findingCount || 0, after: afterMetric.lessonEvidence.length, delta: afterMetric.lessonEvidence.length, improved: true });
  }
  const improvedChecks = checks.filter(check => check.improved);
  return {
    metricImproved: improvedChecks.length > 0,
    improvedCheckCount: improvedChecks.length,
    checkedMetricCount: checks.length,
    checks,
    summary: improvedChecks.length
      ? improvedChecks.map(check => `${check.label}: ${check.before} -> ${check.after}`).join("; ")
      : "No measurable improvement has been confirmed yet."
  };
}

function preventionMemoryForAction(entry = {}) {
  const key = String(entry.actionKey || entry.type || "").toLowerCase();
  if (key.includes("refresh-news-cache")) return "When feed latency, fallback status, or refresh failures appear again, attempt a bounded feed refresh before waiting for owner intervention.";
  if (key.includes("warm-public-news-payload")) return "When visitor-facing news API latency or payload readiness degrades, warm the public payload and verify story count, payload size, and runtime freshness.";
  if (key.includes("clear-diagnostics-cache")) return "When diagnostics may be stale, clear diagnostic cache and force the next health check to measure current runtime state.";
  if (key.includes("retry-creator-desk")) return "When Creator Desk is pending or retrying, trigger the scheduler and verify whether editorial generation resumes.";
  if (key.includes("save-diagnostic-lessons")) return "When high-priority diagnostics recur, convert them into reusable lessons so future cycles prioritize the same class of issue sooner.";
  return "Reuse this action only when the same trigger appears, then verify the before/after metric before considering it successful.";
}

function autonomousProofChain(entry = {}) {
  const improvement = entry.improvementAssessment || metricImprovementAssessment(entry.beforeMetric || {}, entry.afterMetric || {});
  const preventionMemory = entry.preventionMemory || preventionMemoryForAction(entry);
  const chain = [
    {
      step: "issue-detected",
      label: "Issue detected",
      value: entry.issueDetected || entry.reason || entry.message || "The Framework detected a site optimization signal."
    },
    {
      step: "solution-chosen",
      label: "Framework chooses solution",
      value: entry.solutionChosen || `${entry.actionKey || entry.type || "bounded-action"} selected from the autonomous action whitelist.`
    },
    {
      step: "change-made",
      label: "Framework makes change",
      value: entry.changeMade || entry.message || `Action completed with status ${entry.status || "unknown"}.`
    },
    {
      step: "metric-improves",
      label: "Metric improves",
      value: improvement.summary
    },
    {
      step: "verification",
      label: "Framework verifies improvement",
      value: entry.verified
        ? `Verified by action result: ${entry.status || "verified"}.`
        : "Verification is pending or the action was blocked/failed."
    },
    {
      step: "prevention-memory",
      label: "Prevention memory",
      value: preventionMemory
    }
  ];
  return {
    metricImproved: improvement.metricImproved,
    improvement,
    preventionMemory,
    chain,
    summary: chain.map(item => item.value).join(" -> ")
  };
}

function saveAdaptiveWeightProofEntry(entry = {}) {
  const log = readAdaptiveWeightProofLog(500);
  const enriched = {
    ...entry,
    causalChain: entry.causalChain || causalImprovementChain(entry.causalInput || entry)
  };
  writeJsonFile(adaptiveWeightProofFile, [...log, enriched].slice(-500));
  return enriched;
}

function readFrameworkLearningProofLog(limit = 80) {
  const log = readJsonFile(frameworkLearningProofFile, []);
  return Array.isArray(log) ? log.slice(-limit) : [];
}

function frameworkProofInterventionTrend(log = readFrameworkLearningProofLog(500)) {
  const cycles = log.filter(entry => entry.category === "procedural-memory" || entry.category === "teach-then-execute");
  const recent = cycles.slice(-20);
  const prior = cycles.slice(-40, -20);
  const interventionRate = items => {
    if (!items.length) return null;
    const total = items.reduce((sum, item) => sum + Number(item.codexInterventionLevel || 0), 0);
    return Number((total / items.length).toFixed(2));
  };
  const recentRate = interventionRate(recent);
  const priorRate = interventionRate(prior);
  return {
    recentInterventionLevel: recentRate,
    priorInterventionLevel: priorRate,
    improving: recentRate !== null && priorRate !== null ? recentRate < priorRate : null,
    interpretation: recentRate === null
      ? "Not enough procedural-memory proof entries yet."
      : priorRate === null
        ? "Baseline is forming; future cycles will show whether intervention decreases."
        : recentRate < priorRate
          ? "Procedural memory is reducing Codex intervention."
          : "Procedural memory has not yet reduced Codex intervention."
  };
}

function saveFrameworkLearningProofEntry(entry = {}) {
  const log = readFrameworkLearningProofLog(500);
  const enriched = {
    at: entry.at || new Date().toISOString(),
    category: entry.category || "framework-learning",
    event: entry.event || "Framework learning event",
    plainEnglish: entry.plainEnglish || entry.summary || "Framework learning proof entry saved.",
    realWorldData: entry.realWorldData || {},
    decisionMeasurement: entry.decisionMeasurement || {},
    teachThenExecute: entry.teachThenExecute || {},
    proceduralMemory: entry.proceduralMemory || {},
    codexInterventionLevel: Number(entry.codexInterventionLevel ?? 0),
    resultMetric: entry.resultMetric || {},
    causalChain: entry.causalChain || causalImprovementChain(entry.causalInput || entry),
    autonomousProofChain: entry.autonomousProofChain || null,
    preventionMemory: entry.preventionMemory || "",
    evidence: normalizeStringList(entry.evidence, 16),
    tags: normalizeStringList(entry.tags, 16)
  };
  const nextLog = [...log, enriched].slice(-500);
  writeJsonFile(frameworkLearningProofFile, nextLog);
  return enriched;
}

function frameworkLearningProofSummary(limit = 20) {
  const log = readFrameworkLearningProofLog(limit);
  const all = readFrameworkLearningProofLog(500);
  const counts = all.reduce((items, entry) => {
    const key = entry.category || "framework-learning";
    items[key] = Number(items[key] || 0) + 1;
    return items;
  }, {});
  return {
    generatedAt: new Date().toISOString(),
    purpose: "Plain-English proof that the Framework is collecting real-world data, measuring decisions, logging teach-then-execute cycles, and tracking whether procedural memory reduces future Codex intervention.",
    counts: Object.entries(counts).map(([category, count]) => ({ category, count })),
    interventionTrend: frameworkProofInterventionTrend(all),
    recentEntries: log.slice(-limit).reverse()
  };
}

function frameworkActionLogSummary(limit = 20) {
  const log = readJsonFile(frameworkActionLogFile, []);
  const all = (Array.isArray(log) ? log : []).map(entry => {
    if (entry.autonomousProofChain && entry.improvementAssessment && entry.preventionMemory) return entry;
    const improvementAssessment = metricImprovementAssessment(entry.beforeMetric || {}, entry.afterMetric || {});
    const proofChain = autonomousProofChain({ ...entry, improvementAssessment });
    return {
      ...entry,
      improvementAssessment,
      whyImprovement: entry.whyImprovement || (improvementAssessment.metricImproved
        ? `The action improved measured site behavior: ${improvementAssessment.summary}`
        : "The action did not yet prove a metric improvement, so future cycles should verify again before treating it as resolved."),
      preventionMemory: entry.preventionMemory || proofChain.preventionMemory,
      autonomousProofChain: proofChain
    };
  });
  const recent = all.slice(-limit).reverse();
  const autonomous = all.filter(entry => entry.autonomous);
  const verified = all.filter(entry => entry.verified);
  const improved = all.filter(entry => entry.improvementAssessment?.metricImproved || entry.autonomousProofChain?.metricImproved);
  return {
    generatedAt: new Date().toISOString(),
    purpose: "Proof that the Framework is executing bounded, reversible, verified optimization actions instead of only monitoring issues.",
    requiredProofChain: "Issue detected -> Framework chooses solution -> Framework makes change -> Metric improves -> Framework verifies improvement -> Prevention memory saved.",
    totals: {
      actionCount: all.length,
      autonomousActionCount: autonomous.length,
      verifiedActionCount: verified.length,
      metricImprovedActionCount: improved.length,
      blockedActionCount: all.filter(entry => /blocked/.test(String(entry.status || ""))).length
    },
    recentActions: recent
  };
}

function readPatchProposals(limit = 50) {
  const proposals = readJsonFile(frameworkPatchProposalFile, []);
  return (Array.isArray(proposals) ? proposals : []).slice(-limit).reverse().map(patchProposalWithDirection);
}

function safeFileSlug(value = "") {
  return String(value || "record")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/(^-|-$)/g, "")
    .slice(0, 90) || "record";
}

function writePatchDecisionRecord(proposal = {}, decision = "approved", ownerNote = "") {
  ensureDataFiles();
  const approved = decision === "approved";
  const folder = approved ? frameworkPatchApprovedDir : frameworkPatchDeniedDir;
  const decidedAt = proposal.ownerDecisionAt || new Date().toISOString();
  const fileName = `${decidedAt.replace(/[:.]/g, "-")}-${safeFileSlug(proposal.title || proposal.id)}.json`;
  const recordPath = path.join(folder, fileName);
  const record = {
    decision,
    decidedAt,
    proposalId: proposal.id || "",
    status: proposal.status || "",
    title: proposal.title || "",
    laymanDescription: proposal.laymanDescription || "",
    rootCause: proposal.rootCause || "",
    proposedFix: proposal.proposedFix || "",
    affectedFiles: proposal.affectedFiles || [],
    riskLevel: proposal.riskLevel || "",
    ownerNote,
    verificationPlan: proposal.verificationPlan || [],
    rollbackPlan: proposal.rollbackPlan || "",
    nextStep: proposal.nextStep || "",
    filePatches: proposal.filePatches || [],
    applyMode: proposal.applyMode || ""
  };
  fs.writeFileSync(recordPath, `${JSON.stringify(record, null, 2)}\n`);
  return path.relative(dataDir, recordPath).replace(/\\/g, "/");
}

function patchDirectionMarkdown(proposal = {}) {
  const list = values => (Array.isArray(values) && values.length)
    ? values.map(value => `- ${String(value || "").trim()}`).join("\n")
    : "- Not provided";
  const patchOps = normalizePatchOperations(proposal.filePatches || proposal.patchOperations || []);
  const structured = patchOps.length
    ? `\n\n## Structured Patch Operations\n\`\`\`json\n${JSON.stringify(patchOps, null, 2)}\n\`\`\``
    : "";
  return [
    "# Codex Teaching Direction",
    "",
    `Patch ID: ${proposal.id || "unknown"}`,
    `Status: ${proposal.status || "unknown"}`,
    `Risk: ${proposal.riskLevel || "medium"}`,
    "",
    "## Owner Intent",
    "The AI Framework/Brain could not complete this safely on its own, or needs Codex teaching before it can execute this pattern independently in the future. Teach the Framework the missing method, then make the smallest safe code change needed.",
    "",
    "## Title",
    proposal.title || "Framework patch request",
    "",
    "## Plain-English Summary",
    proposal.laymanDescription || "No layman summary supplied.",
    "",
    "## Root Cause",
    proposal.rootCause || "No root cause supplied.",
    "",
    "## Requested Fix",
    proposal.proposedFix || proposal.proposedPatch || "No proposed fix supplied.",
    "",
    "## Affected Files",
    list(proposal.affectedFiles || []),
    "",
    "## Verification Required",
    list(proposal.verificationPlan || []),
    "",
    "## Rollback",
    proposal.rollbackPlan || "Revert only the files changed for this patch.",
    "",
    "## Framework Learning Requirement",
    proposal.codexInstruction || "After the fix, save a reusable lesson explaining the exact file path, exact patch operation, verification, and when the Brain should use this pattern again.",
    structured,
    "",
    "## Expected Codex Response",
    "1. Explain why the Brain could not complete the patch, if applicable.",
    "2. Apply or teach the exact structured patch operation.",
    "3. Run the listed verification checks.",
    "4. Record what the Framework should learn so future similar patches can be applied by the Brain after owner approval."
  ].join("\n");
}

function writePatchDirectionFile(proposal = {}) {
  ensureDataFiles();
  const stamp = String(proposal.updatedAt || proposal.ownerDecisionAt || proposal.at || new Date().toISOString()).replace(/[:.]/g, "-");
  const fileName = `${stamp}-${safeFileSlug(proposal.title || proposal.id || "patch-direction")}.md`;
  const absolute = path.join(frameworkPatchDirectionDir, fileName);
  fs.writeFileSync(absolute, `${patchDirectionMarkdown(proposal)}\n`);
  return path.relative(dataDir, absolute).replace(/\\/g, "/");
}

function patchProposalWithDirection(proposal = {}) {
  const codexDirection = proposal.codexDirection || patchDirectionMarkdown(proposal);
  const codexDirectionFile = proposal.codexDirectionFile || writePatchDirectionFile({ ...proposal, codexDirection });
  return { ...proposal, codexDirection, codexDirectionFile };
}

function normalizePatchOperations(input = []) {
  const raw = Array.isArray(input) ? input : [];
  return raw.slice(0, 25).map(item => ({
    action: String(item.action || item.type || (item.deleteFile ? "deleteFile" : item.createFile ? "createFile" : "replace")).trim() || "replace",
    filePath: String(item.filePath || item.path || "").replace(/\\/g, "/").trim(),
    find: String(item.find || item.oldText || item.before || ""),
    replace: String(item.replace ?? item.newText ?? item.after ?? item.content ?? ""),
    occurrence: String(item.occurrence || "first").toLowerCase() === "all" ? "all" : "first",
    description: String(item.description || "").trim()
  })).filter(item => {
    const action = item.action.toLowerCase();
    if (!item.filePath) return false;
    if (["create", "createfile", "write", "writefile", "deletefile", "removefile"].includes(action)) return true;
    return Boolean(item.find);
  });
}

function parseStructuredPatchText(value = "") {
  const source = String(value || "").trim();
  if (!source) return [];
  const candidates = [
    source,
    source.replace(/^```(?:json|javascript|js)?\s*/i, "").replace(/```$/i, "").trim()
  ];
  const arrayMatch = source.match(/\[[\s\S]*\]/);
  const objectMatch = source.match(/\{[\s\S]*\}/);
  if (arrayMatch) candidates.push(arrayMatch[0]);
  if (objectMatch) candidates.push(objectMatch[0]);
  for (const candidate of candidates) {
    try {
      const parsed = JSON.parse(candidate);
      if (Array.isArray(parsed)) return normalizePatchOperations(parsed);
      if (parsed && typeof parsed === "object") {
        return normalizePatchOperations(parsed.filePatches || parsed.patchOperations || parsed.operations || [parsed]);
      }
    } catch (error) {
      // Keep checking other possible structured blocks.
    }
  }
  const blockMatch = source.match(/FILE:\s*([^\n]+)\n+FIND:\s*([\s\S]*?)\n+REPLACE:\s*([\s\S]*)/i);
  if (blockMatch) {
    return normalizePatchOperations([{
      action: "replace",
      filePath: blockMatch[1].trim(),
      find: blockMatch[2].trim(),
      replace: blockMatch[3].trim(),
      description: "Structured from FILE/FIND/REPLACE teaching block."
    }]);
  }
  return [];
}

function extractBrainStructuredPatchOperations(input = {}) {
  const direct = normalizePatchOperations(input.filePatches || input.patchOperations || input.fileUpdates || input.operations);
  if (direct.length) return direct;
  const textFields = [
    input.proposedPatch,
    input.structuredPatch,
    input.patchJson,
    input.codexInstruction,
    Array.isArray(input.patchPlan) ? input.patchPlan.join("\n") : input.patchPlan
  ];
  for (const field of textFields) {
    const parsed = parseStructuredPatchText(field);
    if (parsed.length) return parsed;
  }
  return [];
}

function patchStructuringTeachingContent(input = {}) {
  const title = String(input.title || "Framework patch teaching").trim();
  const affectedFiles = normalizeStringList(input.affectedFiles || input.files, 12);
  return [
    "# Patch Structuring Teaching Scaffold",
    "",
    `Proposal ID: ${input.id || "pending"}`,
    `Title: ${title}`,
    `Patch Type: ${input.patchType || input.type || "unknown"}`,
    "",
    "## Why This Scaffold Exists",
    "The Brain identified a code-level improvement but did not have enough exact patch information to safely write code. This scaffold turns the vague request into a concrete teaching target instead of repeating the same unstructured proposal.",
    "",
    "## Root Cause",
    input.rootCause || input.problem || "No root cause supplied.",
    "",
    "## Requested Fix",
    input.proposedFix || input.fix || input.summary || "No requested fix supplied.",
    "",
    "## Affected Files",
    affectedFiles.length ? affectedFiles.map(file => `- ${file}`).join("\n") : "- Not provided",
    "",
    "## Required Exact Patch Inputs",
    "- targetFile: exact project-relative file path",
    "- action: replace, delete, createFile, or writeFile",
    "- find: exact text to replace/delete when action is replace/delete",
    "- replace/content: exact replacement text or file content",
    "- verification: exact command or endpoint proving the fix worked",
    "",
    "## Reusable Brain Rule",
    "For broad subsystem-code-revision requests, Patch Structuring must either match a known safe pattern or create this teaching scaffold. It should not keep asking the owner for the same vague approval without exact file operations.",
    "",
    "## Next Codex Teaching Step",
    "Codex should fill in the exact operation, apply the smallest safe code change, verify it, and save the resulting filePatches pattern so the Brain can apply similar owner-approved work later."
  ].join("\n");
}

function inferAffectedFilesFromDirection(text = "", target = "") {
  const haystack = `${text} ${target}`.toLowerCase();
  const files = new Set();
  if (/owner desk|learner|approval|patch request|brain state|roadmap|subsystem/.test(haystack)) {
    files.add("owner-desk.html");
    files.add("owner-desk.js");
    files.add("styles.css");
    files.add("server.js");
  }
  if (/server|api|endpoint|brain|framework|patch|subsystem|learning|health|feed|search|deploy/.test(haystack)) files.add("server.js");
  if (/style|layout|button|graph|card|mobile|visual|css/.test(haystack)) files.add("styles.css");
  if (/home page|front page|feed|search bar|tile|ticker/.test(haystack)) {
    files.add("index.html");
    files.add("app.js");
  }
  if (/creator|editorial|blog|comment/.test(haystack)) {
    files.add("creator-desk.html");
    files.add("creator-desk.js");
    files.add("server.js");
  }
  if (/newsletter/.test(haystack)) {
    files.add("newsletter.html");
    files.add("newsletter.js");
    files.add("server.js");
  }
  if (/service worker|offline|cache/.test(haystack)) files.add("sw.js");
  return [...files].slice(0, 12);
}

function parseLaymanPatchInstruction(input = {}) {
  const direction = String(input.direction || input.instruction || input.note || "").trim();
  const targetFile = String(input.targetFile || input.filePath || "").replace(/\\/g, "/").trim();
  const text = direction.replace(/\r\n/g, "\n");
  const replaceBlock = text.match(/(?:replace|change)\s+in\s+([^\n:]+):\s*([\s\S]*?)\s*(?:->|=>|with)\s*([\s\S]*)/i);
  if (replaceBlock) {
    return normalizePatchOperations([{
      action: "replace",
      filePath: replaceBlock[1].trim(),
      find: replaceBlock[2].trim(),
      replace: replaceBlock[3].trim(),
      description: "Parsed from layman replace instruction."
    }]);
  }
  const createBlock = text.match(/(?:create|add)\s+(?:a\s+)?(?:new\s+)?file\s+([^\n:]+):\s*([\s\S]*)/i);
  if (createBlock) {
    return normalizePatchOperations([{
      action: "createFile",
      filePath: createBlock[1].trim(),
      content: createBlock[2].trim(),
      description: "Parsed from layman create-file instruction."
    }]);
  }
  const writeBlock = text.match(/(?:write|overwrite)\s+(?:file\s+)?([^\n:]+):\s*([\s\S]*)/i);
  if (writeBlock) {
    return normalizePatchOperations([{
      action: "writeFile",
      filePath: writeBlock[1].trim(),
      content: writeBlock[2].trim(),
      description: "Parsed from layman write-file instruction."
    }]);
  }
  const deleteBlock = text.match(/(?:delete|remove)\s+(?:file\s+)?([^\s]+(?:\.(?:js|html|css|md|json|txt|webmanifest|ps1|bat)))/i);
  if (deleteBlock) {
    return normalizePatchOperations([{
      action: "deleteFile",
      filePath: deleteBlock[1].trim(),
      description: "Parsed from layman delete-file instruction."
    }]);
  }
  if (targetFile && input.find && (input.replace || input.newText)) {
    return normalizePatchOperations([{
      action: "replace",
      filePath: targetFile,
      find: input.find,
      replace: input.replace || input.newText,
      description: "Parsed from owner exact fields."
    }]);
  }
  return [];
}

function patchStructuringSubsystem(input = {}) {
  const existing = extractBrainStructuredPatchOperations(input);
  if (existing.length) {
    return {
      structured: true,
      source: "provided-or-parsed-structured-operations",
      filePatches: existing,
      confidence: 0.96,
      notes: ["Proposal already included, or could be parsed into, structured patch operations."]
    };
  }

  const patchType = String(input.patchType || input.type || "").trim().toLowerCase();
  const title = String(input.title || "").trim();
  const proposedFix = String(input.proposedFix || input.fix || input.summary || "").trim();
  const rootCause = String(input.rootCause || input.problem || "").trim();
  const targetFile = String(input.targetFile || input.filePath || input.path || "").replace(/\\/g, "/").trim();
  const find = String(input.find || input.oldText || input.before || "").trim();
  const replace = String(input.replace ?? input.newText ?? input.after ?? "").trim();
  const content = String(input.content ?? input.fileContent ?? "").trim();
  const haystack = `${patchType} ${title} ${proposedFix} ${rootCause}`.toLowerCase();

  if (targetFile && find && (replace || /delete|remove/.test(haystack))) {
    return {
      structured: true,
      source: "exact-text-instruction",
      filePatches: normalizePatchOperations([{
        action: /delete|remove/.test(haystack) && !replace ? "delete" : "replace",
        filePath: targetFile,
        find,
        replace,
        description: `Structured from exact owner/Brain instruction for ${targetFile}.`
      }]),
      confidence: 0.92,
      notes: ["Converted exact find/replace instruction into filePatches."]
    };
  }

  if (targetFile && content && /create|write|new file|add file/.test(haystack)) {
    return {
      structured: true,
      source: "create-or-write-file-instruction",
      filePatches: normalizePatchOperations([{
        action: /write|overwrite/.test(haystack) ? "writeFile" : "createFile",
        filePath: targetFile,
        content,
        description: `Structured ${/write|overwrite/.test(haystack) ? "write" : "create"} operation for ${targetFile}.`
      }]),
      confidence: 0.9,
      notes: ["Converted target file and content into a structured file operation."]
    };
  }

  if (patchType === "owner-desk-cache-bust" || /owner desk.*cache|cache.*owner desk|cache bust/.test(haystack)) {
    const filePath = "owner-desk.html";
    const absolute = path.join(publicDir, filePath);
    if (fs.existsSync(absolute)) {
      const html = fs.readFileSync(absolute, "utf8");
      const currentMatch = html.match(/owner-desk\.js\?v=([^"]+)/);
      const styleMatch = html.match(/styles\.css\?v=([^"]+)/);
      const nextVersion = String(input.version || `brain-${Date.now()}`).replace(/[^a-z0-9_-]/gi, "-").slice(0, 80);
      const ops = [];
      if (currentMatch) {
        ops.push({
          action: "replace",
          filePath,
          find: `owner-desk.js?v=${currentMatch[1]}`,
          replace: `owner-desk.js?v=${nextVersion}`,
          description: "Cache-bust Owner Desk JavaScript."
        });
      }
      if (styleMatch) {
        ops.push({
          action: "replace",
          filePath,
          find: `styles.css?v=${styleMatch[1]}`,
          replace: `styles.css?v=${nextVersion}`,
          description: "Cache-bust Owner Desk stylesheet."
        });
      }
      const filePatches = normalizePatchOperations(ops);
      if (filePatches.length) {
        return {
          structured: true,
          source: "known-owner-desk-cache-bust-pattern",
          filePatches,
          confidence: 0.86,
          notes: [`Generated Owner Desk cache-bust operations for version ${nextVersion}.`]
        };
      }
    }
  }

  if (patchType === "feed-source-failure-isolation" || /feed.*timeout|source.*failure|one bad source|feed.*crash/.test(haystack)) {
    const serverPath = path.join(publicDir, "server.js");
    const serverText = fs.existsSync(serverPath) ? fs.readFileSync(serverPath, "utf8") : "";
    const alreadySatisfied = /function rememberFeedSourceError/.test(serverText)
      && /async function fetchWithTimeout/.test(serverText)
      && /async function loadFeed\(source\)[\s\S]*?catch \(error\)[\s\S]*?return \[\]/.test(serverText);
    if (alreadySatisfied) {
      return {
        structured: false,
        source: "known-feed-guard-pattern",
        filePatches: [],
        confidence: 0.88,
        alreadySatisfied: true,
        notes: ["Feed source failure isolation already appears present in server.js; do not create another duplicate patch."]
      };
    }
  }

  if (/site performance subsystem|site-performance|performance-proof|health-check.*connectivity-check/i.test(haystack)) {
    const filePath = "server.js";
    const serverPath = path.join(publicDir, filePath);
    const serverText = fs.existsSync(serverPath) ? fs.readFileSync(serverPath, "utf8") : "";
    const oldScoreLine = "const healthScore = Number(diagnostics?.publicHealth?.score || diagnostics?.score || 0);";
    const newScoreLine = "const healthScore = Number(diagnostics?.publicHealth?.score || diagnostics?.score || diagnostics?.aiShield?.score || 0);";
    const hasPerformanceProof = /sitePerformance:\s*\{[\s\S]*?performanceProof:\s*\{/.test(serverText);
    if (serverText.includes(oldScoreLine)) {
      return {
        structured: true,
        source: "known-site-performance-readiness-pattern",
        filePatches: normalizePatchOperations([{
          action: "replace",
          filePath,
          find: oldScoreLine,
          replace: newScoreLine,
          description: "Teach Site Performance readiness to use the actual AI Shield score from diagnostics."
        }]),
        confidence: 0.89,
        notes: ["Generated exact replacement for Site Performance readiness score measurement."]
      };
    }
    if (serverText.includes(newScoreLine) && hasPerformanceProof) {
      return {
        structured: false,
        source: "known-site-performance-readiness-pattern",
        filePatches: [],
        confidence: 0.9,
        alreadySatisfied: true,
        notes: ["Site Performance readiness score and public health performance proof already appear present in server.js."]
      };
    }
  }

  if (patchType === "subsystem-code-revision" || /revise .* subsystem behavior|subsystem readiness|missing capabilities/i.test(haystack)) {
    const subsystemKey = safeFileSlug(input.trigger?.subsystem || title || "subsystem-code-revision");
    return {
      structured: true,
      source: "subsystem-revision-teaching-scaffold",
      filePatches: normalizePatchOperations([{
        action: "createFile",
        filePath: `data/patch-structuring-teachings/${subsystemKey}-${Date.now()}.md`,
        content: patchStructuringTeachingContent(input),
        description: "Create a concrete Patch Structuring teaching scaffold for a broad subsystem revision request."
      }]),
      confidence: 0.72,
      teachingScaffold: true,
      notes: ["Broad subsystem revision request lacked exact file operations; generated a teaching scaffold so the Brain has a concrete artifact instead of repeating a vague proposal."]
    };
  }

  return {
    structured: false,
    source: "patch-structuring-subsystem",
    filePatches: [],
    confidence: 0.35,
    notes: [
      "No safe exact structured patch could be generated from this diagnosis.",
      "The Brain should request teaching with target file, exact find text, replacement text, or create/write file content."
    ],
    teachingNeeded: true
  };
}

function savePatchProposal(input = {}) {
  const proposals = readJsonFile(frameworkPatchProposalFile, []);
  const affectedFiles = normalizeStringList(input.affectedFiles || input.files, 20);
  const structuring = patchStructuringSubsystem(input);
  const filePatches = structuring.filePatches || [];
  const rootCause = String(input.rootCause || input.problem || "").trim();
  const proposedFix = String(input.proposedFix || input.fix || input.summary || "").trim();
  const verificationPlan = normalizeStringList(input.verificationPlan || input.verification || input.tests, 16);
  const rollbackPlan = String(input.rollbackPlan || "Do not apply the patch. Keep current files until owner/Codex approval.").trim();
  const dedupeKey = String(input.dedupeKey || `${input.patchType || "controlled-code-proposal"}:${input.title || proposedFix}:${affectedFiles.join("|")}`).trim();
  const record = {
    id: input.id || `patch_proposal_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    at: new Date().toISOString(),
    status: "pending-owner-approval",
    source: String(input.source || "AI Framework").trim(),
    trigger: input.trigger || {},
    title: String(input.title || proposedFix || "Framework code patch proposal").trim(),
    rootCause,
    dedupeKey,
    proposedFix,
    laymanDescription: String(input.laymanDescription || input.plainEnglish || `The Framework believes this change will fix: ${rootCause || proposedFix || "a detected site issue"}. It is waiting for owner approval before code is changed.`).trim(),
    affectedFiles,
    patchType: String(input.patchType || "controlled-code-proposal").trim(),
    riskLevel: String(input.riskLevel || "medium").trim(),
    ownerApprovalRequired: true,
    applyMode: "proposal-only",
    patchPlan: normalizeStringList(input.patchPlan || input.steps, 20),
    proposedPatch: String(input.proposedPatch || "").trim(),
    filePatches,
    patchStructuring: {
      structured: Boolean(structuring.structured),
      source: structuring.source,
      confidence: structuring.confidence,
      alreadySatisfied: Boolean(structuring.alreadySatisfied),
      teachingNeeded: Boolean(structuring.teachingNeeded),
      notes: structuring.notes || []
    },
    verificationPlan,
    rollbackPlan,
    expectedOutcome: String(input.expectedOutcome || "").trim(),
    resultMetric: input.resultMetric || {},
    codexInstruction: String(input.codexInstruction || (structuring.teachingNeeded
      ? "The Brain could not safely generate structured filePatches from this diagnosis yet. Codex/GitHub should teach the missing exact file path, find text, replacement text, or create/write operation."
      : "After owner approval, the Brain/AI Framework should apply structured patch operations directly. Codex/GitHub is a teaching fallback only when the Brain lacks the structured fix.")).trim(),
    tags: [...new Set([
      ...normalizeStringList(input.tags, 12),
      "patch-proposal",
      "owner-approval-required",
      structuring.structured ? "structured-by-brain" : "needs-patch-structuring",
      structuring.alreadySatisfied ? "already-satisfied" : ""
    ].filter(Boolean))]
  };
  record.codexDirection = patchDirectionMarkdown(record);
  record.codexDirectionFile = writePatchDirectionFile(record);
  const current = Array.isArray(proposals) ? proposals : [];
  const resolvedDuplicateIndex = current.findIndex(item =>
    String(item.dedupeKey || "") === record.dedupeKey
    && ["applied-by-framework", "applied-manually-after-owner-approval", "denied-by-owner"].includes(item.status)
  );
  if (resolvedDuplicateIndex >= 0) {
    const existing = current[resolvedDuplicateIndex];
    const updated = {
      ...existing,
      updatedAt: record.at,
      repeatedAfterResolutionCount: Number(existing.repeatedAfterResolutionCount || 0) + 1,
      repeatedSignal: {
        at: record.at,
        trigger: record.trigger,
        rootCause: record.rootCause,
        proposedFix: record.proposedFix,
        patchStructuring: record.patchStructuring
      },
      nextStep: existing.status === "denied-by-owner"
        ? "A similar proposal was already denied. The Brain should not ask again unless new evidence or a changed fix is supplied."
        : "A similar proposal was already approved/applied. The Brain should verify the existing fix instead of asking for permission again.",
      tags: [...new Set([...(existing.tags || []), "duplicate-suppressed", record.patchStructuring?.alreadySatisfied ? "already-satisfied" : ""])]
    };
    current[resolvedDuplicateIndex] = updated;
    updated.codexDirection = patchDirectionMarkdown(updated);
    updated.codexDirectionFile = writePatchDirectionFile(updated);
    writeJsonFile(frameworkPatchProposalFile, current.slice(-250));
    saveFrameworkLearningProofEntry({
      category: "patch-duplicate-suppressed",
      event: `Duplicate patch suppressed: ${record.title}`,
      plainEnglish: "The Brain tried to create a patch for a fix that was already resolved. The Framework updated the existing record instead of asking the owner again.",
      decisionMeasurement: {
        dedupeKey: record.dedupeKey,
        existingStatus: existing.status,
        repeatedAfterResolutionCount: updated.repeatedAfterResolutionCount
      },
      resultMetric: {
        duplicateSuppressed: true,
        newProposalCreated: false
      },
      evidence: [record.rootCause, record.proposedFix, ...(record.patchStructuring?.notes || [])].filter(Boolean),
      tags: ["patch-proposal", "duplicate-suppressed", "brain-execution-loop"]
    });
    return updated;
  }
  const duplicateIndex = current.findIndex(item => item.status === "pending-owner-approval" && String(item.dedupeKey || "") === record.dedupeKey);
  if (duplicateIndex >= 0) {
    const existing = current[duplicateIndex];
    const updated = {
      ...existing,
      updatedAt: record.at,
      repeatedSignalCount: Number(existing.repeatedSignalCount || 1) + 1,
      trigger: record.trigger,
      resultMetric: record.resultMetric,
      filePatches: record.filePatches.length ? record.filePatches : existing.filePatches,
      patchStructuring: record.patchStructuring?.structured ? record.patchStructuring : existing.patchStructuring || record.patchStructuring,
      verificationPlan: record.verificationPlan.length ? record.verificationPlan : existing.verificationPlan,
      tags: [...new Set([...(existing.tags || []), ...record.tags])]
    };
    updated.codexDirection = patchDirectionMarkdown(updated);
    updated.codexDirectionFile = writePatchDirectionFile(updated);
    current[duplicateIndex] = updated;
    writeJsonFile(frameworkPatchProposalFile, current.slice(-250));
    return updated;
  }
  writeJsonFile(frameworkPatchProposalFile, [...current, record].slice(-250));
  saveFrameworkLearningProofEntry({
    category: "patch-proposal",
    event: `Patch proposal: ${record.title}`,
    plainEnglish: `The Framework identified a root cause and proposed a controlled patch for owner approval. It did not edit code automatically.`,
    realWorldData: {
      trigger: record.trigger,
      affectedFiles: record.affectedFiles,
      rootCause: record.rootCause
    },
    decisionMeasurement: {
      status: record.status,
      ownerApprovalRequired: record.ownerApprovalRequired,
      riskLevel: record.riskLevel,
      affectedFileCount: record.affectedFiles.length,
      structuredByBrain: Boolean(record.patchStructuring?.structured),
      teachingNeeded: Boolean(record.patchStructuring?.teachingNeeded)
    },
    proceduralMemory: {
      patchProposalId: record.id,
      reuseRule: "When diagnostics identify a code-level root cause, the Patch Structuring subsystem should convert it into structured filePatches before owner approval. If it cannot, request teaching instead of creating an unapplyable loop."
    },
    codexInterventionLevel: 2,
    resultMetric: {
      proposalCreated: true,
      affectedFileCount: record.affectedFiles.length,
      verificationStepCount: record.verificationPlan.length,
      structuredPatchCount: record.filePatches.length,
      patchStructuringConfidence: record.patchStructuring?.confidence || 0
    },
    causalInput: {
      weightChange: "Meta Execution selected proposal-only mode because the root cause required code change.",
      selectedPath: record.filePatches.length ? "propose-structured-code-patch" : "request-patch-structuring-teaching",
      measuredResult: `proposal=${record.id}, affectedFiles=${record.affectedFiles.length}, structuredOps=${record.filePatches.length}, status=${record.status}`,
      verification: "Proposal saved to framework-code-patch-proposals.json with patchStructuring metadata and proof log; no code applied without approval."
    },
    evidence: [record.rootCause, record.proposedFix, ...record.verificationPlan].filter(Boolean),
    tags: record.tags
  });
  return record;
}

function updatePatchProposalDecision(input = {}) {
  const proposals = readJsonFile(frameworkPatchProposalFile, []);
  const current = Array.isArray(proposals) ? proposals : [];
  const id = String(input.id || "").trim();
  const decision = String(input.decision || "").trim().toLowerCase();
  const ownerNote = String(input.ownerNote || input.note || "").trim();
  if (!id) throw new Error("Patch proposal id is required.");
  if (!["approve", "approved", "deny", "denied"].includes(decision)) throw new Error("Decision must be approve or deny.");
  const index = current.findIndex(item => item.id === id);
  if (index < 0) throw new Error("Patch proposal was not found.");
  const existing = current[index];
  const approved = decision === "approve" || decision === "approved";
  const decidedAt = new Date().toISOString();
  const status = approved ? "approved-for-framework" : "denied-by-owner";
  const updated = {
    ...existing,
    status,
    ownerDecision: approved ? "approved" : "denied",
    ownerDecisionAt: decidedAt,
    ownerNote,
    applyMode: approved ? "approved-awaiting-framework-apply" : "rejected-no-code-change",
    nextStep: approved
      ? "Owner approved this proposal. If structured filePatches are attached, the Brain/AI Framework may apply it directly, create backups, verify, and log the result. If no structured patch exists, the Brain should request Codex/GitHub teaching only to learn how to create the structured fix."
      : "Owner denied this proposal. Do not apply the patch unless a new proposal is created and approved.",
    tags: [...new Set([...(existing.tags || []), approved ? "owner-approved" : "owner-denied"])]
  };
  const decisionRecordPath = writePatchDecisionRecord(updated, updated.ownerDecision, ownerNote);
  updated.decisionRecordPath = decisionRecordPath;
  updated.codexDirection = patchDirectionMarkdown(updated);
  updated.codexDirectionFile = writePatchDirectionFile(updated);
  current[index] = updated;
  writeJsonFile(frameworkPatchProposalFile, current.slice(-250));
  saveFrameworkLearningProofEntry({
    category: "patch-proposal-decision",
    event: `Patch proposal ${approved ? "approved" : "denied"}: ${existing.title || id}`,
    plainEnglish: approved
      ? "The owner reviewed the Framework's plain-English patch proposal and approved it for controlled Brain/AI Framework application. The code is not changed until the apply step runs."
      : "The owner reviewed the Framework's patch proposal and denied it. The Framework preserved the decision and will not treat this patch as approved.",
    realWorldData: {
      proposalId: id,
      status,
      title: existing.title || "",
      affectedFiles: existing.affectedFiles || [],
      ownerNote,
      decisionRecordPath
    },
    decisionMeasurement: {
      ownerDecision: updated.ownerDecision,
      ownerApprovalRequired: true,
      applyMode: updated.applyMode,
      riskLevel: existing.riskLevel || "medium"
    },
    proceduralMemory: {
      reuseRule: "Patch proposals must be visible in the Learners Desk with plain-English impact, affected files, verification, rollback, and owner approve/deny decision before code changes are applied."
    },
    resultMetric: {
      proposalDecisionRecorded: true,
      approved,
      codeChangedByFramework: false,
      decisionRecordWritten: true
    },
    evidence: [existing.rootCause, existing.proposedFix, ownerNote].filter(Boolean),
    tags: ["patch-proposal", "owner-decision", approved ? "owner-approved" : "owner-denied"]
  });
  return updated;
}

function markPatchProposalManuallyApplied(input = {}) {
  const proposals = readJsonFile(frameworkPatchProposalFile, []);
  const current = Array.isArray(proposals) ? proposals : [];
  const id = String(input.id || "").trim();
  const ownerNote = String(input.ownerNote || input.note || "").trim();
  if (!id) throw new Error("Patch proposal id is required.");
  const index = current.findIndex(item => item.id === id);
  if (index < 0) throw new Error("Patch proposal was not found.");
  const existing = current[index];
  if (!["approved-for-framework", "approved-for-codex", "applied-by-framework"].includes(existing.status)) {
    throw new Error("Only approved or already-applied proposals can be marked manually applied.");
  }
  const appliedAt = new Date().toISOString();
  const updated = {
    ...existing,
    status: "applied-manually-after-owner-approval",
    appliedAt,
    appliedBy: "Brain/AI Framework, Codex/GitHub teaching fallback, or manual workflow after owner approval",
    ownerNote: ownerNote || existing.ownerNote || "",
    applyMode: "owner-approved-manual-application-recorded",
    applyResult: {
      ok: true,
      manual: true,
      changedFiles: existing.affectedFiles || [],
      verificationPlan: existing.verificationPlan || []
    },
    nextStep: "Manual application was recorded. Run or confirm the verification checks, then keep the proposal as proof memory."
  };
  current[index] = updated;
  writeJsonFile(frameworkPatchProposalFile, current.slice(-250));
  saveFrameworkLearningProofEntry({
    category: "patch-applied-manually",
    event: `Owner-approved patch marked applied: ${existing.title || id}`,
    plainEnglish: "The owner recorded that an approved patch was applied outside the Framework's structured apply lane. The Framework saved the decision as proof and will stop showing it as waiting for application.",
    realWorldData: {
      proposalId: id,
      title: existing.title || "",
      affectedFiles: existing.affectedFiles || [],
      ownerNote
    },
    decisionMeasurement: {
      ownerDecision: "approved",
      applyMode: updated.applyMode,
      frameworkAppliedCode: false,
      manualApplicationRecorded: true
    },
    proceduralMemory: {
      reuseRule: "When older approved proposals lack structured filePatches but have already been applied, mark them manually applied so the approval queue reflects reality. Future proposals should teach the Brain to create structured filePatches."
    },
    resultMetric: {
      manualApplicationRecorded: true,
      changedFileCount: (existing.affectedFiles || []).length
    },
    evidence: [existing.rootCause, existing.proposedFix, ownerNote].filter(Boolean),
    tags: ["patch-proposal", "owner-approved", "manual-application", "proof-memory"]
  });
  return updated;
}

function safePatchTarget(filePath = "") {
  const clean = String(filePath || "").replace(/\\/g, "/").replace(/^\/+/, "");
  const normalized = path.normalize(clean);
  if (!normalized || normalized.startsWith("..") || path.isAbsolute(normalized)) {
    throw new Error(`Unsafe patch target: ${filePath}`);
  }
  const absolute = path.resolve(publicDir, normalized);
  const relative = path.relative(publicDir, absolute);
  if (relative.startsWith("..") || path.isAbsolute(relative)) {
    throw new Error(`Patch target is outside the project: ${filePath}`);
  }
  const dataRelative = path.relative(dataDir, absolute);
  if (!dataRelative.startsWith("..") && !path.isAbsolute(dataRelative)) {
    const inPatchTeachingDir = !path.relative(frameworkPatchTeachingDir, absolute).startsWith("..") && !path.isAbsolute(path.relative(frameworkPatchTeachingDir, absolute));
    const inPatchDirectionDir = !path.relative(frameworkPatchDirectionDir, absolute).startsWith("..") && !path.isAbsolute(path.relative(frameworkPatchDirectionDir, absolute));
    if (inPatchTeachingDir || inPatchDirectionDir) {
      return { absolute, relative: relative.replace(/\\/g, "/") };
    }
    throw new Error(`Patch target cannot modify private data files: ${filePath}`);
  }
  const blocked = /(^|[\\/])(\.git|node_modules|BACKUPS|patch-backups)([\\/]|$)/i.test(relative);
  if (blocked) throw new Error(`Patch target is blocked: ${filePath}`);
  const allowedExtensions = new Set([".js", ".html", ".css", ".md", ".json", ".webmanifest", ".txt", ".ps1", ".bat"]);
  const ext = path.extname(absolute).toLowerCase();
  if (!allowedExtensions.has(ext)) throw new Error(`Patch target extension is not allowed: ${filePath}`);
  return { absolute, relative: relative.replace(/\\/g, "/") };
}

function applyPatchOperationText(original, operation = {}) {
  const action = String(operation.action || "replace").toLowerCase();
  const find = String(operation.find || "");
  const replace = String(operation.replace || "");
  if (action === "delete" || action === "deletetext" || action === "remove") {
    if (!find) throw new Error("Delete patch operation is missing exact text to remove.");
    if (!original.includes(find)) throw new Error(`Exact delete text was not found in ${operation.filePath}.`);
    if (operation.occurrence === "all") {
      return {
        text: original.split(find).join(""),
        replacements: original.split(find).length - 1
      };
    }
    return {
      text: original.replace(find, ""),
      replacements: 1
    };
  }
  if (!find) throw new Error("Patch operation is missing exact text to find.");
  if (!original.includes(find)) throw new Error(`Exact patch text was not found in ${operation.filePath}.`);
  if (operation.occurrence === "all") {
    return {
      text: original.split(find).join(replace),
      replacements: original.split(find).length - 1
    };
  }
  return {
    text: original.replace(find, replace),
    replacements: 1
  };
}

function verifyChangedPatchFiles(changedFiles = []) {
  const results = [];
  changedFiles.forEach(file => {
    const target = safePatchTarget(file.filePath);
    const exists = fs.existsSync(target.absolute);
    const deleted = file.action === "deleteFile";
    const base = {
      filePath: file.filePath,
      action: file.action || "updateFile",
      exists,
      ok: deleted ? !exists : exists,
      checks: []
    };
    if (deleted) {
      base.checks.push({ name: "file-deleted", ok: !exists });
      results.push(base);
      return;
    }
    if (!exists) {
      base.checks.push({ name: "file-exists", ok: false, message: "Expected changed file to exist after patch." });
      results.push(base);
      return;
    }
    const ext = path.extname(target.absolute).toLowerCase();
    if (ext === ".js") {
      try {
        childProcess.execFileSync(process.execPath, ["--check", target.absolute], {
          cwd: publicDir,
          stdio: "pipe",
          timeout: 15000
        });
        base.checks.push({ name: "node-syntax-check", ok: true });
      } catch (error) {
        base.ok = false;
        base.checks.push({
          name: "node-syntax-check",
          ok: false,
          message: String(error.stderr || error.message || "JavaScript syntax check failed.").slice(0, 800)
        });
      }
    }
    if (ext === ".json" || ext === ".webmanifest") {
      try {
        JSON.parse(fs.readFileSync(target.absolute, "utf8").replace(/^\uFEFF/, ""));
        base.checks.push({ name: "json-parse", ok: true });
      } catch (error) {
        base.ok = false;
        base.checks.push({ name: "json-parse", ok: false, message: error.message || "JSON parse failed." });
      }
    }
    if (!base.checks.length) base.checks.push({ name: "file-exists", ok: true });
    results.push(base);
  });
  return {
    ok: results.every(result => result.ok),
    verifiedAt: new Date().toISOString(),
    results
  };
}

async function runAutonomousDeploymentAfterPatch(proposal = {}, verification = {}) {
  const hookUrl = process.env.RENDER_DEPLOY_HOOK_URL || process.env.DEPLOY_HOOK_URL || "";
  const shouldDeploy = /^(1|true|yes)$/i.test(String(process.env.CE_AUTO_DEPLOY_AFTER_PATCH || ""))
    || Boolean(proposal.deployAfterApply)
    || Boolean(hookUrl);
  if (!shouldDeploy) {
    return {
      attempted: false,
      ok: false,
      status: "not-configured",
      message: "Autonomous deployment did not run because no deployment hook was configured. Set RENDER_DEPLOY_HOOK_URL or DEPLOY_HOOK_URL to let the Brain trigger Render after approved patches.",
      verifiedPatchOk: Boolean(verification.ok)
    };
  }
  if (!hookUrl) {
    return {
      attempted: false,
      ok: false,
      status: "blocked-missing-deploy-hook",
      message: "Deployment was requested, but no deployment hook URL is configured.",
      verifiedPatchOk: Boolean(verification.ok)
    };
  }
  if (!verification.ok) {
    return {
      attempted: false,
      ok: false,
      status: "blocked-failed-verification",
      message: "Deployment was blocked because patch verification failed.",
      verifiedPatchOk: false
    };
  }
  try {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), 15000);
    const response = await fetch(hookUrl, {
      method: "POST",
      headers: { "content-type": "application/json" },
      body: JSON.stringify({
        source: "Censored Expressions AI Framework",
        proposalId: proposal.id || "",
        title: proposal.title || "",
        appliedAt: proposal.appliedAt || new Date().toISOString()
      }),
      signal: controller.signal
    }).finally(() => clearTimeout(timeout));
    return {
      attempted: true,
      ok: response.ok,
      status: response.ok ? "deploy-hook-triggered" : "deploy-hook-failed",
      httpStatus: response.status,
      message: response.ok
        ? "Deployment hook triggered after owner-approved Framework patch."
        : `Deployment hook returned HTTP ${response.status}.`,
      verifiedPatchOk: true
    };
  } catch (error) {
    return {
      attempted: true,
      ok: false,
      status: "deploy-hook-error",
      message: error.message || "Deployment hook request failed.",
      verifiedPatchOk: true
    };
  }
}

async function applyApprovedPatchProposal(input = {}) {
  if (!frameworkPatchApplyEnabled) throw new Error("Framework patch application is disabled by runtime policy.");
  const id = String(input.id || "").trim();
  if (!id) throw new Error("Patch proposal id is required.");
  const proposals = readJsonFile(frameworkPatchProposalFile, []);
  const current = Array.isArray(proposals) ? proposals : [];
  const index = current.findIndex(item => item.id === id);
  if (index < 0) throw new Error("Patch proposal was not found.");
  const proposal = current[index];
  if (!["approved-for-framework", "approved-for-codex"].includes(proposal.status) || proposal.ownerDecision !== "approved") {
    throw new Error("Patch proposal must be approved by the owner before the Framework can apply it.");
  }
  const operations = normalizePatchOperations(proposal.filePatches || proposal.patchOperations || []);
  if (!operations.length) {
    throw new Error("This proposal has no structured filePatches for the Framework to apply. The Brain should learn or request Codex/GitHub teaching to convert it into structured patch operations.");
  }

  const grouped = new Map();
  operations.forEach(operation => {
    const target = safePatchTarget(operation.filePath);
    const action = String(operation.action || "replace").toLowerCase();
    if (["deletefile", "removefile"].includes(action)) {
      grouped.set(`${target.relative}::${operation.action}`, {
        target,
        fileAction: "deleteFile",
        operations: [{ ...operation, filePath: target.relative }],
        original: fs.existsSync(target.absolute) ? fs.readFileSync(target.absolute, "utf8") : ""
      });
      return;
    }
    if (["create", "createfile", "write", "writefile"].includes(action)) {
      grouped.set(`${target.relative}::${operation.action}`, {
        target,
        fileAction: fs.existsSync(target.absolute) ? "writeFile" : "createFile",
        operations: [{ ...operation, filePath: target.relative }],
        original: fs.existsSync(target.absolute) ? fs.readFileSync(target.absolute, "utf8") : ""
      });
      return;
    }
    if (!fs.existsSync(target.absolute)) throw new Error(`Patch target does not exist: ${target.relative}`);
    const existing = grouped.get(target.relative) || {
      target,
      fileAction: "updateFile",
      operations: [],
      original: fs.readFileSync(target.absolute, "utf8")
    };
    existing.operations.push({ ...operation, filePath: target.relative });
    grouped.set(target.relative, existing);
  });

  const prepared = [];
  grouped.forEach(item => {
    if (item.fileAction === "deleteFile") {
      if (!fs.existsSync(item.target.absolute)) throw new Error(`Cannot delete missing patch target: ${item.target.relative}`);
      prepared.push({ ...item, nextText: "", operationResults: [{ filePath: item.target.relative, description: item.operations[0]?.description || "Delete approved file", occurrence: "file", replacements: 1 }] });
      return;
    }
    if (item.fileAction === "createFile" || item.fileAction === "writeFile") {
      const content = String(item.operations[0]?.replace || "");
      if (item.fileAction === "createFile" && fs.existsSync(item.target.absolute)) throw new Error(`Cannot create file because it already exists: ${item.target.relative}`);
      if (item.fileAction === "writeFile" && content === item.original) throw new Error(`Patch would not change ${item.target.relative}.`);
      prepared.push({ ...item, nextText: content, operationResults: [{ filePath: item.target.relative, description: item.operations[0]?.description || item.fileAction, occurrence: "file", replacements: 1 }] });
      return;
    }
    let nextText = item.original;
    const operationResults = [];
    item.operations.forEach(operation => {
      const result = applyPatchOperationText(nextText, operation);
      nextText = result.text;
      operationResults.push({
        filePath: item.target.relative,
        description: operation.description || "",
        occurrence: operation.occurrence,
        replacements: result.replacements
      });
    });
    if (nextText === item.original) throw new Error(`Patch would not change ${item.target.relative}.`);
    prepared.push({ ...item, nextText, operationResults });
  });

  const appliedAt = new Date().toISOString();
  const backupRoot = path.join(frameworkPatchBackupDir, `${id}-${Date.now()}`);
  fs.mkdirSync(backupRoot, { recursive: true });
  const changedFiles = [];
  prepared.forEach(item => {
    const backupPath = path.join(backupRoot, item.target.relative);
    fs.mkdirSync(path.dirname(backupPath), { recursive: true });
    if (fs.existsSync(item.target.absolute)) fs.copyFileSync(item.target.absolute, backupPath);
    if (item.fileAction === "deleteFile") {
      fs.unlinkSync(item.target.absolute);
    } else {
      fs.mkdirSync(path.dirname(item.target.absolute), { recursive: true });
      fs.writeFileSync(item.target.absolute, item.nextText);
    }
    changedFiles.push({
      filePath: item.target.relative,
      action: item.fileAction || "updateFile",
      backupPath: fs.existsSync(backupPath) ? path.relative(dataDir, backupPath).replace(/\\/g, "/") : "",
      operationCount: item.operations.length,
      replacements: item.operationResults.reduce((sum, result) => sum + Number(result.replacements || 0), 0)
    });
  });

  const verification = verifyChangedPatchFiles(changedFiles);
  const deployment = await runAutonomousDeploymentAfterPatch({
    ...proposal,
    appliedAt
  }, verification);

  const updated = {
    ...proposal,
    status: "applied-by-framework",
    appliedAt,
    appliedBy: "AI Framework after owner approval",
    applyMode: "owner-approved-framework-applied",
    applyResult: {
      ok: true,
      changedFiles,
      operationCount: operations.length,
      backupRoot: path.relative(dataDir, backupRoot).replace(/\\/g, "/"),
      verification,
      deployment
    },
    nextStep: verification.ok
      ? deployment.ok
        ? "Patch applied, verified, and deployment hook triggered by the Brain/AI Framework after owner approval."
        : `Patch applied and verified by the Brain/AI Framework. Deployment status: ${deployment.status}. ${deployment.message}`
      : "Patch was written, but verification failed. Review verification results before deployment."
  };
  current[index] = updated;
  writeJsonFile(frameworkPatchProposalFile, current.slice(-250));
  saveFrameworkLearningProofEntry({
    category: "patch-applied-by-framework",
    event: `Owner-approved patch applied: ${proposal.title || id}`,
    plainEnglish: "The owner approved a structured patch, then the AI Framework applied the exact approved file changes, saved backups, and logged the result.",
    realWorldData: {
      proposalId: id,
      changedFiles,
      backupRoot: updated.applyResult.backupRoot
    },
    decisionMeasurement: {
      ownerDecision: "approved",
      applyMode: updated.applyMode,
      structuredOperationsOnly: true,
      allowedProjectFilesOnly: true,
      backupCreated: true
    },
    proceduralMemory: {
      reuseRule: "The Framework may apply code when a proposal is owner-approved, structured patch operations exist, targets are allowed project files, backups are created, and verification remains required. Codex/GitHub is a teaching fallback only when the Brain lacks the structured fix."
    },
    resultMetric: {
      patchApplied: true,
      changedFileCount: changedFiles.length,
      operationCount: operations.length,
      fileCreateCount: changedFiles.filter(file => file.action === "createFile").length,
      fileDeleteCount: changedFiles.filter(file => file.action === "deleteFile").length,
      verificationOk: verification.ok,
      deploymentAttempted: deployment.attempted,
      deploymentOk: deployment.ok,
      deploymentStatus: deployment.status
    },
    evidence: [
      proposal.rootCause,
      proposal.proposedFix,
      ...(proposal.verificationPlan || []),
      `verification=${verification.ok}`,
      `deployment=${deployment.status}`
    ].filter(Boolean),
    tags: ["patch-proposal", "owner-approved", "framework-applied", "code-change"]
  });
  return updated;
}

function patchProposalSummary(limit = 20) {
  const proposals = readPatchProposals(limit);
  const all = readJsonFile(frameworkPatchProposalFile, []);
  const safeAll = (Array.isArray(all) ? all : []).map(patchProposalWithDirection);
  const activeRequests = safeAll
    .filter(item => item.status === "pending-owner-approval")
    .slice()
    .sort((a, b) => Date.parse(b.at || b.updatedAt || "") - Date.parse(a.at || a.updatedAt || ""));
  const history = safeAll
    .filter(item => item.status !== "pending-owner-approval")
    .slice()
    .sort((a, b) => Date.parse(b.appliedAt || b.ownerDecisionAt || b.updatedAt || b.at || "") - Date.parse(a.appliedAt || a.ownerDecisionAt || a.updatedAt || a.at || ""));
  return {
    generatedAt: new Date().toISOString(),
    purpose: "Controlled code patch proposals generated by the Framework. These require owner approval; after approval, the Brain applies structured patch operations, verifies changed files, and triggers deployment when a deploy hook is configured.",
    totals: {
      proposalCount: safeAll.length,
      pendingApprovalCount: activeRequests.length,
      historyCount: history.length,
      approvedAwaitingApplyCount: safeAll.filter(item => item.status === "approved-for-framework" || item.status === "approved-for-codex").length,
      appliedByFrameworkCount: safeAll.filter(item => item.status === "applied-by-framework").length,
      manuallyAppliedCount: safeAll.filter(item => item.status === "applied-manually-after-owner-approval").length
    },
    patchApplyEnabled: frameworkPatchApplyEnabled,
    activeRequests: activeRequests.slice(0, limit),
    history: history.slice(0, limit),
    proposalRule: "Recognize root cause -> propose patch -> list affected files -> require owner approval -> Brain applies structured patch directly -> Codex/GitHub teaches only when the Brain lacks structured operations -> verify and log result.",
    recentProposals: proposals
  };
}

async function runPatchStructuringCycle(input = {}) {
  const proposals = readJsonFile(frameworkPatchProposalFile, []);
  const current = Array.isArray(proposals) ? proposals : [];
  const now = new Date().toISOString();
  let structuredCount = 0;
  let teachingNeededCount = 0;
  let alreadySatisfiedCount = 0;
  const applyResults = [];
  const updated = [];
  for (const proposal of current) {
    if ((proposal.filePatches || []).length) {
      updated.push(proposal);
      continue;
    }
    if (!["pending-owner-approval", "approved-for-framework", "approved-for-codex"].includes(proposal.status)) {
      updated.push(proposal);
      continue;
    }
    const structuring = patchStructuringSubsystem(proposal);
    if (structuring.structured && structuring.filePatches.length) structuredCount += 1;
    if (structuring.teachingNeeded) teachingNeededCount += 1;
    if (structuring.alreadySatisfied) alreadySatisfiedCount += 1;
    const next = {
      ...proposal,
      updatedAt: now,
      filePatches: structuring.structured ? structuring.filePatches : proposal.filePatches || [],
      patchStructuring: {
        structured: Boolean(structuring.structured),
        source: structuring.source,
        confidence: structuring.confidence,
        alreadySatisfied: Boolean(structuring.alreadySatisfied),
        teachingNeeded: Boolean(structuring.teachingNeeded),
        notes: structuring.notes || []
      },
      codexInstruction: structuring.teachingNeeded
        ? "Patch Structuring could not create safe filePatches yet. Teach the Brain with exact target file, find text, replacement text, or create/write file content."
        : proposal.codexInstruction,
      tags: [...new Set([...(proposal.tags || []), structuring.structured ? "structured-by-brain" : "needs-patch-structuring", structuring.alreadySatisfied ? "already-satisfied" : ""].filter(Boolean))]
    };
    updated.push(next);
  }
  writeJsonFile(frameworkPatchProposalFile, updated.slice(-250));
  if (input.applyApproved !== false) {
    const approvedStructured = updated.filter(proposal =>
      ["approved-for-framework", "approved-for-codex"].includes(proposal.status)
      && proposal.ownerDecision === "approved"
      && normalizePatchOperations(proposal.filePatches || proposal.patchOperations || []).length
    );
    for (const proposal of approvedStructured) {
      try {
        const applied = await applyApprovedPatchProposal({ id: proposal.id });
        applyResults.push({ id: proposal.id, ok: true, status: applied.status, verification: applied.applyResult?.verification || null, deployment: applied.applyResult?.deployment || null });
      } catch (error) {
        applyResults.push({ id: proposal.id, ok: false, error: error.message || "Approved structured patch could not be applied." });
      }
    }
  }
  const record = {
    generatedAt: now,
    reason: String(input.reason || "manual").trim(),
    proposalCount: current.length,
    structuredCount,
    teachingNeededCount,
    alreadySatisfiedCount,
    autoApplyCount: applyResults.filter(result => result.ok).length,
    autoApplyFailureCount: applyResults.filter(result => !result.ok).length,
    rule: "Patch Structuring converts Brain diagnoses into executable filePatches before approval; if it cannot, it explicitly asks for teaching instead of repeating unapplyable proposals."
  };
  saveFrameworkLearningProofEntry({
    category: "patch-structuring",
    event: `Patch structuring cycle: ${record.reason}`,
    plainEnglish: `The Patch Structuring subsystem reviewed ${record.proposalCount} proposal(s), structured ${record.structuredCount}, flagged ${record.teachingNeededCount} for teaching, found ${record.alreadySatisfiedCount} already satisfied, and auto-applied ${record.autoApplyCount} approved structured patch(es).`,
    decisionMeasurement: record,
    proceduralMemory: {
      rule: record.rule,
      reuseRule: "Before asking for owner approval on a code fix, try to attach structured filePatches that the Brain can apply after approval."
    },
    resultMetric: record,
    evidence: [`structured=${structuredCount}`, `teachingNeeded=${teachingNeededCount}`, `alreadySatisfied=${alreadySatisfiedCount}`, `autoApplied=${record.autoApplyCount}`],
    tags: ["patch-structuring", "brain-code-generation", "filePatches"]
  });
  return { record, applyResults, proposals: patchProposalSummary(50) };
}

function readCreatorPosts() {
  const posts = readJsonFile(creatorPostsFile, []);
  const list = Array.isArray(posts) ? posts : posts && typeof posts === "object" && posts.dayId ? [posts] : [];
  return list.sort((a, b) =>
    new Date(b.dayId || b.weekId || b.generatedAt || 0) - new Date(a.dayId || a.weekId || a.generatedAt || 0)
    || new Date(b.generatedAt || 0) - new Date(a.generatedAt || 0)
  );
}

function readCreatorComments() {
  const comments = readJsonFile(creatorCommentsFile, []);
  return Array.isArray(comments) ? comments : [];
}

function publicCreatorComment(comment = {}) {
  return {
    id: comment.id,
    postId: comment.postId,
    name: comment.name,
    message: comment.message,
    createdAt: comment.createdAt
  };
}

function commentsForPost(postId) {
  return readCreatorComments()
    .filter(comment => comment.postId === postId && comment.status === "visible")
    .sort((a, b) => new Date(a.createdAt) - new Date(b.createdAt))
    .slice(-100)
    .map(publicCreatorComment);
}

function clientIp(request) {
  const forwarded = String(request.headers["x-forwarded-for"] || "").split(",")[0].trim();
  return forwarded || request.socket.remoteAddress || "";
}

function hasRecentComment(comments, ip) {
  const latest = comments
    .filter(comment => comment.ip === ip)
    .sort((a, b) => new Date(b.createdAt) - new Date(a.createdAt))[0];
  return latest && Date.now() - new Date(latest.createdAt).getTime() < 45 * 1000;
}

function cleanPublicText(value = "", limit = 1200) {
  return String(value || "")
    .replace(/\s+/g, " ")
    .trim()
    .slice(0, limit);
}

function defaultSearchLearning() {
  return {
    version: 1,
    updatedAt: new Date().toISOString(),
    queryCount: 0,
    queries: {},
    terms: {},
    noResultQueries: [],
    clickedResults: {}
  };
}

function readSearchLearning() {
  const memory = readJsonFile(searchLearningFile, defaultSearchLearning());
  return {
    ...defaultSearchLearning(),
    ...memory,
    queries: memory && typeof memory.queries === "object" && memory.queries ? memory.queries : {},
    terms: memory && typeof memory.terms === "object" && memory.terms ? memory.terms : {},
    noResultQueries: Array.isArray(memory.noResultQueries) ? memory.noResultQueries : [],
    clickedResults: memory && typeof memory.clickedResults === "object" && memory.clickedResults ? memory.clickedResults : {}
  };
}

function saveSearchLearning(memory) {
  const orderedQueries = Object.entries(memory.queries || {})
    .sort((a, b) => Number(b[1].count || 0) - Number(a[1].count || 0))
    .slice(0, 500);
  const orderedTerms = Object.entries(memory.terms || {})
    .sort((a, b) => Number(b[1].count || 0) - Number(a[1].count || 0))
    .slice(0, 300);
  const orderedClicks = Object.entries(memory.clickedResults || {})
    .sort((a, b) => Number(b[1].count || 0) - Number(a[1].count || 0))
    .slice(0, 500);
  writeJsonFile(searchLearningFile, {
    ...memory,
    updatedAt: new Date().toISOString(),
    queries: Object.fromEntries(orderedQueries),
    terms: Object.fromEntries(orderedTerms),
    clickedResults: Object.fromEntries(orderedClicks),
    noResultQueries: (memory.noResultQueries || []).slice(-100)
  });
}

function rejectSpamComment(name, message) {
  const text = `${name} ${message}`.toLowerCase();
  const linkCount = (message.match(/https?:\/\//gi) || []).length;
  if (linkCount > 1) return "Please keep links to one or fewer.";
  if (/(free money|guaranteed profit|miracle cure|crypto giveaway|act now|work from home)/i.test(text)) return "Comment looks like spam.";
  if (message.length < 3) return "Comment is too short.";
  if (message.length > 1200) return "Comment is too long.";
  return "";
}

function addCreatorComment(input = {}, request) {
  const postId = cleanPublicText(input.postId, 80);
  const name = cleanPublicText(input.name, 60) || "Reader";
  const message = cleanPublicText(input.message || input.comment, 1200);
  const postExists = readCreatorPosts().some(post => post.id === postId || post.dayId === postId || post.weekId === postId);
  if (!postExists) throw new Error("Creator Desk post was not found.");

  const spamError = rejectSpamComment(name, message);
  if (spamError) throw new Error(spamError);

  const comments = readCreatorComments();
  const ip = clientIp(request);
  if (hasRecentComment(comments, ip)) throw new Error("Please wait a moment before posting another comment.");

  const comment = {
    id: `comment_${Date.now()}_${Math.random().toString(36).slice(2, 8)}`,
    postId,
    name,
    message,
    createdAt: new Date().toISOString(),
    status: "visible",
    ip
  };
  writeJsonFile(creatorCommentsFile, [...comments, comment].slice(-5000));
  return publicCreatorComment(comment);
}

function logCreatorDesk(message, details = {}) {
  ensureDataFiles();
  const entry = {
    at: new Date().toISOString(),
    message,
    ...details
  };
  fs.appendFileSync(creatorDeskLogFile, `${JSON.stringify(entry)}\n`);
}

function defaultAdaptiveWeights() {
  return {
    version: 1,
    updatedAt: new Date().toISOString(),
    bounds: {
      confidenceEvidence: [0.7, 1.45],
      confidenceVerification: [0.8, 1.6],
      confidenceRationale: [0.75, 1.45],
      confidenceRule: [0.75, 1.45],
      confidenceRecurrence: [0.6, 1.35],
      confidenceSourceTrust: [0.75, 1.35],
      priorityConfidence: [0.22, 0.46],
      prioritySeverity: [0.18, 0.38],
      priorityRecency: [0.1, 0.28],
      priorityRecurrence: [0.06, 0.24],
      priorityBreadth: [0.03, 0.14],
      lessonOwner: [1.0, 1.28],
      lessonCodex: [1.0, 1.22],
      lessonOptimization: [0.95, 1.16],
      visitorSearchInfluence: [0.15, 0.55],
      selfReviewInfluence: [0.75, 1.35]
    },
    values: {
      confidenceEvidence: 1,
      confidenceVerification: 1,
      confidenceRationale: 1,
      confidenceRule: 1,
      confidenceRecurrence: 1,
      confidenceSourceTrust: 1,
      priorityConfidence: 0.34,
      prioritySeverity: 0.26,
      priorityRecency: 0.18,
      priorityRecurrence: 0.14,
      priorityBreadth: 0.08,
      lessonOwner: 1.12,
      lessonCodex: 1.08,
      lessonOptimization: 1.04,
      visitorSearchInfluence: 0.35,
      selfReviewInfluence: 1
    },
    metaLearning: {
      version: 1,
      updatedAt: new Date().toISOString(),
      saturationWindow: 12,
      saturationThreshold: 3,
      redirectStepLimit: 0.008,
      decayAfterMs: 7 * 24 * 60 * 60 * 1000,
      decayStep: 0.004,
      boundAdjustmentStep: 0.02,
      boundAdjustmentLimit: 0.12,
      history: []
    },
    history: []
  };
}

function normalizeAdaptiveWeights(input = {}) {
  const defaults = defaultAdaptiveWeights();
  const bounds = { ...defaults.bounds, ...(input.bounds || {}) };
  const values = { ...defaults.values, ...(input.values || {}) };
  const incomingMeta = input.metaLearning && typeof input.metaLearning === "object" ? input.metaLearning : {};
  const metaLearning = {
    ...defaults.metaLearning,
    ...incomingMeta,
    history: Array.isArray(incomingMeta.history) ? incomingMeta.history.slice(-100) : []
  };
  Object.entries(bounds).forEach(([key, range]) => {
    const [min, max] = Array.isArray(range) ? range : defaults.bounds[key] || [0, 2];
    values[key] = Math.max(min, Math.min(max, Number(values[key] ?? defaults.values[key] ?? min)));
  });
  return {
    ...defaults,
    ...input,
    bounds,
    values,
    metaLearning,
    history: Array.isArray(input.history) ? input.history.slice(-100) : []
  };
}

