function storyLearningFeatures(story = {}) {
  const text = `${story.title || ""} ${story.summary || ""} ${story.articleSummary || ""} ${story.category || ""}`.toLowerCase();
  const features = new Set([story.category].filter(Boolean));
  if (/free speech|censor|speech|silence|expression|press/.test(text)) features.add("freeSpeech");
  if (/family|father|mother|parent|child|children|school|marriage|home/.test(text)) features.add("family");
  if (/tax|budget|spending|welfare|subsid|debt|government|congress|policy|court|law/.test(text)) features.add("governmentPower");
  if (/culture|movie|music|celebrity|gender|sex|trans|lgbt|hollywood|streaming/.test(text)) features.add("culture");
  if (/race|racial|racism|discrimination|equity|diversity/.test(text)) features.add("raceAgency");
  if (/private choice|personal choice|privacy|belief|conscience|religion/.test(text)) features.add("privateChoice");
  if (/economy|market|job|jobs|inflation|tax|tariff|business/.test(text)) features.add("economyTaxes");
  if (/detroit|lions|tigers|pistons|red wings|michigan|wolverines|sports|coach|playoff/.test(text)) features.add("sportsStandards");
  return [...features];
}

function learningScoreForStory(story, memory = learningMemory(), searchMemory = readSearchLearning()) {
  const topicScore = storyLearningFeatures(story)
    .reduce((score, feature) => score + Number(memory.topicWeights?.[feature] || 0), 0);
  const sourceScore = Number(memory.sourceWeights?.[story.source] || 0);
  const audienceCuriosityScore = Math.min(4, searchInterestScoreForStory(story, searchMemory));
  return topicScore + sourceScore + audienceCuriosityScore;
}

function rankStoriesWithLearning(stories = [], memory = learningMemory()) {
  const searchMemory = readSearchLearning();
  return [...stories].sort((a, b) => {
    const aLearning = learningScoreForStory(a, memory, searchMemory);
    const bLearning = learningScoreForStory(b, memory, searchMemory);
    const aEngagement = Number(a.engagementScore || 0);
    const bEngagement = Number(b.engagementScore || 0);
    return (bLearning - aLearning) || (bEngagement - aEngagement) || (storyDate(b.published) - storyDate(a.published));
  });
}

