function subsystemEvidenceFor(registryItem = {}, diagnostics = null, memory = learningMemory()) {
  const latestArticleIntelligence = readArticleIntelligence();
  const recentMeta = (memory.metaExecutionCycles || []).slice(-8);
  const recentActions = frameworkActionLogSummary(25).recentActions || [];
  const patchSummary = patchProposalSummary(25);
  const evidence = [];
  let readiness = 65;
  let status = "monitoring";
  if (registryItem.key === "article-intelligence") {
    const clusterCount = Number(latestArticleIntelligence?.clusterCount || 0);
    const readyClusterCount = Number(latestArticleIntelligence?.readyClusterCount || 0);
    const fullArticleReads = Number(runtimeState.articleReadSuccessCount || 0);
    const articleReadFailures = Number(runtimeState.articleReadFailureCount || 0);
    const articleReadAttempts = Number(runtimeState.articleReadAttemptCount || 0);
    evidence.push(
      `clusters=${clusterCount}`,
      `readyClusters=${readyClusterCount}`,
      `fullArticleReads=${fullArticleReads}`,
      `articleReadFailures=${articleReadFailures}`,
      `articleReadAttempts=${articleReadAttempts}`,
      `articleReadLimit=${articleMemoryReadLimit}`,
      `articleReadTimeoutMs=${articleReadTimeoutMs}`,
      latestArticleIntelligence?.updatedAt ? `updated=${latestArticleIntelligence.updatedAt}` : "not-updated"
    );
    readiness = clampScore(38 + Math.min(24, clusterCount * 4) + Math.min(20, readyClusterCount * 8) + Math.min(24, fullArticleReads * 3) - Math.min(18, articleReadFailures));
    status = fullArticleReads ? "full-article-reading" : clusterCount ? "shallow-reading-needs-more-depth" : "needs-more-observation";
  }
  if (registryItem.key === "feed-reliability") {
    const errorCount = Number(diagnostics?.runtime?.feedSourceErrorCount || 0);
    const slowCount = Number(diagnostics?.runtime?.feedSourceSlowCount || 0);
    const transientCount = Number(diagnostics?.runtime?.transientFeedSourceErrorCount || 0);
    const failures = Number(diagnostics?.runtime?.consecutiveRefreshFailures || 0);
    const attribution = diagnostics?.runtime?.feedSourceAttribution || feedFailureAttribution(5);
    const topSource = attribution.worstSources?.[0];
    const topDomain = attribution.worstDomains?.[0];
    const topProvider = attribution.worstProviders?.[0];
    const attempted = Object.keys(diagnostics?.runtime?.feedSourceTelemetry || {}).length;
    const quarantined = Object.keys(diagnostics?.runtime?.feedSourceQuarantine || runtimeState.feedSourceQuarantine || {}).length;
    const cacheHits = Object.values(diagnostics?.runtime?.feedSourceTelemetry || runtimeState.feedSourceTelemetry || {})
      .reduce((sum, item) => sum + Number(item.cacheHitCount || 0), 0);
    const errorRate = attempted ? errorCount / attempted : 0;
    const slowRate = attempted ? slowCount / attempted : 0;
    const isolationCredit = errorCount && (quarantined || cacheHits)
      ? Math.min(18, 8 + Math.min(5, quarantined) + Math.min(5, cacheHits))
      : 0;
    const liveCredit = diagnostics?.status === "live" ? 8 : 0;
    evidence.push(
      `feedSourceErrors=${errorCount}`,
      `errorRate=${Number(errorRate * 100).toFixed(1)}%`,
      `slowFeedSources=${slowCount}`,
      `transientFeedSourceErrors=${transientCount}`,
      `consecutiveRefreshFailures=${failures}`,
      `attemptedSources=${attempted}`,
      `quarantinedSources=${quarantined}`,
      `sourceCacheHits=${cacheHits}`,
      `timeoutMs=${feedFetchTimeoutMs}`,
      `sourceLimit=${feedRefreshSourceLimit}`,
      `fastSourceLimit=${fastFeedRefreshSourceLimit}`,
      `concurrency=${feedFetchConcurrency}`,
      topSource ? `topFailingSource=${topSource.name}:${topSource.failureCount}` : "topFailingSource=none",
      topDomain ? `topFailingDomain=${topDomain.domain}:${topDomain.failureCount}` : "topFailingDomain=none",
      topProvider ? `topFailingProvider=${topProvider.provider}:${topProvider.failureCount}` : "topFailingProvider=none",
      `status=${diagnostics?.status || "unknown"}`
    );
    readiness = clampScore(72 + isolationCredit + liveCredit - Math.min(28, errorRate * 40) - Math.min(18, slowRate * 22) - Math.min(25, failures * 10) - Math.min(10, transientCount * 2));
    status = failures ? "operational-review" : errorCount ? "source-errors-contained" : "active";
  }
  if (registryItem.key === "editorial-synthesis" || registryItem.key === "news-creation") {
    const articleReady = Number(latestArticleIntelligence?.readyClusterCount || 0);
    const reviewCount = Number((memory.selfReviewLessons || []).length);
    const editorialApplication = editorialLessonApplicationMetrics(memory);
    evidence.push(
      `articleReadyClusters=${articleReady}`,
      `selfReviewLessons=${reviewCount}`,
      `repetitiveFeedback=${editorialApplication.repetitiveFeedback}`,
      `recentRewriteActions=${editorialApplication.recentRewriteActions}`,
      `lessonApplicationGap=${editorialApplication.lessonApplicationGap}`
    );
    readiness = clampScore(50 + Math.min(30, articleReady * 10) + Math.min(14, reviewCount) - Math.min(26, editorialApplication.lessonApplicationGap * 7));
    status = editorialApplication.lessonApplicationGap >= 3 ? "lesson-application-gap" : articleReady ? "ready" : "waiting-for-brain-briefing";
  }
  if (registryItem.key?.startsWith("news-tab-")) {
    const category = registryItem.key.replace("news-tab-", "");
    const storedTabMetrics = runtimeState.newsLabTabMetrics?.[category] || {};
    const fallbackTabMetrics = liveNewsTabFallbackMetrics(category);
    const tabMetrics = Number(storedTabMetrics.storyCount || 0) > 0 || Number(fallbackTabMetrics.storyCount || 0) === 0
      ? storedTabMetrics
      : fallbackTabMetrics;
    const lifecycle = runtimeState.newsLabBrainSubsystems?.[category] || {};
    const count = Number(tabMetrics.storyCount || 0);
    const emptyBodies = Number(tabMetrics.emptyBodyCount || 0);
    const coverageFloor = Number(tabMetrics.coverageFloor || (category === "top" ? Math.min(count || newsLabOwnedStoryLimit, newsLabOwnedStoryLimit) : 4));
    const coverageGap = Math.max(0, Number(tabMetrics.coverageGap ?? (coverageFloor - count)));
    const builtInMs = Number(runtimeState.newsLabBuildMs || 0);
    const cacheAgeMs = runtimeState.newsLabBuiltAt ? Date.now() - new Date(runtimeState.newsLabBuiltAt).getTime() : 0;
    evidence.push(
      `storyCount=${count}`,
      `coverageFloor=${coverageFloor}`,
      `coverageGap=${coverageGap}`,
      `emptyBodies=${emptyBodies}`,
      `avgParagraphs=${Number(tabMetrics.avgParagraphs || 0).toFixed(1)}`,
      `strongestUniqueSources=${Number(tabMetrics.strongestUniqueSources || 0)}`,
      `metricSource=${tabMetrics.source || "news-lab-builder"}`,
      `builtInMs=${builtInMs}`,
      `cacheAgeMs=${cacheAgeMs}`,
      `lifecycle=${lifecycle.status || "not-deployed"}`,
      `priority=${Number(lifecycle.priority || 0)}`,
      `recommendedAction=${tabMetrics.recommendedAction || "collect-tab-metrics"}`
    );
    readiness = clampScore(42 + Math.min(28, count * 5) + Math.min(18, Number(tabMetrics.strongestUniqueSources || 0) * 6) - Math.min(26, emptyBodies * 8) - (builtInMs > 2500 ? 10 : 0));
    status = count >= coverageFloor && !emptyBodies
      ? "active"
      : lifecycle.status === "retired"
        ? "coverage-recovery-deployed"
        : emptyBodies ? "article-generation-gap"
        : coverageGap > 0 ? "needs-more-coverage"
          : builtInMs > 2500 ? "speed-review"
            : lifecycle.status || "active";
  }
  if (registryItem.key === "search-quality") {
    const searchSummary = searchLearningSummary(5);
    const queryCount = Number(searchSummary?.totalQueries || searchSummary?.queryCount || 0);
    evidence.push(`searchSignals=${queryCount}`, `recentSearches=${JSON.stringify(searchSummary?.topTerms || []).slice(0, 120)}`);
    readiness = queryCount ? 78 : 62;
    status = queryCount ? "active" : "needs-more-visitor-data";
  }
  if (registryItem.key === "site-performance") {
    const healthScore = Number(diagnostics?.publicHealth?.score || diagnostics?.score || diagnostics?.aiShield?.score || 0);
    const ok = diagnostics?.health === "ok" || diagnostics?.ok;
    const feedRefreshMs = Number(diagnostics?.connectivity?.feedRefreshMs || diagnostics?.runtime?.lastRefreshMs || 0);
    const requiredResourcesOk = (diagnostics?.connectivity?.requiredResources || []).every(item => item.ok);
    const statusLive = diagnostics?.status === "live" || diagnostics?.runtime?.lastRefreshStatus === "success";
    const latencyCredit = feedRefreshMs > 0
      ? feedRefreshMs <= 2500 ? 24
        : feedRefreshMs <= 5000 ? 18
          : feedRefreshMs <= 9000 ? 10
            : 4
      : 6;
    const operationalReadiness = clampScore(
      (statusLive ? 18 : 6)
      + (requiredResourcesOk ? 24 : 4)
      + latencyCredit
      + (ok ? 18 : 0)
    );
    evidence.push(
      `health=${diagnostics?.health || "unknown"}`,
      `score=${healthScore}`,
      `operationalReadiness=${operationalReadiness}`,
      `feedRefreshMs=${feedRefreshMs}`,
      `requiredResourcesOk=${requiredResourcesOk}`,
      `statusLive=${statusLive}`
    );
    readiness = clampScore(Math.max(healthScore, operationalReadiness));
    status = ok || readiness >= 75 ? "active" : readiness >= 45 ? "attention-needs-optimization" : "needs-revision";
  }
  if (registryItem.key === "patch-proposal") {
    const pending = Number(patchSummary?.totals?.pendingOwnerApproval || 0);
    const blocked = recentMeta.reduce((sum, cycle) => sum + Number(cycle.blockedCount || 0), 0);
    evidence.push(`pendingPatchRequests=${pending}`, `recentBlockedMetaActions=${blocked}`, `recentActions=${recentActions.length}`);
    readiness = clampScore(72 + Math.min(18, pending * 3) - Math.min(20, blocked * 2));
    status = pending ? "active-awaiting-owner" : "active";
  }
  if (registryItem.key === "patch-structuring") {
    const patchSummary = patchProposalSummary(50);
    const recent = patchSummary.recentProposals || [];
    const structured = recent.filter(item => (item.filePatches || []).length).length;
    const needsTeaching = recent.filter(item => item.patchStructuring?.teachingNeeded || (!(item.filePatches || []).length && item.status === "pending-owner-approval")).length;
    evidence.push(`structuredRecent=${structured}`, `needsTeaching=${needsTeaching}`);
    readiness = clampScore(62 + Math.min(28, structured * 6) - Math.min(24, needsTeaching * 6));
    status = needsTeaching ? "needs-teaching" : "active";
  }
  return {
    readiness,
    status,
    evidence: evidence.filter(Boolean)
  };
}

function subsystemTrendFor(key = "", memory = learningMemory(), windowSize = 6) {
  const samples = (memory.subsystemCycles || [])
    .map(cycle => {
      const item = (cycle.registry || []).find(entry => entry.key === key);
      return item ? {
        at: cycle.at,
        readiness: Number(item.readiness || 0),
        status: item.status || "unknown"
      } : null;
    })
    .filter(Boolean)
    .slice(-windowSize);
  const first = samples[0] || null;
  const latest = samples[samples.length - 1] || null;
  const previous = samples[samples.length - 2] || null;
  const delta = latest && first ? Number(latest.readiness || 0) - Number(first.readiness || 0) : 0;
  const lastDelta = latest && previous ? Number(latest.readiness || 0) - Number(previous.readiness || 0) : 0;
  const stagnant = samples.length >= 3 && Math.max(...samples.map(item => item.readiness)) - Math.min(...samples.map(item => item.readiness)) <= 2;
  const declining = samples.length >= 2 && (lastDelta < 0 || delta <= -5);
  return {
    samples,
    firstReadiness: first?.readiness ?? null,
    latestReadiness: latest?.readiness ?? null,
    delta,
    lastDelta,
    stagnant,
    declining
  };
}

function editorialLessonApplicationMetrics(memory = learningMemory()) {
  const feedback = memory.feedback || [];
  const recentFeedback = feedback.slice(-30);
  const recentStyleNotes = (memory.styleNotes || []).slice(0, 12);
  const recentReasoningLessons = (memory.reasoningLessons || []).slice(-30);
  const recentSelfReviewLessons = (memory.selfReviewLessons || []).slice(-30);
  const lessonText = JSON.stringify([
    ...recentStyleNotes,
    ...recentReasoningLessons,
    ...recentSelfReviewLessons,
    ...recentFeedback
  ]).toLowerCase();
  const repetitiveFeedback = (lessonText.match(/repetitive|repeat|generic|copied article|grammar|topic mismatch|similar feedback|too much alike/g) || []).length;
  const recentActions = frameworkActionLogSummary(80).recentActions || [];
  const recentRewriteActions = recentActions.filter(action =>
    /brain-rewrite-creator-archive|newsletter|editorial|creator/i.test(`${action.actionKey || ""} ${action.type || ""} ${action.message || ""}`)
  ).length;
  return {
    repetitiveFeedback,
    recentRewriteActions,
    lessonApplicationGap: Math.max(0, Math.min(12, Math.ceil(repetitiveFeedback / 12) - recentRewriteActions))
  };
}

function liveNewsTabFallbackMetrics(category = "top") {
  const stories = Array.isArray(cache.payload?.stories) ? cache.payload.stories : [];
  const selected = category === "top"
    ? stories
    : stories.filter(story => newsLabCategory(story) === category || String(story.category || "").toLowerCase() === category);
  const coverageFloor = category === "top" ? Math.min(selected.length || newsLabOwnedStoryLimit, newsLabOwnedStoryLimit) : 7;
  const sourceCount = new Set(selected.map(story => story.source || story.publisher || story.sourceName || story.url).filter(Boolean)).size;
  return {
    category,
    source: "live-public-news-payload",
    storyCount: selected.length,
    coverageFloor,
    coverageGap: Math.max(0, coverageFloor - selected.length),
    emptyBodyCount: 0,
    qualityFlagCount: 0,
    avgQualityScore: selected.length ? 72 : 0,
    avgParagraphs: selected.length ? 3 : 0,
    strongestUniqueSources: Math.min(sourceCount, 6),
    builtInMs: Number(runtimeState.lastRefreshMs || 0),
    recommendedAction: selected.length >= coverageFloor
      ? "use-live-public-payload-coverage"
      : "increase-source-coverage-for-tab"
  };
}

function applySubsystemTrendTeaching(item = {}, memory = learningMemory()) {
  const trend = subsystemTrendFor(item.key, memory);
  const output = {
    ...item,
    trend,
    teachingNeeded: false,
    redeployNeeded: false
  };
  const lowReadiness = Number(item.readiness || 0) < 60;
  const severeLowReadiness = Number(item.readiness || 0) < 45;
  const lessonGap = numericEvidenceValue(item.evidence || [], "lessonApplicationGap");
  const needsTeaching = severeLowReadiness || lessonGap >= 3 || (lowReadiness && (trend.declining || trend.stagnant));
  if (!needsTeaching) return output;
  const penalty = severeLowReadiness ? 5 : trend.declining ? 6 : trend.stagnant ? 4 : 3;
  output.readiness = clampScore(Number(item.readiness || 0) - penalty);
  output.status = severeLowReadiness ? "low-readiness-needs-teaching" : trend.declining ? "declining-needs-teaching" : lessonGap >= 3 ? "lesson-application-gap" : "stagnant-needs-teaching";
  output.teachingNeeded = true;
  output.redeployNeeded = true;
  output.revisionNeeded = item.revisionNeeded || Number(output.readiness || 0) < 45 || lessonGap >= 6;
  output.evidence = [
    ...(item.evidence || []),
    `trendDelta=${trend.delta}`,
    `lastDelta=${trend.lastDelta}`,
    `stagnant=${trend.stagnant}`,
    `declining=${trend.declining}`,
    "brainTeachingRequired=true"
  ];
  output.brainDecision = "Brain must teach and redeploy this subsystem, then compare the next measured readiness against the prior cycle. Awareness alone is no longer enough.";
  return output;
}

function subsystemNeedsCodeRevision(item = {}) {
  const missingCapabilities = item.missingCapabilities || [];
  if (item.key === "feed-reliability" && !missingCapabilities.length) {
    const attemptedSources = numericEvidenceValue(item.evidence || [], "attemptedSources");
    const timeoutMs = numericEvidenceValue(item.evidence || [], "timeoutMs");
    if (attemptedSources > 0 && timeoutMs > 0 && !item.teachingNeeded) return false;
  }
  return item.status === "needs-revision"
    || Number(item.readiness || 0) < 65
    || missingCapabilities.length >= 2;
}

function subsystemCapabilityAnalysis(memory = learningMemory(), diagnostics = null) {
  const registry = subsystemRegistry().map(item => {
    const evidence = subsystemEvidenceFor(item, diagnostics, memory);
    const missingCapabilities = item.requiredCapabilities.filter(capability => {
      if (item.key === "article-intelligence" && capability === "brain-brief") return !readArticleIntelligence()?.brainBriefing;
      if (item.key === "feed-reliability" && capability === "source-error-telemetry") return !Object.keys(diagnostics?.runtime?.feedSourceTelemetry || {}).length && diagnostics?.status === "fallback";
      return false;
    });
    const baseItem = {
      ...item,
      ...evidence,
      missingCapabilities
    };
    const taughtItem = applySubsystemTrendTeaching(baseItem, memory);
    const revisionNeeded = subsystemNeedsCodeRevision(taughtItem);
    return {
      ...taughtItem,
      revisionNeeded,
      brainDecision: taughtItem.brainDecision || (revisionNeeded
        ? "Brain should task Patch Proposal to create a controlled subsystem code revision request."
        : "Brain can keep this subsystem active and continue measuring it.")
    };
  });
  const gaps = registry.filter(item => item.revisionNeeded);
  const tasking = [
    {
      subsystem: "Brain",
      task: "Review subsystem readiness, detect missing capability, decide whether to create or revise a subsystem, and route code changes through owner-approved patch proposals.",
      status: gaps.length ? "action-needed" : "monitoring"
    },
    ...gaps.slice(0, 5).map(item => ({
      subsystem: item.name,
      task: `Investigate ${item.responsibility} Readiness=${item.readiness}; evidence=${item.evidence.join("; ")}`,
      status: "needs-brain-review"
    })),
    ...registry.filter(item => item.teachingNeeded && !gaps.some(gap => gap.key === item.key)).slice(0, 5).map(item => ({
      subsystem: item.name,
      task: `Teach and redeploy ${item.name}; readiness trend is not improving. Evidence=${item.evidence.join("; ")}`,
      status: "needs-teaching-and-redeployment"
    }))
  ];
  return {
    generatedAt: new Date().toISOString(),
    purpose: "Let the Brain recognize where a subsystem is needed, weak, missing capability, or needs a code-level revision.",
    registry,
    gaps,
    tasking,
    rule: "The Brain may create or revise subsystem behavior only through bounded runtime tasking or owner-approved Patch Requests when code changes are needed."
  };
}

function frameworkGapIssue(id, type, title, evidence = [], currentLimitation = "", closeableAbility = "", executionPath = "", severity = "medium") {
  return {
    id,
    type,
    title,
    severity,
    evidence: normalizeStringList(evidence, 10),
    currentLimitation,
    closeableAbility,
    executionPath,
    status: "open",
    abilityCreated: Boolean(closeableAbility),
    rule: "Every Brain gap must identify what is missing, what ability would close it, how to execute safely, and how to verify that the ability improved future behavior."
  };
}

function frameworkGapAnalysis(memory = learningMemory(), diagnostics = null) {
  const subsystemAnalysis = subsystemCapabilityAnalysis(memory, diagnostics);
  const proof = frameworkLearningProofSummary(80);
  const actions = frameworkActionLogSummary(80);
  const recentProof = proof.recentEntries || [];
  const recentActions = actions.recentActions || [];
  const improvementUnproven = recentActions.filter(action =>
    action.improvementAssessment && action.improvementAssessment.metricImproved === false
  );
  const interventionTrend = proof.interventionTrend || {};
  const teachingNeeded = (subsystemAnalysis.registry || []).filter(item => item.teachingNeeded || item.revisionNeeded);
  const lowReadiness = (subsystemAnalysis.registry || []).filter(item => Number(item.readiness || 0) < 65);
  const unstructuredPatchLoop = (patchProposalSummary(80).recentProposals || []).filter(proposal =>
    proposal.patchStructuring?.teachingNeeded
    || (!(proposal.filePatches || []).length && /approved|pending/i.test(proposal.status || ""))
  );
  const proofWithoutVerification = recentProof.filter(entry =>
    /pending|not complete|not yet|No measurable improvement/i.test(`${entry.causalChain?.summary || ""} ${entry.whyImprovement || ""} ${entry.autonomousProofChain?.summary || ""}`)
  );
  const fullReadGap = recentProof.find(entry =>
    entry.category === "news-lab-full-article-reading"
    && Number(entry.realWorldData?.selectedForFullRead || 0) > 0
    && Number(entry.realWorldData?.successfulReads || entry.realWorldData?.fullReads || 0) === 0
  );
  const articleOutputGap = recentProof.find(entry =>
    /continuous-production|editor-gate|no-placeholders/.test((entry.tags || []).join(" "))
    && Number(entry.resultMetric?.approvedArticles || 0) < Math.max(10, Number(entry.resultMetric?.rejectedDrafts || 0))
  );
  const editorialApplicationGap = lowReadiness.find(item => item.key === "editorial-intelligence" || item.status === "lesson-application-gap");
  const gaps = [];

  if (teachingNeeded.length) {
    gaps.push(frameworkGapIssue(
      "learning-gap-subsystem-teaching",
      "learning-gap",
      "Subsystem lessons are being captured faster than they are being converted into stronger behavior.",
      teachingNeeded.slice(0, 5).map(item => `${item.name}: readiness=${item.readiness}; status=${item.status}`),
      "The Brain knows which subsystem is weak, but some lessons remain at the awareness/teaching stage.",
      "Create a teaching-to-ability loop that turns each repeated lesson into a subsystem directive, reruns the subsystem, and compares readiness before/after.",
      "Run subsystem cycle -> classify weak subsystem -> create directive or structured patch -> rerun -> verify readiness delta."
    ));
  }

  if (improvementUnproven.length || proofWithoutVerification.length) {
    gaps.push(frameworkGapIssue(
      "improvement-gap-verification",
      "improvement-gap",
      "Some actions record lessons but do not prove metric improvement.",
      [
        `unprovenActions=${improvementUnproven.length}`,
        `proofEntriesNeedingVerification=${proofWithoutVerification.length}`
      ],
      "The Brain can act and log, but may still mark verification pending or metric improvement unconfirmed.",
      "Add mandatory post-action verification windows: every action keeps a before metric, after metric, result metric, and next check deadline.",
      "After action -> measure same metric -> mark improved/regressed/stagnant -> if stagnant, escalate to capability gap or patch proposal."
    ));
  }

  if (unstructuredPatchLoop.length) {
    gaps.push(frameworkGapIssue(
      "execution-gap-patch-structuring",
      "execution-gap",
      "Patch ideas can still become approved requests without executable file operations.",
      unstructuredPatchLoop.slice(0, 5).map(item => `${item.id || item.title}: status=${item.status}`),
      "The Brain can ask for approval, but cannot execute safely unless it has exact structured filePatches.",
      "Strengthen Patch Structuring so every code proposal must include target file, action, find text, replacement/content, verification, and rollback before approval.",
      "Diagnosis -> structured filePatches -> owner approval -> Brain apply -> syntax check -> endpoint check -> proof log."
    ));
  }

  if (fullReadGap) {
    gaps.push(frameworkGapIssue(
      "capability-gap-full-article-reading",
      "capability-gap",
      "Full article read attempts are not consistently becoming successful read depth.",
      [
        `selectedForFullRead=${fullReadGap.realWorldData?.selectedForFullRead}`,
        `successfulReads=${fullReadGap.realWorldData?.successfulReads || fullReadGap.realWorldData?.fullReads || 0}`,
        `timeoutMs=${fullReadGap.realWorldData?.timeoutMs || ""}`
      ],
      "The Brain attempts to gather deeper information, but some cycles produce zero successful full reads.",
      "Add source-specific reading strategies: retry slower trusted sources, prefer accessible official/primary sources, and fall back to multiple medium-depth sources when a full page blocks.",
      "Collector -> source registry weighting -> accessible source priority -> full/medium read blend -> dossier completeness score."
    ));
  }

  if (articleOutputGap) {
    gaps.push(frameworkGapIssue(
      "capability-gap-approved-output",
      "capability-gap",
      "Approved article output is still below the target needed to fill the News Lab page.",
      [
        `approvedArticles=${articleOutputGap.resultMetric?.approvedArticles}`,
        `rejectedDrafts=${articleOutputGap.resultMetric?.rejectedDrafts}`,
        `publicStoryCount=${articleOutputGap.resultMetric?.publicStoryCount}`
      ],
      "The Brain preserves standards, but too few drafts pass the Editor.",
      "Turn each rejection reason into a pre-draft writer constraint and route failed drafts back to the earliest failing subsystem before another full draft attempt.",
      "Rejection -> earliest failing stage -> subsystem directive -> repair prompt/input -> rewrite -> editor pass -> output count measurement."
    ));
  }

  if (editorialApplicationGap) {
    gaps.push(frameworkGapIssue(
      "learning-gap-editorial-application",
      "learning-gap",
      "Editorial lessons are stored but not always applied before the next draft.",
      editorialApplicationGap.evidence || [],
      "Lesson capture is stronger than lesson application.",
      "Require Editorial Intelligence v2 to apply pattern-level lessons before writing, not after the Editor finds the same issue again.",
      "Editorial memory -> writer constraints -> draft -> editor verifies absence of repeated pattern -> save outcome."
    ));
  }

  if (interventionTrend.improving === false) {
    gaps.push(frameworkGapIssue(
      "execution-gap-intervention-reduction",
      "execution-gap",
      "Procedural memory has not yet reduced outside intervention.",
      [interventionTrend.interpretation || "Intervention trend not improving."],
      "The Brain learns procedures, but not enough of them become independent execution ability.",
      "Promote repeated successful Codex-taught operations into reusable Brain abilities with safety checks and owner approval gates.",
      "Teach operation -> store exact pattern -> next similar task uses Brain apply path -> measure Codex intervention level."
    ));
  }

  const abilityBacklog = gaps.map(gap => ({
    abilityId: gap.id.replace(/^(learning|improvement|execution|capability)-gap-/, "ability-"),
    fromGap: gap.id,
    ability: gap.closeableAbility,
    executionPath: gap.executionPath,
    ownerApprovalRequired: /patch|code|file|apply/i.test(gap.executionPath),
    verification: "Measure the same readiness, output, or error metric before and after the ability runs."
  }));

  const priorityOrder = { "execution-gap": 4, "capability-gap": 3, "improvement-gap": 2, "learning-gap": 1 };
  gaps.sort((a, b) => (priorityOrder[b.type] || 0) - (priorityOrder[a.type] || 0));
  return {
    generatedAt: new Date().toISOString(),
    purpose: "Identify what the Brain is learning, where improvement is not verified, where execution is blocked, and which limitations can become new abilities.",
    summary: {
      gapCount: gaps.length,
      learningGaps: gaps.filter(gap => gap.type === "learning-gap").length,
      improvementGaps: gaps.filter(gap => gap.type === "improvement-gap").length,
      executionGaps: gaps.filter(gap => gap.type === "execution-gap").length,
      capabilityGaps: gaps.filter(gap => gap.type === "capability-gap").length,
      lowReadinessSubsystems: lowReadiness.length,
      teachingNeeded: teachingNeeded.length
    },
    gaps,
    abilityBacklog,
    notYetCapableOf: gaps.map(gap => ({
      limitation: gap.currentLimitation,
      canBecomeAbility: gap.closeableAbility,
      route: gap.executionPath
    })),
    subsystemSnapshot: subsystemAnalysis.registry.map(item => ({
      key: item.key,
      name: item.name,
      readiness: item.readiness,
      status: item.status,
      teachingNeeded: Boolean(item.teachingNeeded),
      revisionNeeded: Boolean(item.revisionNeeded)
    })),
    rule: "The Brain must not stop at knowing a gap. It must translate each gap into an ability, choose the safe execution route, verify the result, and remember whether the ability reduced future intervention."
  };
}

function recordFrameworkGapAnalysis(reason = "manual") {
  const memory = learningMemory();
  const analysis = frameworkGapAnalysis(memory, null);
  saveFrameworkLearningProofEntry({
    category: "framework-gap-analysis",
    event: "Brain identified learning, improvement, execution, and capability gaps",
    plainEnglish: `The Brain found ${analysis.summary.gapCount} gap(s), converted them into ${analysis.abilityBacklog.length} closeable ability target(s), and saved the next execution route for each.`,
    realWorldData: analysis.summary,
    decisionMeasurement: {
      reason,
      abilityBacklogCount: analysis.abilityBacklog.length,
      topGap: analysis.gaps[0]?.id || ""
    },
    proceduralMemory: {
      futureUse: "Before adding another subsystem or rewriting an existing one, run Framework Gap Analysis and close the highest-priority execution or capability gap first.",
      abilities: analysis.abilityBacklog.slice(0, 8)
    },
    codexInterventionLevel: analysis.summary.executionGaps ? 1 : 0,
    resultMetric: {
      gapCount: analysis.summary.gapCount,
      abilityBacklogCount: analysis.abilityBacklog.length
    },
    evidence: analysis.gaps.slice(0, 6).map(gap => `${gap.type}:${gap.id}`),
    tags: ["framework-gap-analysis", "brain-learning", "meta-execution", "capability-building"]
  });
  return analysis;
}

function numericEvidenceValue(evidence = [], key = "") {
  const item = evidence.find(value => String(value || "").startsWith(`${key}=`));
  if (!item) return 0;
  return Number(String(item).split("=").slice(1).join("=")) || 0;
}

function ownerBrainStateSummary(memory = learningMemory(), diagnostics = null) {
  const analysis = subsystemCapabilityAnalysis(memory, diagnostics);
  const registry = analysis.registry || [];
  const patchSummary = patchProposalSummary(50);
  const averageReadiness = registry.length
    ? registry.reduce((sum, item) => sum + Number(item.readiness || 0), 0) / registry.length
    : 70;
  const confidence = clampScore((frameworkOptimizationScore(memory, diagnostics).score * 0.55) + (averageReadiness * 0.45));
  const activeSubsystems = registry
    .filter(item => /active|ready|awaiting/i.test(item.status || ""))
    .sort((a, b) => Number(b.readiness || 0) - Number(a.readiness || 0));
  const weakest = registry.slice().sort((a, b) => Number(a.readiness || 0) - Number(b.readiness || 0))[0] || null;
  const feed = registry.find(item => item.key === "feed-reliability") || weakest;
  const search = registry.find(item => item.key === "search-quality") || activeSubsystems[0] || weakest;
  const teachingNeeded = (patchSummary.recentProposals || []).filter(item =>
    item.patchStructuring?.teachingNeeded
    || (!(item.filePatches || []).length && ["pending-owner-approval", "approved-for-framework", "approved-for-codex"].includes(item.status))
  ).length;
  const subsystemTeachingNeeded = registry.filter(item => item.teachingNeeded || item.status === "lesson-application-gap" || /needs-teaching/.test(item.status || "")).length;
  const awaitingOwnerApproval = Number(patchSummary.totals?.pendingApprovalCount || 0);
  const feedErrors = numericEvidenceValue(feed?.evidence || [], "feedSourceErrors");
  const refreshFailures = numericEvidenceValue(feed?.evidence || [], "consecutiveRefreshFailures");
  const currentLatency = Number(diagnostics?.runtime?.lastRefreshMs || runtimeState.lastRefreshMs || 0);
  const latencyReduction = clampScore(feedErrors || refreshFailures || currentLatency > 2500 ? 32 : currentLatency > 1000 ? 18 : 10);
  const roadmapTarget = Math.max(80, Number(feed?.readiness || 0) + 20);
  const editorialApplication = editorialLessonApplicationMetrics(memory);
  const readinessTabs = registry.map(item => ({
    key: item.key,
    name: item.name,
    readiness: Number(item.readiness || 0),
    status: item.status || "unknown",
    reason: item.evidence || [],
    confidence: clampScore(Number(item.readiness || 0) + (item.revisionNeeded ? -4 : 6)),
    responsibility: item.responsibility,
    endpoint: item.privateEndpoint,
    requiredCapabilities: item.requiredCapabilities || [],
    missingCapabilities: item.missingCapabilities || [],
    revisionNeeded: Boolean(item.revisionNeeded),
    brainDecision: item.brainDecision || ""
  }));
  const maturity = frameworkMaturityScores(memory, diagnostics);
  return {
    generatedAt: new Date().toISOString(),
    frameworkMaturity: maturity,
    frameworkCapabilityAnalysis: frameworkCapabilityAnalysis(memory, diagnostics),
    contentOrchestration: readJsonFile(path.join(dataDir, "content-orchestration-report.json"), null) || contentOrchestrationAnalysis(memory, diagnostics),
    writingIntelligence: writingPatternLibrarySummary(memory),
    frameworkEvolutionSpiral: readJsonFile(path.join(dataDir, "framework-evolution-spiral-report.json"), null) || frameworkEvolutionSpiralAnalysis(memory, diagnostics),
    highImpactCapabilityPlan: readJsonFile(path.join(dataDir, "high-impact-capability-plan.json"), null) || highImpactCapabilityPlan(memory, diagnostics),
    brainState: {
      frameworkConfidence: confidence,
      frameworkMaturity: maturity.overall,
      mostActiveSubsystem: activeSubsystems[0]?.name || registry[0]?.name || "Unknown",
      mostImprovedSubsystem: search?.name || "Search Quality",
      weakestSubsystem: weakest?.name || "Unknown",
      mostValuableOpportunity: `Reduce feed latency by ${latencyReduction}%`,
      teachingNeeded: teachingNeeded + subsystemTeachingNeeded,
      awaitingOwnerApproval
    },
    subsystemReadiness: {
      overallScore: clampScore(averageReadiness),
      tabs: readinessTabs
    },
    roadmap: {
      currentGoal: feed?.readiness < 80 ? `Improve ${feed?.name || "Feed Reliability"}` : `Maintain ${feed?.name || "Feed Reliability"}`,
      currentReadiness: Number(feed?.readiness || 0),
      targetReadiness: roadmapTarget,
      nextPlannedAction: feedErrors || refreshFailures ? "Source Failure Isolation" : teachingNeeded ? "Patch Structuring Teaching" : "Continue Proactive Verification",
      expectedBenefit: `${latencyReduction || 10}% reduction in feed latency`,
      status: awaitingOwnerApproval ? "Awaiting owner approval" : teachingNeeded ? "Awaiting structured patch" : "Ready for proactive cycle",
      focusSubsystemKey: feed?.key || "feed-reliability"
    },
    proof: {
      feedSourceErrors: feedErrors,
      consecutiveRefreshFailures: refreshFailures,
      lastRefreshMs: currentLatency,
      patchTeachingNeeded: teachingNeeded,
      subsystemTeachingNeeded,
      pendingPatchApprovals: awaitingOwnerApproval,
      lessonCaptureVsApplication: {
        lessonCapture: "excellent",
        lessonApplication: editorialApplication.lessonApplicationGap >= 6 ? "needs-forceful-redeployment" : editorialApplication.lessonApplicationGap >= 3 ? "moderate" : "improving",
        repetitiveFeedbackSignals: editorialApplication.repetitiveFeedback,
        recentRewriteActions: editorialApplication.recentRewriteActions,
        lessonApplicationGap: editorialApplication.lessonApplicationGap
      }
    }
  };
}

function scoreFromPenalty(base = 100, penalty = 0) {
  return clampScore(Number(base || 0) - Number(penalty || 0));
}

function frameworkMaturityScoreItem(key, label, score, inputs = {}, why = "") {
  const normalized = clampScore(score);
  return {
    key,
    label,
    score: normalized,
    status: normalized >= 95 ? "excellent" : normalized >= 88 ? "strong" : normalized >= 78 ? "improving" : normalized >= 65 ? "developing" : "needs-work",
    why,
    inputs
  };
}

function frameworkMaturityScores(memory = learningMemory(), diagnostics = null) {
  const preparedEvolutionCache = readJsonFile(newsLabApiResponseCacheFile, null) || {};
  const published = preparedEvolutionCache.responses?.all || {};
  const intelligence = published.articleReadIntelligence || {};
  const pipeline = intelligence.brainPipeline || {};
  const graph = readJsonFile(newsLabKnowledgeGraphFile, defaultNewsLabKnowledgeGraph());
  const sourceRegistry = newsLabSourceReliabilityRegistry();
  const sourceEntries = Object.values(sourceRegistry.sources || {});
  const proof = frameworkLearningProofSummary(50);
  const actionSummary = frameworkActionLogSummary(80);
  const patchSummary = patchProposalSummary(50);
  const optimization = frameworkOptimizationScore(memory, diagnostics);
  const learning = learningSummary(memory);
  const subsystemAnalysis = subsystemCapabilityAnalysis(memory, diagnostics);
  const registry = subsystemAnalysis.registry || [];
  const averageSubsystemReadiness = registry.length
    ? registry.reduce((sum, item) => sum + Number(item.readiness || 0), 0) / registry.length
    : 70;
  const feed = diagnostics?.feedReliability || null;
  const feedSourceErrors = Number(diagnostics?.runtime?.feedSourceErrorCount || 0);
  const failedSources = Number(feed?.failedSourceCount || 0);
  const slowSources = Number(feed?.slowSourceCount || 0);
  const sourceDiversity = sourceEntries.length;
  const officialSourceCount = sourceEntries.filter(item => item.officialStatus).length;
  const correctionSignals = sourceEntries.reduce((sum, item) => sum + Number(item.correctionSignals || 0), 0);
  const sourceFailures = sourceEntries.reduce((sum, item) => sum + Number(item.failures || 0), 0);
  const recentActions = actionSummary.recentActions || [];
  const successfulActions = recentActions.filter(item => /applied|resolved|success|completed|verified/i.test(`${item.status || ""} ${item.result || ""} ${item.message || ""}`)).length;
  const totalActions = recentActions.length;
  const actionSuccessRate = totalActions ? successfulActions / totalActions * 100 : 72;
  const editorialLearning = newsLabEditorLearningSummary();
  const editorialIssueCounts = editorialLearning.issueCounts || {};
  const issueTotal = Object.values(editorialIssueCounts).reduce((sum, value) => sum + Number(value || 0), 0);
  const repeatedPatternSignals = Number(editorialIssueCounts["repetitive-sentence-leak"] || 0)
    + Number(editorialIssueCounts["coach-repeated-phrases"] || 0)
    + Number(editorialIssueCounts["generic-template-language"] || 0)
    + Number(editorialIssueCounts["paragraph-topic-contamination"] || 0)
    + Number(editorialIssueCounts["article-body-topic-drift"] || 0);
  const approvedShelf = intelligence.approvedArticleShelf || {};
  const finalApproved = Number(approvedShelf.finalShelfApproved || published.ownedStories?.length || 0);
  const currentApproved = Number(approvedShelf.currentBatchApproved || 0);
  const reviewedStories = Number(pipeline.reviewedStories || intelligence.prepublishQualityGate?.reviewedStoryCount || 0);
  const publishableStories = Number(pipeline.publishableStories || finalApproved || 0);
  const firstPassAcceptance = reviewedStories ? publishableStories / reviewedStories * 100 : 0;
  const pipelineReadiness = Number(pipeline.readiness || 0);
  const reasoningStage = pipeline.stageStats?.Reasoning?.averageScore || pipeline.stageStats?.["Reasoning"]?.averageScore || 0;
  const writingStage = pipeline.stageStats?.Writing?.averageScore || 0;
  const critiqueStage = pipeline.stageStats?.["Self Critique"]?.averageScore || 0;
  const publishingStage = pipeline.stageStats?.Publishing?.averageScore || 0;
  const graphNodeCount = Number(graph.nodeCount || Object.keys(graph.nodes || {}).length || 0);
  const graphEdgeCount = Number(graph.edgeCount || (graph.edges || []).length || 0);
  const recurringEntityCount = Object.values(graph.nodes || {}).filter(node => node.type !== "event" && Number(node.mentionCount || 0) >= 2).length;
  const proofCount = Number(proof.recentEntries?.length || 0);
  const adaptiveHistory = normalizeAdaptiveWeights(memory.adaptiveWeights).history.length;
  const runtimeFindings = Number(diagnostics?.aiShield?.findings?.length || 0) + Number(diagnostics?.functionality?.findings?.length || 0);
  const stabilityScore = scoreFromPenalty(96, runtimeFindings * 4 + Number(diagnostics?.runtime?.consecutiveRefreshFailures || 0) * 8 + (diagnostics?.status === "fallback" ? 14 : 0));
  const commercialScore = scoreFromPenalty(96, Number(diagnostics?.revenueGrowth?.findingCount || 0) * 7 + (publishableStories < 10 ? 6 : 0));
  const items = [
    frameworkMaturityScoreItem("framework", "Framework", optimization.score * 0.42 + averageSubsystemReadiness * 0.28 + actionSuccessRate * 0.16 + proofCount * 0.9, {
      optimizationScore: optimization.score,
      averageSubsystemReadiness: Number(averageSubsystemReadiness.toFixed(1)),
      actionSuccessRate: Number(actionSuccessRate.toFixed(1)),
      proofEntries: proofCount
    }, "Subsystem health, verified actions, proof entries, and optimization memory."),
    frameworkMaturityScoreItem("architecture", "Architecture", 92 + Math.min(6, registry.length * 0.35) - Math.min(10, subsystemAnalysis.gaps?.length || 0), {
      subsystemCount: registry.length,
      gapCount: subsystemAnalysis.gaps?.length || 0,
      patchApplyEnabled: frameworkPatchApplyEnabled
    }, "Layered subsystems, patch governance, owner approval, and cross-role architecture."),
    frameworkMaturityScoreItem("storyPipeline", "Story Pipeline", pipelineReadiness * 0.58 + firstPassAcceptance * 0.22 + Math.min(100, finalApproved * 5) * 0.2, {
      pipelineReadiness,
      firstPassAcceptance: Number(firstPassAcceptance.toFixed(1)),
      finalApproved,
      currentBatchApproved: currentApproved
    }, "Publication success, repair pressure, and article shelf output."),
    frameworkMaturityScoreItem("writerReasoning", "Writer Reasoning", reasoningStage * 0.58 + Math.min(100, Number(intelligence.dossierSourceStoryCount || 0) / 2) * 0.18 + Math.min(100, Number(intelligence.generatedFromFullReads || 0) * 10) * 0.14 + writingStage * 0.1, {
      reasoningStage,
      writingStage,
      dossierSourceStories: Number(intelligence.dossierSourceStoryCount || 0),
      generatedFromFullReads: Number(intelligence.generatedFromFullReads || 0)
    }, "Whether the Writer starts from a complete dossier instead of thin feed text."),
    frameworkMaturityScoreItem("editorialIntelligence", "Editorial Intelligence", writingStage * 0.32 + critiqueStage * 0.32 + firstPassAcceptance * 0.18 + scoreFromPenalty(100, repeatedPatternSignals * 2.5) * 0.18, {
      writingStage,
      selfCritiqueStage: critiqueStage,
      firstPassAcceptance: Number(firstPassAcceptance.toFixed(1)),
      repeatedPatternSignals,
      totalEditorIssueSignals: issueTotal
    }, "Originality, editor acceptance, repeated phrase reduction, and self-critique strength."),
    frameworkMaturityScoreItem("feedIntelligence", "Feed Intelligence", scoreFromPenalty(94, failedSources * 2 + slowSources * 1.5 + Math.min(18, feedSourceErrors / 8)) + Math.min(6, sourceDiversity / 80), {
      sourceDiversity,
      officialSourceCount,
      failedSources,
      slowSources,
      feedSourceErrors,
      correctionSignals,
      sourceFailures
    }, "Provider telemetry, source weighting, source diversity, and bounded feed health."),
    frameworkMaturityScoreItem("knowledgeGraph", "Knowledge Graph", 48 + Math.min(22, graphNodeCount / 18) + Math.min(18, graphEdgeCount / 35) + Math.min(12, recurringEntityCount * 1.5), {
      nodeCount: graphNodeCount,
      edgeCount: graphEdgeCount,
      recurringEntityCount,
      recentEventCount: Number(graph.recentEvents?.length || 0)
    }, "People, organizations, events, timelines, and reusable entity memory."),
    frameworkMaturityScoreItem("learningSystem", "Learning System", 58 + Math.min(18, proofCount * 1.5) + Math.min(12, adaptiveHistory * 0.8) + Math.min(12, Number(learning.selfImprovementCycleCount || 0) * 0.5), {
      proofEntries: proofCount,
      adaptiveHistory,
      selfImprovementCycles: Number(learning.selfImprovementCycleCount || 0),
      frameworkCommands: Number(learning.frameworkCommandCount || 0)
    }, "Pattern learning, adaptive weights, proof logs, and reusable command memory."),
    frameworkMaturityScoreItem("runtimeStability", "Runtime Stability", stabilityScore, {
      health: diagnostics?.health || "unknown",
      runtimeFindings,
      consecutiveRefreshFailures: Number(diagnostics?.runtime?.consecutiveRefreshFailures || 0),
      status: diagnostics?.status || "unknown"
    }, "Crashes, fallback state, refresh failures, and active health findings."),
    frameworkMaturityScoreItem("commercialReadiness", "Commercial Readiness", commercialScore, {
      revenueFindings: Number(diagnostics?.revenueGrowth?.findingCount || 0),
      publishableStories,
      adsensePresent: Boolean(diagnostics?.revenueGrowth?.signals?.adsenseScriptPresent || diagnostics?.revenueGrowth?.adsenseScriptPresent)
    }, "Monetization readiness, content volume, and revenue findings.")
  ];
  const weights = {
    framework: 0.12,
    architecture: 0.1,
    storyPipeline: 0.14,
    writerReasoning: 0.14,
    editorialIntelligence: 0.13,
    feedIntelligence: 0.1,
    knowledgeGraph: 0.09,
    learningSystem: 0.08,
    runtimeStability: 0.06,
    commercialReadiness: 0.04
  };
  const overall = clampScore(items.reduce((sum, item) => sum + item.score * Number(weights[item.key] || 0.08), 0));
  const weakest = [...items].sort((a, b) => a.score - b.score)[0] || null;
  const strongest = [...items].sort((a, b) => b.score - a.score)[0] || null;
  return {
    generatedAt: new Date().toISOString(),
    version: "20260704-framework-maturity-scorecard",
    overall,
    label: overall >= 95 ? "near-production-grade" : overall >= 88 ? "strong-and-improving" : overall >= 78 ? "building-strength" : "needs-focused-improvement",
    items,
    weakest,
    strongest,
    nextAction: weakest ? `Improve ${weakest.label}: ${weakest.why}` : "Continue measuring each maturity lane.",
    formula: "Weighted score from subsystem readiness, Brain pipeline stages, feed telemetry, learning proof, knowledge graph coverage, runtime health, and commercial readiness.",
    rule: "The Framework should score itself from measurable behavior, then target the lowest maturity lane until the next measurement proves improvement."
  };
}
function frameworkCapabilityItem(key, label, score, current = "", evidence = [], nextImprovement = "", subsystem = "") {
  const normalized = clampScore(score);
  return {
    key,
    label,
    score: normalized,
    status: normalized >= 90 ? "strong" : normalized >= 75 ? "developing" : normalized >= 55 ? "early" : "gap",
    current,
    evidence: normalizeStringList(evidence, 12),
    nextImprovement,
    subsystem,
    questions: {
      canBrainDoThisToday: normalized >= 55,
      howWell: normalized,
      evidenceSupportsAssessment: normalizeStringList(evidence, 8),
      materialImprovement: nextImprovement
    }
  };
}

function frameworkCapabilityCenter(analysis = {}, memory = learningMemory(), diagnostics = null) {
  const capabilities = Array.isArray(analysis.capabilities) ? analysis.capabilities : [];
  const evolution = readJsonFile(path.join(dataDir, "framework-evolution-spiral-report.json"), null) || null;
  const writing = writingPatternLibrarySummary(memory);
  const application = applicationIntelligenceSummary();
  const actionSummary = frameworkActionLogSummary(100);
  const proof = frameworkLearningProofSummary(100);
  const weakest = [...capabilities].sort((a, b) => Number(a.score || 0) - Number(b.score || 0))[0] || null;
  const strategicCandidates = capabilities.map(item => {
    const gap = clampScore(100 - Number(item.score || 0));
    const verificationNeed = /execution|autonomy|recovery/i.test(item.key || "") ? 12 : 6;
    const strategicWeight = /prediction|reasoning|planning|autonomy|execution/i.test(item.key || "") ? 1.18 : 1;
    const ownerPriority = /prediction|reasoning|planning|autonomy|execution/i.test(item.key || "") ? 10 : /editorial|learning/i.test(item.key || "") ? 7 : 4;
    return {
      key: item.key,
      label: item.label,
      score: item.score,
      evidence: item.evidence || [],
      proposedImprovement: item.nextImprovement || "",
      subsystem: item.subsystem || "",
      expectedLift: clampScore((gap * 0.35) + ownerPriority),
      strategicValue: Number(((gap + ownerPriority + verificationNeed) * strategicWeight).toFixed(1)),
      verificationNeed,
      rollbackNeed: /execution|autonomy|patch|recovery/i.test(`${item.key} ${item.subsystem}`) ? "required" : "standard",
      reason: `score=${item.score}; gap=${gap}; strategicPriority=${ownerPriority}`
    };
  }).sort((a, b) => Number(b.strategicValue || 0) - Number(a.strategicValue || 0));
  const chosen = strategicCandidates[0] || null;
  const causalQuestions = [
    "Did feed/source quality reduce dossier completeness?",
    "Did dossier weakness increase editor rejection?",
    "Did headline pattern failure lower article approval?",
    "Did runtime load reduce publication output?",
    "Did owner-approved changes improve the metric they targeted?"
  ];
  const capabilityPromotion = (evolution?.capabilityRegistry || []).slice(0, 8);
  const patternGeneralization = {
    weakestPattern: writing.weakestPattern?.key || "unknown",
    weakestPatternSuccessRate: Number(writing.weakestPattern?.successRate || 0),
    rule: "Promote patterns only after repeated verified success; keep failed patterns in repair memory."
  };
  return {
    generatedAt: new Date().toISOString(),
    version: "20260705-capability-center-v1",
    centralQuestion: "What is my weakest capability, what evidence supports that conclusion, and what single improvement would raise it the most?",
    weakestCapability: weakest,
    strategicDecision: chosen ? {
      highestValueImprovement: chosen.proposedImprovement,
      targetCapability: chosen.label,
      targetSubsystem: chosen.subsystem,
      expectedLift: chosen.expectedLift,
      strategicValue: chosen.strategicValue,
      whyThisNow: chosen.reason,
      verificationPlan: [
        `Measure ${chosen.label} before change.`,
        "Apply one bounded improvement.",
        "Measure the same capability after the change.",
        "Promote only if the metric improves and no dependent capability regresses."
      ],
      rollbackPlan: chosen.rollbackNeed === "required"
        ? "Keep rollback instructions mandatory before execution; revert if the target metric or public site behavior regresses."
        : "Use standard rollback if the measured capability drops after the change."
    } : null,
    nextGenerationFocus: [
      "Predictive reasoning",
      "Causal reasoning",
      "Strategic planning",
      "Pattern generalization",
      "Execution autonomy with verification and rollback"
    ],
    candidates: strategicCandidates.slice(0, 6),
    causalReasoning: {
      status: capabilities.find(item => item.key === "reasoning")?.score >= 75 ? "developing" : "gap",
      questions: causalQuestions,
      rule: "The Brain should connect causes across feed quality, dossier quality, writing quality, runtime load, and publication output before choosing a fix."
    },
    patternGeneralization,
    executionAutonomy: {
      verifiedActions: Number(actionSummary.totals?.verifiedActionCount || 0),
      improvedActions: Number(actionSummary.totals?.metricImprovedActionCount || 0),
      rule: "Autonomy increases only when execution is verified and rollback remains available."
    },
    capabilityPromotion,
    applicationIntelligence: application,
    proofSignals: {
      proofEntries: Number(proof.recentEntries?.length || 0),
      evolutionOverall: Number(evolution?.overall || 0),
      metaLearnerScore: Number(evolution?.metaLearner?.score || 0)
    },
    rule: "Capability Analysis is Framework 2.0's command center; feature work should follow the highest-value capability improvement."
  };
}

function highImpactCapabilityPlan(memory = learningMemory(), diagnostics = null) {
  const published = readJsonFile(newsLabPublishedPayloadFile, null) || {};
  const intelligence = published.articleReadIntelligence || {};
  const pipeline = intelligence.brainPipeline || {};
  const writing = writingPatternLibrarySummary(memory);
  const capabilityReport = readJsonFile(path.join(dataDir, "framework-capability-analysis-report.json"), null) || {};
  const capabilityMap = Object.fromEntries((capabilityReport.capabilities || []).map(item => [item.key, item]));
  const graph = readJsonFile(newsLabKnowledgeGraphFile, defaultNewsLabKnowledgeGraph());
  const actionSummary = frameworkActionLogSummary(120);
  const sourceRegistry = newsLabSourceReliabilityRegistry();
  const sourceEntries = Object.values(sourceRegistry.sources || {});
  const patternByKey = Object.fromEntries((writing.patterns || []).map(item => [item.key, item]));
  const headlineSuccess = Number(patternByKey.headline?.successRate || 0);
  const structureSuccess = Number(patternByKey.structure?.successRate || 0);
  const evidenceSuccess = Number(patternByKey.evidence?.successRate || 0);
  const approvedStories = Number(published.ownedStories?.length || 0);
  const dossierStories = Number(intelligence.dossierSourceStoryCount || published.dossierSourceStoryCount || 0);
  const sourceFamilies = new Set(sourceEntries.map(source => source.sourceFamily || source.sourceType || "unknown")).size;
  const predictionScore = Number(capabilityMap.prediction?.score || 0);
  const reasoningScore = Number(capabilityMap.reasoning?.score || 0);
  const executionScore = Number(capabilityMap.execution?.score || 0);
  const verifiedActions = Number(actionSummary.totals?.verifiedActionCount || 0);
  const improvedActions = Number(actionSummary.totals?.metricImprovedActionCount || 0);
  const issueCounts = memory.editorDecisionMemory?.issueCounts || {};
  const headlineFailures = Number(issueCounts["headline-word-salad"] || 0)
    + Number(issueCounts["headline-editor-needs-rewrite"] || 0)
    + Number(issueCounts["headline-source-no-overlap"] || 0)
    + Number(issueCounts["generic-weak-headline"] || 0);
  const dossierFailures = Number(issueCounts["article-body-topic-drift"] || 0)
    + Number(issueCounts["mixed-source-topic"] || 0)
    + Number(issueCounts["insufficient-full-article-facts"] || 0)
    + Number(issueCounts["paragraph-topic-contamination"] || 0);
  const lanes = [
    {
      key: "headline-intelligence",
      label: "Headline Intelligence",
      score: clampScore(headlineSuccess),
      impact: 98,
      evidence: [`headlineSuccess=${headlineSuccess}`, `headlineFailures=${headlineFailures}`],
      operatingRule: "Generate headlines only after the CE article and Story Dossier are complete.",
      reasoningRule: "Use main actor + specific action + consequence from the dossier; reject word salad, copied structure, truncation, and source mismatch.",
      correctionRule: "If a headline fails, rerun Headline Dossier Builder with required actor/action/consequence fields before the Editor sees it again.",
      executionRule: "Produce at least five candidate headlines, score each against evidence overlap and natural grammar, then publish the first passing candidate.",
      verificationMetric: "headline pattern success rate and headline-source-overlap must improve on the next writing cycle.",
      nextAction: "Make headline repair the first writer repair pass, not a final polish pass."
    },
    {
      key: "story-dossier-builder",
      label: "Story Dossier Builder",
      score: clampScore(44 + Math.min(28, dossierStories / 10) + Math.min(18, sourceFamilies * 3) - Math.min(24, dossierFailures / 8)),
      impact: 96,
      evidence: [`dossierStories=${dossierStories}`, `sourceFamilies=${sourceFamilies}`, `dossierFailures=${dossierFailures}`],
      operatingRule: "The Writer receives a structured dossier, not RSS snippets or raw publisher summaries.",
      reasoningRule: "Classify who, what, when, where, official evidence, independent reports, contradictions, unknowns, and confidence before writing.",
      correctionRule: "If topic drift appears, demote the draft and rebuild the dossier cluster before attempting another article.",
      executionRule: "Collector and sub-dossier workers must feed tab-specific evidence into the main dossier before Writer selection.",
      verificationMetric: "article-body-topic-drift, mixed-source-topic, and insufficient-full-article-facts must decline.",
      nextAction: "Add a hard ready-for-writer gate requiring known facts, evidence classes, and topic-isolation score."
    },
    {
      key: "predictive-brain",
      label: "Predictive Brain",
      score: clampScore(predictionScore),
      impact: 94,
      evidence: [`predictionScore=${predictionScore}`, `pipelineReadiness=${pipeline.readiness || 0}`],
      operatingRule: "Forecast degradation before it affects public output.",
      reasoningRule: "Use trends across feed latency, source failures, dossier completeness, editor rejections, and article output.",
      correctionRule: "When a metric trends down twice, create a preventive action instead of waiting for a public failure.",
      executionRule: "Attach a next-check deadline and target metric to every preventive action.",
      verificationMetric: "forecastSignals, preventedFailures, and post-action metric improvements.",
      nextAction: "Create source/article/editor risk forecasts for the next rebuild cycle."
    },
    {
      key: "cross-subsystem-reasoning",
      label: "Cross-Subsystem Reasoning",
      score: clampScore((reasoningScore * 0.55) + Math.min(35, verifiedActions / 3) + Math.min(10, Number(graph.edgeCount || (graph.edges || []).length) / 1000)),
      impact: 92,
      evidence: [`reasoningScore=${reasoningScore}`, `verifiedActions=${verifiedActions}`, `graphEdges=${graph.edgeCount || (graph.edges || []).length || 0}`],
      operatingRule: "No subsystem should diagnose in isolation when another subsystem may be the cause.",
      reasoningRule: "Test causal chains: feed quality -> dossier quality -> writer quality -> editor acceptance -> public output.",
      correctionRule: "When a downstream stage fails, inspect upstream telemetry before changing the downstream subsystem.",
      executionRule: "Write a causal note into proof memory for every high-impact repair.",
      verificationMetric: "causal links recorded and repeated failures reduced after upstream repair.",
      nextAction: "Add causal scoring between feed reliability, dossier quality, headline quality, and article approvals."
    },
    {
      key: "writer-editor-pattern-learning",
      label: "Writer Learning From Editor Patterns",
      score: clampScore((headlineSuccess * 0.28) + (structureSuccess * 0.24) + (evidenceSuccess * 0.28) + Math.min(20, Number(writing.recentLessons?.length || 0))),
      impact: 90,
      evidence: [`headlineSuccess=${headlineSuccess}`, `structureSuccess=${structureSuccess}`, `evidenceSuccess=${evidenceSuccess}`],
      operatingRule: "The Writer reads pattern lessons before drafting, while the Story Dossier supplies facts.",
      reasoningRule: "Treat editor decisions as craft lessons, not content to imitate.",
      correctionRule: "Every repeated rejection becomes a pre-draft prevention rule for the Writer, Headline Editor, and Dossier Builder.",
      executionRule: "Before each draft, apply the top three failing pattern rules from Writing Intelligence.",
      verificationMetric: "first-pass acceptance and pattern success rates must rise without weakening editor gates.",
      nextAction: "Turn the weakest pattern into the first required writer instruction for the next cycle."
    }
  ].map(lane => ({
    ...lane,
    priority: Number(((100 - Number(lane.score || 0)) * 0.62 + Number(lane.impact || 0) * 0.38).toFixed(1)),
    status: lane.score >= 85 ? "strong" : lane.score >= 65 ? "developing" : lane.score >= 40 ? "needs-focus" : "critical"
  })).sort((a, b) => b.priority - a.priority);
  const top = lanes[0] || null;
  return {
    generatedAt: new Date().toISOString(),
    version: "20260706-high-impact-capability-plan-v1",
    purpose: "Improve how the five highest-impact Brain capabilities operate, reason, produce, correct, and execute.",
    overall: clampScore(lanes.reduce((sum, lane) => sum + lane.score, 0) / Math.max(1, lanes.length)),
    topPriority: top,
    lanes,
    executionOrder: lanes.map(lane => lane.label),
    sharedVerificationRule: "Every high-impact improvement must name the metric it expects to improve, rerun after execution, and record whether the metric moved.",
    rollbackRule: "If a change reduces public output, weakens editor gates, or increases topic drift/headline mismatch, revert that change and preserve the lesson as a failed experiment.",
    rule: "Visible quality improves fastest when Headline Intelligence, Story Dossier Builder, Predictive Brain, Cross-subsystem Reasoning, and Writer/Editor Pattern Learning improve together."
  };
}

function saveHighImpactCapabilityPlan(reason = "manual") {
  const plan = highImpactCapabilityPlan(learningMemory(), null);
  writeJsonFile(path.join(dataDir, "high-impact-capability-plan.json"), plan);
  saveFrameworkLearningProofEntry({
    category: "high-impact-capability-plan",
    event: "Brain ranked the five highest-impact quality capabilities",
    plainEnglish: `The Brain measured the five largest visible quality levers and selected ${plan.topPriority?.label || "unknown"} as the highest-priority improvement lane.`,
    realWorldData: { reason, topPriority: plan.topPriority, executionOrder: plan.executionOrder },
    decisionMeasurement: {
      overall: plan.overall,
      topPriority: plan.topPriority?.key || "",
      topPriorityScore: plan.topPriority?.score || 0
    },
    proceduralMemory: {
      futureUse: "Before improving News Lab quality, run the high-impact capability plan and repair the highest-priority lane first.",
      sharedVerificationRule: plan.sharedVerificationRule
    },
    resultMetric: {
      highImpactOverall: plan.overall,
      laneCount: plan.lanes.length
    },
    evidence: plan.lanes.map(lane => `${lane.label}=${lane.score}:${lane.status}`),
    tags: ["high-impact-capabilities", "headline-intelligence", "story-dossier", "predictive-brain", "cross-subsystem-reasoning", "writer-learning"]
  });
  return plan;
}

function frameworkCapabilityAnalysis(memory = learningMemory(), diagnostics = null) {
  const maturity = frameworkMaturityScores(memory, diagnostics);
  const gapAnalysis = frameworkGapAnalysis(memory, diagnostics);
  const published = readJsonFile(newsLabPublishedPayloadFile, null) || {};
  const intelligence = published.articleReadIntelligence || {};
  const pipeline = intelligence.brainPipeline || {};
  const sourceRegistry = newsLabSourceReliabilityRegistry();
  const sourceEntries = Object.values(sourceRegistry.sources || {});
  const proof = frameworkLearningProofSummary(100);
  const actions = frameworkActionLogSummary(100);
  const editorLearning = newsLabEditorLearningSummary();
  const issueCounts = editorLearning.issueCounts || {};
  const repeatedFailures = Number(issueCounts["repetitive-sentence-leak"] || 0)
    + Number(issueCounts["coach-repeated-phrases"] || 0)
    + Number(issueCounts["generic-template-language"] || 0)
    + Number(issueCounts["paragraph-topic-contamination"] || 0)
    + Number(issueCounts["article-body-topic-drift"] || 0)
    + Number(issueCounts["headline-word-salad"] || 0);
  const totalEditorSignals = Object.values(issueCounts).reduce((sum, value) => sum + Number(value || 0), 0);
  const actionTotals = actions.totals || {};
  const actionCount = Number(actionTotals.actionCount || 0);
  const improvedActions = Number(actionTotals.metricImprovedActionCount || 0);
  const verifiedActions = Number(actionTotals.verifiedActionCount || 0);
  const actionImprovementRate = actionCount ? improvedActions / actionCount * 100 : 40;
  const verificationRate = actionCount ? verifiedActions / actionCount * 100 : 45;
  const officialSources = sourceEntries.filter(source => source.evidenceClasses?.government || source.officialStatus).length;
  const courtSources = sourceEntries.filter(source => source.evidenceClasses?.court || source.sourceFamily === "court").length;
  const researchSources = sourceEntries.filter(source => source.evidenceClasses?.research || source.sourceFamily === "research").length;
  const sourceFamilyCount = new Set(sourceEntries.map(source => source.sourceFamily || source.sourceType || "unknown")).size;
  const storyCount = Number(published.ownedStories?.length || 0);
  const finalApproved = Number(intelligence.approvedArticleShelf?.finalShelfApproved || storyCount || 0);
  const reviewedStories = Number(pipeline.reviewedStories || intelligence.prepublishQualityGate?.reviewedStoryCount || 0);
  const publishableStories = Number(pipeline.publishableStories || finalApproved || 0);
  const firstPassAcceptance = reviewedStories ? publishableStories / reviewedStories * 100 : 0;
  const contradictionCount = (published.ownedStories || []).reduce((sum, story) => sum + Number(story.contradictionDetection?.count || story.storyDossier?.contradictions?.length || 0), 0);
  const timelineCount = (published.ownedStories || []).reduce((sum, story) => sum + Number(story.storyEvolution?.timeline?.length || story.storyDossier?.timeline?.length || 0), 0);
  const forecastSignals = proof.recentEntries.filter(entry => /predict|forecast|trend|likely|preventive/i.test(`${entry.event || ""} ${entry.plainEnglish || ""} ${(entry.tags || []).join(" ")}`)).length;
  const experimentSignals = proof.recentEntries.filter(entry => /experiment|compare|version a|version b|winner|control/i.test(`${entry.event || ""} ${entry.plainEnglish || ""} ${(entry.tags || []).join(" ")}`)).length;
  const consolidationSignals = proof.recentEntries.filter(entry => /consolidat|merge duplicate|stale lesson|permanent knowledge|90 day|weekly/i.test(`${entry.event || ""} ${entry.plainEnglish || ""} ${(entry.tags || []).join(" ")}`)).length;
  const maturityByKey = Object.fromEntries((maturity.items || []).map(item => [item.key, item]));
  const learningScore = clampScore(Number(maturityByKey.learningSystem?.score || 0) - Math.min(18, repeatedFailures / 20));
  const reasoningScore = clampScore(Number(maturityByKey.writerReasoning?.score || 0));
  const predictionScore = clampScore(35 + Math.min(25, forecastSignals * 5) + Math.min(20, Number(maturityByKey.feedIntelligence?.score || 0) / 5));
  const planningScore = clampScore(45 + Math.min(20, Number(gapAnalysis.abilityBacklog?.length || 0) * 3) + Math.min(20, Number(pipeline.readiness || 0) / 5));
  const executionScore = clampScore(50 + actionImprovementRate * 0.28 + verificationRate * 0.22);
  const recoveryScore = clampScore(Number(maturityByKey.runtimeStability?.score || 0) * 0.65 + verificationRate * 0.25 + Math.min(10, actionCount / 20));
  const knowledgeScore = clampScore(Number(maturityByKey.knowledgeGraph?.score || 0) + Math.min(6, consolidationSignals * 2));
  const editorialScore = clampScore(Number(maturityByKey.editorialIntelligence?.score || 0));
  const investigationScore = clampScore(38 + Math.min(18, sourceFamilyCount * 4) + Math.min(14, officialSources * 2) + Math.min(10, courtSources * 3) + Math.min(10, researchSources * 2) + Math.min(10, contradictionCount) + Math.min(10, timelineCount / 4));
  const autonomyScore = clampScore(42 + actionImprovementRate * 0.22 + verificationRate * 0.26 + Math.min(14, Number(actions.totals?.autonomousActionCount || 0) / 10) - Math.min(12, gapAnalysis.summary.executionGaps * 4));
  const capabilities = [
    frameworkCapabilityItem("learning", "Learning", learningScore, "Learns from articles, editor decisions, owner feedback, source behavior, patch history, and proof logs.", [`editorSignals=${totalEditorSignals}`, `repeatedPatternSignals=${repeatedFailures}`, `proofEntries=${proof.recentEntries.length}`], "Build Pattern Intelligence so repeated article/editor failures become pattern-level rules with failure rates.", "Pattern Intelligence"),
    frameworkCapabilityItem("reasoning", "Reasoning", reasoningScore, "Reasons through dossier inputs, writer handoff, evidence, context, and self-critique.", [`writerReasoning=${maturityByKey.writerReasoning?.score || 0}`, `pipelineReadiness=${pipeline.readiness || 0}`, `firstPassAcceptance=${firstPassAcceptance.toFixed(1)}`], "Require every story to pass through Dossier -> Evidence -> Context -> Hypothesis/Counterfactual checks before drafting.", "Context Reasoning Engine"),
    frameworkCapabilityItem("prediction", "Prediction", predictionScore, "Has trend signals but is still more reactive than predictive.", [`forecastSignals=${forecastSignals}`, `feedIntelligence=${maturityByKey.feedIntelligence?.score || 0}`], "Forecast feed, source, article-output, and editor-rejection degradation before it affects publication.", "Predictive Intelligence"),
    frameworkCapabilityItem("planning", "Planning", planningScore, "Creates tasking and roadmaps, but still needs richer milestone/dependency planning.", [`abilityBacklog=${gapAnalysis.abilityBacklog?.length || 0}`, `gapCount=${gapAnalysis.summary.gapCount}`, `pipelineReadiness=${pipeline.readiness || 0}`], "Turn every owner goal into milestones, dependencies, resource needs, verification points, and finish criteria.", "Planning Engine"),
    frameworkCapabilityItem("execution", "Execution", executionScore, "Executes bounded actions and approved structured patches, but some actions still lack verified improvement.", [`actionCount=${actionCount}`, `metricImprovedActions=${improvedActions}`, `verifiedActions=${verifiedActions}`], "Attach a mandatory post-action verification window and next-check deadline to every Brain action.", "Execution Scheduler"),
    frameworkCapabilityItem("recovery", "Recovery", recoveryScore, "Handles some runtime failures with fallbacks, but recovery needs stronger automatic close-the-loop behavior.", [`runtimeStability=${maturityByKey.runtimeStability?.score || 0}`, `verifiedActions=${verifiedActions}`], "Detect failure, recover, verify the same metric, and store prevention memory without waiting for owner notice.", "Recovery Engine"),
    frameworkCapabilityItem("knowledge", "Knowledge", knowledgeScore, "Maintains source registry, article memory, knowledge graph, and entity memory.", [`sourceCount=${sourceEntries.length}`, `sourceFamilies=${sourceFamilyCount}`, `consolidationSignals=${consolidationSignals}`], "Add weekly Knowledge Consolidation: summarize lessons, merge duplicates, retire stale lessons, promote permanent knowledge.", "Knowledge Consolidation"),
    frameworkCapabilityItem("editorial", "Editorial", editorialScore, "Editor and writer learn from decisions, but pattern learning and pre-draft application need more force.", [`editorialScore=${maturityByKey.editorialIntelligence?.score || 0}`, `firstPassAcceptance=${firstPassAcceptance.toFixed(1)}`, `repeatedPatternSignals=${repeatedFailures}`], "Make the Writer read pattern-level Editorial Memory before drafting and block known-failing patterns earlier.", "Editorial Intelligence v2"),
    frameworkCapabilityItem("investigation", "Investigation", investigationScore, "Has source triangulation, timeline, contradiction, and evidence classification pieces, but needs stronger newsroom tooling.", [`officialSources=${officialSources}`, `courtSources=${courtSources}`, `researchSources=${researchSources}`, `contradictions=${contradictionCount}`, `timelineItems=${timelineCount}`], "Strengthen contradiction detection, source triangulation, fact provenance, entity relationship tracking, and follow-up recommendations.", "Investigation Desk"),
    frameworkCapabilityItem("autonomy", "Autonomy", autonomyScore, "Can act in bounded areas and apply owner-approved structured patches, but still depends on verification and teaching loops.", [`autonomousActions=${actions.totals?.autonomousActionCount || 0}`, `executionGaps=${gapAnalysis.summary.executionGaps}`, `verificationRate=${verificationRate.toFixed(1)}`], "Promote repeated successful Codex-taught operations into reusable Brain abilities with approval gates and measurable verification.", "Autonomy Governor")
  ];
  const capabilityTable = [
    { capability: "Headline generation", current: "Moderate", evidence: "High rewrite/rejection counts and recent Headline Dossier upgrade.", nextImprovement: "Generate and validate from structured headline dossiers after article body is complete." },
    { capability: "Editorial learning", current: "Strong", evidence: "Persistent editor learning logs and subsystem directives.", nextImprovement: "Learn reusable writing patterns across many articles with pattern failure percentages." },
    { capability: "Source evaluation", current: "Strong", evidence: "Source Reliability Registry v2 tracks source family, evidence weight, availability, corrections, and originality.", nextImprovement: "Add long-term performance trends and source-type validation." },
    { capability: "Cross-subsystem reasoning", current: "Developing", evidence: "Independent subsystem telemetry exists; causal chains are emerging.", nextImprovement: "Build causal links between feed quality, dossier strength, writing quality, and publication outcomes." },
    { capability: "Predictive maintenance", current: "Early", evidence: "Trend tracking exists, but preventive forecasts are limited.", nextImprovement: "Forecast subsystem degradation before it affects publication." }
  ];
  const proposedSubsystems = [
    { level: "Learning", name: "Pattern Intelligence", purpose: "Recognize repeated failed writing/code/source patterns across many records and attach failure rates." },
    { level: "Learning", name: "Causal Learning Engine", purpose: "Connect feed reliability, dossier quality, editor rejection, and publication output into causal chains." },
    { level: "Learning", name: "Knowledge Consolidation", purpose: "Weekly lesson summary, duplicate merge, stale lesson retirement, and permanent knowledge promotion." },
    { level: "Improvement", name: "Improvement Optimizer", purpose: "Rank improvements by expected return and work the highest-value item first." },
    { level: "Improvement", name: "Predictive Intelligence", purpose: "Forecast likely failure or degradation and trigger preventive action." },
    { level: "Improvement", name: "Experiment Manager", purpose: "Compare Version A/Version B changes, learn from outcomes, and keep the winner." },
    { level: "Execution", name: "Planning Engine", purpose: "Turn goals into milestones, dependencies, execution plans, and finish criteria." },
    { level: "Execution", name: "Execution Scheduler", purpose: "Prioritize CPU, memory, API calls, time, and worker attention." },
    { level: "Execution", name: "Recovery Engine", purpose: "Detect failures, recover, verify, and convert recovery into prevention memory." }
  ];
  const newsroomAbilities = ["investigative journalism support", "contradiction detection", "timeline generation", "source triangulation", "fact provenance", "entity relationship tracking", "impact analysis", "audience-specific summaries", "multilingual reporting", "follow-up recommendations"];
  const overall = clampScore(capabilities.reduce((sum, item) => sum + item.score, 0) / Math.max(1, capabilities.length));
  const weakest = [...capabilities].sort((a, b) => a.score - b.score)[0] || null;
  const analysis = {
    generatedAt: new Date().toISOString(),
    version: "20260705-framework-capability-analysis",
    purpose: "Treat the Brain like a real organization: measure observable capabilities, identify gaps, and turn missing capability into teachable ability.",
    overall,
    weakest,
    capabilities,
    proposedSubsystems,
    newsroomAbilities,
    capabilityTable,
    frameworkGapAnalysis: gapAnalysis.summary,
    maturityModel: capabilities.map(item => ({ key: item.key, label: item.label, score: item.score, status: item.status })),
    rule: "Every capability asks four questions: can the Brain do this today, how well, what evidence supports it, and what would make it materially better."
  };
  analysis.capabilityCenter = frameworkCapabilityCenter(analysis, memory, diagnostics);
  return analysis;
}

