function sentenceCase(value = "") {
  const text = cleanNewsletterCopy(value);
  return text ? `${text.charAt(0).toUpperCase()}${text.slice(1)}` : "";
}

function sentenceFromLabel(label = "") {
  const text = sentenceCase(label).replace(/[.]+$/g, "");
  return text ? `${text}.` : "";
}

function readableStance(value = "") {
  const text = cleanNewsletterCopy(value).replace(/[.]+$/g, "");
  if (!text) return "it deserves careful judgment.";
  if (text.startsWith("for ")) return `we should favor ${text.slice(4)}.`;
  if (text.startsWith("against ")) return `we should resist ${text.slice(8)}.`;
  return `${text}.`;
}

function newsletterSignalKey(story = {}) {
  return [
    reportClusterKey(story),
    storyMatter(story),
    cleanNewsletterCopy(story.title || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim().slice(0, 90)
  ].filter(Boolean).join("::");
}

function isDistinctNewsletterStory(story = {}, selected = []) {
  const key = newsletterSignalKey(story);
  return !selected.some(existing =>
    existing.url === story.url
    || newsletterSignalKey(existing) === key
    || reportClusterKey(existing) === reportClusterKey(story)
    || keywordOverlap(existing, story) >= 3
  );
}

function distinctNewsletterStories(stories = [], limit = 7) {
  const selected = [];
  const cleaned = stories
    .filter(isPublishableStory)
    .filter(story => !isGenericStory(story))
    .filter((story, index, all) => all.findIndex(match => match.url === story.url || newsletterSignalKey(match) === newsletterSignalKey(story)) === index);
  cleaned.forEach(story => {
    if (selected.length < limit && isDistinctNewsletterStory(story, selected)) selected.push(story);
  });
  return selected;
}

function newsletterStoryQuestion(signal = {}, index = 0) {
  const matter = newsletterShortMatter(signal.matter || "public responsibility");
  const rawTitle = cleanNewsletterCopy(signal.title || signal.ownedTitle || "");
  const title = rawTitle && rawTitle.length <= 72 ? rawTitle : "the story";
  const questions = [
    `${title} matters because it shows where authority, consequence, and public trust meet.`,
    `The public record should make clear what decision created the pressure and who is left living with the result.`,
    `The story is worth watching when it reveals the actor, the incentive, the people affected, and the remedy still on the table.`
  ];
  return cleanNewsletterParagraph(questions[index % questions.length].replace(/\bpublic leadership, authority, and voter accountability\b/gi, matter));
}

function newsletterStoryCommentary(signal = {}, index = 0) {
  const stance = readableStance(signal.perspective);
  const matter = newsletterShortMatter(signal.matter || "public responsibility");
  const title = cleanNewsletterCopy(signal.ownedTitle || signal.title || "this story");
  const source = cleanNewsletterCopy(signal.source || "reporting");
  const question = newsletterStoryQuestion(signal, index);
  const templates = [
    `${title} belongs in the weekly read because ${matter} became visible in a public decision. ${question} The Censored Expressions view is that ${stance}`,
    `${source} supplied the starting point, but the larger issue is ${matter}. ${question} The week needs judgment rooted in the record, not another copied headline.`,
    `${title} helps readers measure consequence. On ${matter}, the answer should be tied to what happened, who had authority, and whether the response can be checked later. ${stance}`,
    `${matter} often hides inside an ordinary headline. ${question} The better read follows the incentive, the cost, and the remedy.`,
    `${title} should be read as part of a larger pattern. Decisions are made, families or communities absorb the result, and leaders should be measured by outcomes.`
  ];
  return cleanNewsletterParagraph(templates[index % templates.length]);
}

function newsletterShortMatter(matter = "") {
  const text = cleanNewsletterCopy(matter).toLowerCase();
  if (/public leadership|authority|voter/.test(text)) return "public accountability";
  if (/foreign policy|foreign affairs|national strength/.test(text)) return "national strength";
  if (/competition|standards|sports/.test(text)) return "standards and competition";
  if (/emergency|cleanup|local/.test(text)) return "local response";
  if (/government spending|dependency/.test(text)) return "spending and dependency";
  if (/culture/.test(text)) return "culture and family judgment";
  if (/law|liberty|conscience/.test(text)) return "law and liberty";
  return cleanNewsletterCopy(matter || "public responsibility");
}

function newsletterOwnedTitle(input = {}, index = 0) {
  const title = cleanNewsletterCopy(input.title || "");
  const matter = cleanNewsletterCopy(input.matter || storyMatter(input));
  const text = `${title} ${matter} ${input.category || ""}`.toLowerCase();
  const variants = [];
  if (/tax|budget|debt|spending|gas tax|federal|state|program|subsid|aid|benefit/.test(text)) {
    variants.push("Follow The Money, Then Ask Who Pays", "Government Help Still Comes With Strings", "The Bill Always Lands Somewhere");
  }
  if (/court|judge|lawsuit|defamation|settlement|rights|law|constitution/.test(text)) {
    variants.push("When The Legal Fight Ends, Accountability Should Begin", "The Settlement Is Not The Whole Story", "Law Should Clarify, Not Just Quiet The Room");
  }
  if (/war|iran|israel|gaza|ukraine|russia|china|foreign|border|security|visa|world cup/.test(text)) {
    variants.push("Strength Needs Clear Rules", "National Interest Needs Plain Answers", "Global Headlines Still Need Accountability");
  }
  if (/family|child|children|school|parent|father|mother/.test(text)) {
    variants.push("Families Deserve The First Voice", "Protect The Home Before The Institution", "Children Should Not Be An Afterthought");
  }
  if (/culture|movie|music|celebrity|hollywood|streaming|composer|film|review|entertainment/.test(text)) {
    variants.push("Culture Teaches Before Politics Acts", "Entertainment Still Shapes The Home", "The Story Behind The Screen Matters");
  }
  if (/sports|coach|football|baseball|world cup|season|playoff|competition|michigan|detroit/.test(text)) {
    variants.push("Standards Still Show Up On The Scoreboard", "Competition Still Tells The Truth", "Preparation Beats Excuses");
  }
  if (/storm|weather|outage|cleanup|flood|heat|forecast|emergency/.test(text)) {
    variants.push("The Real Test Comes After The Storm", "Preparedness Matters Before The Cameras Arrive", "Local Response Should Be Measured");
  }
  if (/crime|police|shooting|violence|safety|murder/.test(text)) {
    variants.push("Public Safety Is The First Promise", "Order Is Compassion In Practice", "Families Need Safer Streets, Not Softer Words");
  }
  if (/gender|trans|pronoun|lgbt|marriage|private choices/.test(text)) {
    variants.push("Private Choices Do Not Require Public Obedience", "Freedom Does Not Mean Forced Agreement", "Tolerance Should Not Rewrite The Home");
  }
  if (!variants.length) {
    variants.push("The Headline Needs A Responsibility Test", "What The Week Revealed", "Do Not Stop At The Headline");
  }
  return variants[index % variants.length];
}

function newsletterSourceSignals(stories = [], limit = 7) {
  return distinctNewsletterStories(stories, limit).map((story, index) => {
    const angle = creatorStoryAngle(story);
    const stance = creatorStanceForStory(story);
    return {
      title: cleanNewsletterCopy(story.title),
      ownedTitle: newsletterOwnedTitle(story, index),
      source: cleanNewsletterCopy(story.source),
      url: story.url,
      category: story.category || "news",
      topic: cleanNewsletterCopy(creatorTopicForStory(story, index)),
      matter: cleanNewsletterCopy(storyMatter(story)),
      takeaway: cleanNewsletterCopy(angle.issue),
      question: cleanNewsletterCopy(angle.questions),
      perspective: cleanNewsletterCopy(`${stance.side} ${stance.reason}`),
      sourceUse: "Direction only. This source points to the topic; it is not the newsletter body."
    };
  });
}

function newsletterWeeklyRecap(signals = []) {
  const lead = signals[0];
  const second = signals[1];
  const third = signals[2];
  const matters = [...new Set(signals.map(signal => signal.matter).filter(Boolean))].slice(0, 4);
  const topicLine = matters.length
    ? `The week clustered around ${matters.join(", ")}.`
    : "The week produced scattered headlines, but the job is still to find the responsibility underneath them.";

  return [
    `${topicLine} A useful weekly signal should explain which decisions created consequences and which stories still need measurable answers.`,
    lead ? `The strongest signal was ${lead.matter}. ${lead.takeaway} The commentary should start where responsibility becomes visible.` : "The strongest signal this week was the need to separate noise from consequence.",
    second ? `A second thread pointed toward ${second.matter}. The test is whether the response respects free people, honest limits, and the families who live with the outcome.` : "",
    third ? `The third thread added pressure around ${third.matter}. That matters because next week's debate will likely be shaped by unresolved incentives, not yesterday's headline count.` : ""
  ].filter(Boolean);
}

function newsletterLeadHeadline(signals = []) {
  const text = signals.map(signal => `${signal.matter} ${signal.topic}`).join(" ").toLowerCase();
  if (/storm|cleanup|local|emergency|crime|safety/.test(text)) return "ACCOUNTABILITY STARTS CLOSE TO HOME";
  if (/war|foreign|iran|israel|china|ukraine|national strength/.test(text)) return "STRENGTH IS MORE THAN A SLOGAN";
  if (/culture|entertainment|family|school|children|private choices/.test(text)) return "CULTURE KEEPS MOVING THE LINE";
  if (/tax|budget|spending|debt|government/.test(text)) return "THE BILL ALWAYS FINDS THE FAMILY";
  if (/competition|sports|standards/.test(text)) return "STANDARDS STILL TELL THE TRUTH";
  return "WHAT THE WEEK REVEALED";
}

function newsletterTopNewsBriefs(signals = []) {
  const briefStarters = [
    "The weekly read:",
    "Why it matters:",
    "What to measure:"
  ];
  return signals.slice(0, Math.min(3, signals.length)).map((signal, index) => ({
    title: newsletterOwnedTitle(signal, index),
    originalTitle: signal.title,
    brief: cleanNewsletterParagraph(`${briefStarters[index % briefStarters.length]} ${newsletterStoryQuestion(signal, index)}`),
    source: signal.source,
    url: signal.url
  }));
}

function newsletterOpeningNote(signals = [], week = workWeekWindow()) {
  const lead = signals[0];
  const variants = lead ? [
    `This weekï¿½s issue starts with ${newsletterShortMatter(lead.matter)} because that is where the public consequence was easiest to see. The purpose is not to recap every headline; it is to separate passing noise from the stories that still deserve attention.`,
    `The week brought more headlines than clarity, so this issue slows down around ${newsletterShortMatter(lead.matter)} and asks what changed, who carried the cost, and what should be watched next.`,
    `${sentenceCase(newsletterShortMatter(lead.matter))} shaped the strongest signal this week. The newsletterï¿½s job is to give readers a clean read on the consequence without turning the issue into a pile of links.`
  ] : [
    "This issue looks back at the week by separating lasting consequence from passing noise, then looks ahead to the stories most likely to demand clearer answers.",
    "The week did not need more headline stacking. It needed a cleaner read on responsibility, consequence, and the next public decision worth watching.",
    "This issue is built for readers who want the week organized around consequence instead of volume."
  ];
  return cleanNewsletterParagraph(variants[creatorVariantIndex(lead || {}, `newsletter-opening-${week.start}`, variants.length)]);
}

function newsletterQuickLinks(signals = [], upcoming = []) {
  const signalLinks = signals.slice(0, Math.min(3, signals.length)).map((signal, index) => ({
    label: newsletterOwnedTitle(signal, index + 3),
    title: signal.title,
    originalTitle: signal.title,
    url: signal.url,
    source: signal.source
  }));
  const seen = new Set(signalLinks.map(item => item.url).filter(Boolean));
  const upcomingLinks = upcoming.filter(item => {
    if (!item.url || seen.has(item.url)) return false;
    seen.add(item.url);
    return true;
  }).slice(0, 2).map((item, index) => ({
    label: newsletterOwnedTitle(item, index + signalLinks.length + 6),
    title: item.title,
    originalTitle: item.title,
    url: item.url,
    source: item.source
  }));
  return [...signalLinks, ...upcomingLinks].slice(0, 5);
}

function newsletterCallToAction(signals = []) {
  const lead = signals[0];
  return lead
    ? `Reply with the story you think deserves the next deeper Censored Expressions breakdown, especially if it connects to ${lead.matter}.`
    : "Reply with the story you think deserves the next deeper Censored Expressions breakdown.";
}

function newsletterBranding() {
  return {
    name: "Censored Expressions",
    tagline: "We Say What You Can't",
    sealImage: "./assets/ce-seal-newsletter-transparent.png",
    stampImage: "./assets/censored-expressions-stamp.jpg",
    homeUrl: "./index.html"
  };
}

function newsletterMainNarrative(signals = [], week = workWeekWindow()) {
  const usable = signals.slice(0, 3);
  const [lead, second, third] = usable;
  const matters = [...new Set(signals.map(signal => newsletterShortMatter(signal.matter)).filter(Boolean))].slice(0, 4);
  const matterLine = matters.length === 1 ? matters[0] : matters.join(", ");
  const openingVariants = matters.length ? [
    `The weekï¿½s strongest pattern ran through ${matterLine}. That does not make every story the same; it means each one should be judged by the decision made, the consequence created, and the standard that can be checked later.`,
    `${sentenceCase(matterLine)} gave the week its shape. The important part is not the number of headlines, but whether any of them reveal who acted, who benefited, and who was left carrying the result.`,
    `The week kept returning to ${matterLine}. A useful weekly signal has to do more than name the topic; it has to explain why the topic still matters after the news cycle moves on.`
  ] : [
    "This past week was scattered, but the better read is to ask which stories exposed responsibility, pressure, and consequence."
  ];
  const opening = cleanNewsletterParagraph(openingVariants[creatorVariantIndex(lead || {}, `newsletter-main-${week.start}`, openingVariants.length)]);
  const leadLine = lead ? newsletterStoryCommentary(lead, 0) : "The lead signal this week was the need to separate noise from consequence.";
  const bridge = second ? newsletterStoryCommentary(second, 1) : "That same pattern is why the next week should be watched carefully.";
  const values = third
    ? newsletterStoryCommentary(third, 2)
    : "The Censored Expressions lens should stay steady without turning into a script: defend free speech, protect family authority, reject racism without surrendering agency, favor personal responsibility, and stay skeptical when government power sells itself as compassion.";
  const closeVariants = usable.length > 1 ? [
    "Together, those stories should be judged by response and consequence: clearer answers, visible action where it applies, honest limits on power, and measurable improvement.",
    "The point is not to make the week sound tidy. The point is to leave readers with a standard they can use when the next update arrives.",
    "The through-line is accountability: not louder language, not better branding, but a response that can be measured after the cameras leave."
  ] : [
    "When the week only produces one distinct story worth elevating, the honest move is to go deeper instead of pretending a duplicate headline is a new argument."
  ];
  const close = closeVariants[creatorVariantIndex(third || lead || {}, `newsletter-close-${week.end}`, closeVariants.length)];
  return [opening, leadLine, bridge, values, close].filter(Boolean);
}

function newsletterForecast(signals = [], upcoming = [], week = workWeekWindow()) {
  const watched = upcoming.slice(0, 3).map(item => item.title).filter(Boolean);
  const signalForecasts = signals.slice(0, Math.min(3, signals.length)).map((signal, index) => {
    const topic = newsletterShortMatter(signal.matter || signal.topic || "public accountability");
    const lines = [
      `Watch ${topic} for proof, not posture: timelines, responsible actors, and visible consequences.`,
      `The next question around ${topic} is whether the people with authority give measurable answers or simply wait for attention to move somewhere else.`,
      `${sentenceCase(topic)} should be followed by asking what changed on the ground and who can be held responsible for the result.`
    ];
    return lines[index % lines.length];
  });
  const calendarForecast = watched.length
    ? `The week ahead has visible markers: ${watched.join("; ")}. Treat those as leads for deeper reporting and commentary, not as filler for the issue.`
    : "This week should be judged by which stories create real consequences rather than which headlines trend the loudest.";
  return [calendarForecast, ...signalForecasts].slice(0, 5);
}

function newsletterValuesCommentary(signals = []) {
  const values = (creatorDeskProfile.values || []).slice(0, 5);
  const strongest = signals[0];
  const strongestMatter = newsletterShortMatter(strongest?.matter || "");
  return [
    `The Censored Expressions lens stays consistent: ${values.join(" ")} The point is not to force every story into a slogan; it is to judge whether the public is being asked to trade responsibility for comfort, liberty for permission, or family authority for institutional control.`,
    strongest ? `Through that lens, ${strongestMatter} deserves judgment tied to the facts in front of us: ${readableStance(strongest.perspective)} The article is only the starting point; the public argument is about responsibility, incentives, and consequences.` : "Through that lens, every story should be tested against liberty, responsibility, family authority, honest local action, and limited government.",
    "The standard for next week is concrete: what failed, what worked, who had authority, who paid the price, and what would actually improve life for families and communities."
  ];
}

function buildNewsletterSections(stories = [], week = workWeekWindow()) {
  const writingGuidance = contentLaneWritingIntelligenceGuidance("newsletter");
  const signals = newsletterSourceSignals(stories);
  const upcoming = upcomingSignals(stories);
  const leadHeadline = newsletterLeadHeadline(signals);
  const topBriefs = newsletterTopNewsBriefs(signals);
  const openingNote = newsletterOpeningNote(signals, week);
  const mainNarrative = newsletterMainNarrative(signals, week);
  const forecast = newsletterForecast(signals, upcoming, week);
  const quickLinks = newsletterQuickLinks(signals, upcoming);
  const callToAction = newsletterCallToAction(signals);
  return {
    signals,
    upcoming,
    leadHeadline,
    writingGuidance,
    topBriefs,
    openingNote,
    mainNarrative,
    forecast,
    quickLinks,
    callToAction,
    sections: [
      {
        title: leadHeadline,
        intro: "A smoother weekly read on the prior news cycle, written as commentary instead of a stack of article notes.",
        paragraphs: mainNarrative,
        signals: signals.slice(0, 3)
      },
      {
        title: "What Comes Next",
        intro: "A forward look at what is upcoming this week.",
        paragraphs: forecast,
        signals: signals.slice(0, 4)
      },
      {
        title: "Values Lens",
        intro: "The perspective that turns the source material into original commentary.",
        paragraphs: newsletterValuesCommentary(signals),
        signals: signals.slice(0, 3)
      }
    ]
  };
}

function newsletterStoryLooksStale(story = {}, week = workWeekWindow()) {
  const currentYear = Number(week.end?.getFullYear?.() || new Date().getFullYear());
  const text = `${story.url || ""} ${story.publishedAt || ""} ${story.date || ""}`;
  const years = [...String(text).matchAll(/\b(20\d{2})\b/g)].map(match => Number(match[1]));
  return years.some(year => year && year < currentYear - 1);
}

function cleanNewsletterParagraph(paragraph = "") {
  let text = cleanEncodingArtifacts(cleanNewsletterCopy(paragraph));
  text = text
    .replace(/The practical question is/gi, "The useful question is")
    .replace(/My read is that this is where commentary has to slow down\./gi, "The commentary has to connect the report to responsibility.")
    .replace(/A report can tell us what happened; a serious newsletter has to ask what should happen next and who should be judged by the result\./gi, "The newsletter has to ask what should happen next and who should be judged by the result.")
    .replace(/another round of approved language/gi, "another round of polished language")
    .replace(/\bapproved narrative\b/gi, "official account")
    .replace(/\bheaders\b/gi, "public records")
    .replace(/\.\.\.+/g, ".")
    .replace(/\s+/g, " ")
    .trim();
  return looksLikeScriptJunk(text) ? "" : text;
}

function uniqueNewsletterItems(items = [], limit = 10) {
  const seen = new Set();
  const seenUrl = new Set();
  const seenDisplay = new Set();
  return items.filter(item => {
    const display = cleanNewsletterCopy(item.label || item.title || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
    const url = String(item.url || "").trim().toLowerCase();
    const key = `${url}::${display}`;
    if ((url && seenUrl.has(url)) || seen.has(key) || (display && seenDisplay.has(display))) return false;
    seen.add(key);
    if (url) seenUrl.add(url);
    if (display) seenDisplay.add(display);
    return true;
  }).slice(0, limit);
}

function dedupeNewsletterIssueLists(newsletter = {}) {
  const seenUrl = new Set();
  const seenDisplay = new Set();
  const accept = item => {
    const display = cleanNewsletterCopy(item.label || item.title || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
    const url = String(item.url || "").trim().toLowerCase();
    if ((url && seenUrl.has(url)) || (display && seenDisplay.has(display))) return false;
    if (url) seenUrl.add(url);
    if (display) seenDisplay.add(display);
    return true;
  };
  const cleanList = (list = [], limit = 10) => uniqueNewsletterItems(list, limit).filter(accept);
  return {
    ...newsletter,
    topNews: cleanList(newsletter.topNews || [], 3),
    quickLinks: cleanList(newsletter.quickLinks || [], 5),
    upcoming: cleanList(newsletter.upcoming || [], 8),
    sourceDirections: []
  };
}

function newsletterDuplicateReferenceCount(newsletter = {}) {
  const references = [
    ...(newsletter.topNews || []),
    ...(newsletter.quickLinks || []),
    ...(newsletter.upcoming || []),
    ...(newsletter.sourceDirections || [])
  ];
  const seen = new Set();
  let duplicates = 0;
  references.forEach(item => {
    const display = cleanNewsletterCopy(item.label || item.title || "").toLowerCase().replace(/[^a-z0-9]+/g, " ").trim();
    const url = String(item.url || "").trim().toLowerCase();
    const key = url || display;
    if (!key) return;
    if (seen.has(key)) duplicates += 1;
    seen.add(key);
  });
  return duplicates;
}

function newsletterCeLabel(item = {}) {
  const raw = cleanEncodingArtifacts(cleanNewsletterCopy(item.title || item.label || ""));
  const title = raw
    .replace(/\s*[-|:]\s*(CNN|Fox News|NBC News|ABC News|CBS News|NPR|AP News|Reuters|The Guardian|ESPN|MarketWatch).*$/i, "")
    .replace(/\bWATCH:\s*/gi, "")
    .replace(/\bLIVE UPDATES?:\s*/gi, "")
    .replace(/\s+/g, " ")
    .trim();
  if (!title) return "CE Media brief";
  const words = title.split(/\s+/).slice(0, 12).join(" ");
  return words.length < title.length ? words : words;
}

function newsletterArchiveStoryPool(newsletter = {}) {
  return [
    ...(newsletter.topNews || []),
    ...(newsletter.quickLinks || []),
    ...(newsletter.upcoming || []),
    ...(newsletter.sourceDirections || []),
    ...((newsletter.sections || []).flatMap(section => [
      ...(section.signals || []),
      ...(section.items || [])
    ]))
  ].map(item => ({
    ...item,
    title: cleanEncodingArtifacts(cleanNewsletterCopy(item.title || item.label || item.topic || item.matter || "")),
    label: newsletterCeLabel(item),
    source: cleanEncodingArtifacts(cleanNewsletterCopy(item.source || "")),
    brief: cleanNewsletterParagraph(item.brief || item.summary || item.takeaway || item.question || "")
  })).filter(item => item.title || item.label || item.url);
}

function rebuildNewsletterIssueFromStoredStories(newsletter = {}) {
  const cleaned = cleanNewsletterDeep(newsletter);
  const pool = uniqueNewsletterItems(newsletterArchiveStoryPool(cleaned), 12);
  const topNews = uniqueNewsletterItems(pool.slice(0, 6).map((item, index) => ({
    ...item,
    title: newsletterCeLabel(item),
    brief: cleanNewsletterParagraph(item.brief) || [
      "This story mattered because it put responsibility, consequence, and public trust back in front of readers.",
      "The useful read is not just what happened, but who had authority and what measurable response should follow.",
      "The week should be judged by facts, visible action, and whether families and communities receive honest answers."
    ][index % 3]
  })), 3);
  const quickLinks = uniqueNewsletterItems(pool.map(item => ({
    label: newsletterCeLabel(item),
    title: newsletterCeLabel(item),
    url: item.url || "",
    source: item.source || "CE Media reference"
  })), 5);
  const upcoming = uniqueNewsletterItems((cleaned.upcoming || pool).map(item => ({
    title: newsletterCeLabel(item),
    url: item.url || "",
    source: cleanNewsletterCopy(item.source || "CE Media watch")
  })), 8);
  const topics = topNews.map(item => item.title).filter(Boolean);
  const weekLabel = cleaned.weekLabel || cleaned.publicationDateLabel || "this week";
  const forecastLabel = cleaned.forecastWeekLabel || "the week ahead";
  const openingNote = `This issue looks back at ${weekLabel} by separating the strongest story threads from recycled noise. The purpose is to give readers a cleaner weekly read: what happened, why it mattered, and what should be watched next.`;
  const featureVariants = [
    topics.length
      ? `The clearest signals this week were ${topics.join("; ")}. The common test is whether leaders, institutions, and communities can be judged by facts and consequences instead of presentation.`
      : "The clearest signal this week was the need for facts tied to responsibility. When the public record is thin, the honest newsletter does not inflate weak material; it explains what is known and what still needs proof.",
    topics.length
      ? `Those stories matter because they leave readers with practical questions: what changed, who had authority, who paid the cost, and what standard should be used when the next update arrives?`
      : "The issue is not volume. The issue is whether the available record gives families and communities enough clarity to act.",
    "The values lens remains steady, but the language should not. Each issue should apply free speech, family strength, personal responsibility, limited government, and local accountability to the week in front of us rather than repeating the same paragraph across different issues."
  ];
  const featureParagraphs = featureVariants.map(cleanNewsletterParagraph).filter(Boolean);
  const sections = [
    {
      title: "What This Week Showed",
      intro: "A cleaner read on the prior news cycle.",
      paragraphs: featureParagraphs,
      signals: topNews.map(item => ({ topic: item.title, source: item.source, takeaway: item.brief }))
    },
    {
      title: "What Comes Next",
      intro: `A forward look at ${forecastLabel}.`,
      paragraphs: newsletterForecast(topNews, upcoming, cleaned).map(cleanNewsletterParagraph).filter(Boolean),
      signals: upcoming.slice(0, 4)
    },
    {
      title: "Values Lens",
      intro: "The perspective that turns the source material into original commentary.",
      paragraphs: newsletterValuesCommentary(topNews.map(item => ({
        matter: item.title,
        perspective: item.brief
      }))).map(cleanNewsletterParagraph).filter(Boolean),
      signals: topNews
    }
  ];
  const rebuilt = polishNewsletterIssue({
    ...cleaned,
    title: cleanNewsletterCopy(cleaned.title || "Censored Expressions Weekly Signal"),
    openingNote,
    editorNote: featureParagraphs[0] || openingNote,
    topNews,
    quickLinks,
    upcoming,
    sourceDirections: [],
    sections,
    feature: {
      ...(cleaned.feature || {}),
      kicker: "Weekly Signal",
      headline: cleanNewsletterCopy(cleaned.feature?.headline || "The Week In Responsibility"),
      paragraphs: featureParagraphs
    },
    callToAction: cleanNewsletterParagraph(cleaned.callToAction || "Read the stories, follow the facts, and keep asking who is responsible for the result.")
  });
  return enforceContentEditor({
    ...rebuilt,
    html: newsletterHtml(rebuilt),
    text: newsletterText(rebuilt),
    cleanedAt: new Date().toISOString(),
    cleanupReason: "owner-feedback-brain-archive-rewrite"
  }, "newsletter");
}

function cleanArchiveOutputDeep(value) {
  if (typeof value === "string") return cleanEncodingArtifacts(value);
  if (Array.isArray(value)) return value.map(cleanArchiveOutputDeep);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, cleanArchiveOutputDeep(item)]));
  }
  return value;
}

function technicalEditorCleanString(value = "") {
  let text = cleanEncodingArtifacts(value);
  if (/^https?:\/\//i.test(text)) return text;
  const replacements = [
    [/\bteh\b/gi, "the"],
    [/\brecieve\b/gi, "receive"],
    [/\brecieved\b/gi, "received"],
    [/\bseperate\b/gi, "separate"],
    [/\bgoverment\b/gi, "government"],
    [/\bresponsiblity\b/gi, "responsibility"],
    [/\boccured\b/gi, "occurred"],
    [/\boccuring\b/gi, "occurring"],
    [/\buntill\b/gi, "until"],
    [/\badditonal\b/gi, "additional"],
    [/\bsiting\b/gi, "citing"],
    [/\bpublically\b/gi, "publicly"],
    [/\bgrammer\b/gi, "grammar"],
    [/\bnews letter\b/gi, "newsletter"]
  ];
  replacements.forEach(([pattern, replacement]) => {
    text = text.replace(pattern, replacement);
  });
  return text
    .replace(/\s+([,.;:!?])/g, "$1")
    .replace(/([.!?]){2,}/g, "$1")
    .replace(/,\s*,+/g, ",")
    .replace(/\s+/g, " ")
    .trim();
}

function technicalEditorDeep(value) {
  if (typeof value === "string") return technicalEditorCleanString(value);
  if (Array.isArray(value)) return value.map(technicalEditorDeep);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, technicalEditorDeep(item)]));
  }
  return value;
}

function contentLaneInternalLanguagePattern() {
  return /\b(Source Direction|backend|subsystem|quality gate|dossier|source signals?|full-read signals?|confidence level|confidence score|Brain|Framework|AI Framework|prompt|internal process|editor enforcement|contentLaneQuality|quality-gate|ranked by|source clustering|cluster count)\b/i;
}

function contentLaneStockFrameCount(value = "", lane = "general") {
  const text = String(value || "");
  const sharedPatterns = [
    /The useful question is/gi,
    /The accountability question is practical/gi,
    /The consequence test is simple/gi,
    /what happened, who had authority, who was affected/gi,
    /who made the decision, who carries the consequence/gi,
    /what standard can be checked later/gi,
    /facts tied to responsibility/gi,
    /not a headline followed by a detachable opinion/gi,
    /the public deserves facts tied to responsibility/gi
  ];
  const creatorPatterns = [
    /The column works only when each story answers for its own facts/gi,
    /The shared lesson is not a slogan; it is a standard/gi,
    /The pressure point in .* is not abstract/gi,
    /For Censored Expressions, .* should be judged by the actor/gi,
    /Start with the concrete event/gi,
    /The opinion follows from that/gi,
    /That pushes the column toward/gi,
    /The position should be clear/gi
  ];
  const newsletterPatterns = [
    /The week brought more headlines than clarity/gi,
    /The week kept returning to/gi,
    /The week.?s strongest pattern ran through/gi,
    /The point is not to make the week sound tidy/gi,
    /The through-line is accountability/gi,
    /The newsletter has to ask what should happen next/gi,
    /Treat those as leads for deeper reporting and commentary/gi
  ];
  const patterns = [
    ...sharedPatterns,
    ...(lane === "creator-desk" ? creatorPatterns : []),
    ...(lane === "newsletter" ? newsletterPatterns : [])
  ];
  return patterns.reduce((total, pattern) => total + ((text.match(pattern) || []).length), 0);
}

function splitOverlongPublicSentence(value = "", maxLength = 280) {
  const text = String(value || "").trim();
  if (text.length <= maxLength) return text;
  const breakPoints = [
    /,\s+because\s+/i,
    /,\s+but\s+/i,
    /,\s+and\s+/i,
    /;\s+/,
    /\s+while\s+/i,
    /\s+which\s+/i,
    /\s+that\s+/i
  ];
  let sentences = [text];
  breakPoints.forEach(pattern => {
    sentences = sentences.flatMap(sentence => {
      if (sentence.length <= maxLength) return [sentence];
      const parts = sentence.split(pattern).map(part => part.trim()).filter(Boolean);
      if (parts.length < 2) return [sentence];
      return parts.map(part => /[.!?]$/.test(part) ? part : `${part}.`);
    });
  });
  return sentences.join(" ").replace(/\s+/g, " ").trim();
}

function removeContentLaneInternalLanguage(value = "", lane = "general") {
  let text = String(value || "");
  text = text
    .replace(/\b(Source Direction|source directions?)\b[:\s-]*/gi, "")
    .replace(/\bThe current confidence level is[^.?!]*[.?!]\s*/gi, "")
    .replace(/\bThe dossier includes[^.?!]*[.?!]\s*/gi, "")
    .replace(/\bThe document trail includes\b/gi, "The public record includes")
    .replace(/\bsource signals?\b/gi, "reports")
    .replace(/\bfull-read signals?\b/gi, "reviewed reports")
    .replace(/\bthe Brain\b/g, lane === "newsletter" ? "the newsletter" : "the column")
    .replace(/\bThe Brain\b/g, lane === "newsletter" ? "The newsletter" : "The column")
    .replace(/\bAI Framework\b|\bFramework\b/gi, lane === "newsletter" ? "the editorial process" : "the column")
    .replace(/\bquality gate\b|\bquality-gate\b/gi, "editorial standard")
    .replace(/\bdossier\b/gi, "public record")
    .replace(/\bcluster count\b|\branked by\b|\bsource clustering\b/gi, "reporting context")
    .replace(/\bcontentLaneQuality\b|\beditor enforcement\b/gi, "editorial review");
  if (lane === "creator-desk") {
    text = text
      .replace(/\bThe column works only when each story answers for its own facts\./gi, "The column should let each story carry its own argument.")
      .replace(/\bThe shared lesson is not a slogan; it is a standard\./gi, "The shared lesson should be tested by results.")
      .replace(/\bThe position should be clear:/gi, "My position is direct:")
      .replace(/\bThat pushes the column toward\b/gi, "That points toward");
  }
  if (lane === "newsletter") {
    text = text
      .replace(/\bThe week brought more headlines than clarity\b/gi, "This past week produced more noise than clarity")
      .replace(/\bThe point is not to make the week sound tidy\./gi, "The point is to keep the week honest.")
      .replace(/\bThe through-line is accountability:/gi, "The useful standard is accountability:")
      .replace(/\bTreat those as leads for deeper reporting and commentary\b/gi, "Treat those as starting points for next week's attention");
  }
  return splitOverlongPublicSentence(text.replace(/\s+/g, " ").trim());
}

function polishContentLaneDraftForEditor(record = {}, lane = "general") {
  if (lane === "creator-desk") {
    const polished = {
      ...record,
      title: removeContentLaneInternalLanguage(cleanCreatorEditorialParagraph(record.title || ""), lane) || record.title,
      editorNote: removeContentLaneInternalLanguage(cleanCreatorEditorialParagraph(record.editorNote || ""), lane),
      body: (record.body || []).map(section => ({
        ...section,
        heading: removeContentLaneInternalLanguage(cleanCreatorEditorialParagraph(section.heading || ""), lane),
        paragraphs: (section.paragraphs || [])
          .map(paragraph => removeContentLaneInternalLanguage(cleanCreatorEditorialParagraph(paragraph), lane))
          .filter(Boolean)
      })),
      items: (record.items || []).map(item => ({
        ...item,
        summary: removeContentLaneInternalLanguage(cleanCreatorEditorialParagraph(item.summary || ""), lane),
        commentary: removeContentLaneInternalLanguage(cleanCreatorEditorialParagraph(item.commentary || ""), lane),
        publicConsequence: removeContentLaneInternalLanguage(cleanCreatorEditorialParagraph(item.publicConsequence || ""), lane),
        improvementFrame: removeContentLaneInternalLanguage(cleanCreatorEditorialParagraph(item.improvementFrame || ""), lane)
      }))
    };
    return polished;
  }
  if (lane === "newsletter") {
    const polished = {
      ...record,
      title: removeContentLaneInternalLanguage(cleanNewsletterParagraph(record.title || ""), lane) || record.title,
      editorNote: removeContentLaneInternalLanguage(cleanNewsletterParagraph(record.editorNote || ""), lane),
      openingNote: removeContentLaneInternalLanguage(cleanNewsletterParagraph(record.openingNote || ""), lane),
      callToAction: removeContentLaneInternalLanguage(cleanNewsletterParagraph(record.callToAction || ""), lane),
      sourceDirections: [],
      sections: (record.sections || []).map(section => ({
        ...section,
        intro: removeContentLaneInternalLanguage(cleanNewsletterParagraph(section.intro || ""), lane),
        paragraphs: (section.paragraphs || [])
          .map(paragraph => removeContentLaneInternalLanguage(cleanNewsletterParagraph(paragraph), lane))
          .filter(Boolean)
      })),
      feature: record.feature ? {
        ...record.feature,
        headline: removeContentLaneInternalLanguage(cleanNewsletterParagraph(record.feature.headline || ""), lane),
        paragraphs: (record.feature.paragraphs || [])
          .map(paragraph => removeContentLaneInternalLanguage(cleanNewsletterParagraph(paragraph), lane))
          .filter(Boolean)
      } : record.feature,
      topNews: (record.topNews || []).map(item => ({
        ...item,
        brief: removeContentLaneInternalLanguage(cleanNewsletterParagraph(item.brief || ""), lane)
      }))
    };
    return polished;
  }
  return record;
}

function collectPublicStrings(value, strings = []) {
  if (typeof value === "string") {
    if (!/^https?:\/\//i.test(value)) strings.push(value);
    return strings;
  }
  if (Array.isArray(value)) {
    value.forEach(item => collectPublicStrings(item, strings));
    return strings;
  }
  if (value && typeof value === "object") {
    Object.entries(value).forEach(([key, item]) => {
      if (/url|href|html|text|token|id|at|generated|checked|contentLaneQuality/i.test(key)) return;
      collectPublicStrings(item, strings);
    });
  }
  return strings;
}

function technicalEditorPublicStrings(record = {}, lane = "general") {
  const add = (value, output = [], pathLabel = "content") => {
    if (typeof value === "string" && value.trim() && !/^https?:\/\//i.test(value.trim())) {
      output.push({ path: pathLabel, text: value });
    }
    if (Array.isArray(value)) value.forEach((item, index) => add(item, output, `${pathLabel}[${index}]`));
    return output;
  };
  const strings = [];
  add(record.title, strings, "title");
  add(record.summary, strings, "summary");
  if (lane === "newsletter") {
    add(record.openingNote, strings, "openingNote");
    add(record.editorNote, strings, "editorNote");
    add(record.callToAction, strings, "callToAction");
    add(record.feature?.headline, strings, "feature.headline");
    add(record.feature?.paragraphs, strings, "feature.paragraphs");
    (record.sections || []).forEach(section => {
      add(section.title, strings, `sections.${section.title || "section"}.title`);
      add(section.intro, strings, `sections.${section.title || "section"}.intro`);
      add(section.paragraphs, strings, `sections.${section.title || "section"}.paragraphs`);
    });
    (record.topNews || []).forEach(item => {
      add(item.title, strings, `topNews.${item.title || "item"}.title`);
      add(item.brief, strings, `topNews.${item.title || "item"}.brief`);
    });
    (record.quickLinks || []).forEach(item => add(item.label || item.title, strings, `quickLinks.${item.label || item.title || "item"}`));
    (record.upcoming || []).forEach(item => add(item.title, strings, `upcoming.${item.title || "item"}`));
    return strings;
  }
  if (lane === "creator-desk") {
    (record.body || []).forEach(section => {
      add(section.heading, strings, `body.${section.heading || "section"}.heading`);
      add(section.paragraphs, strings, `body.${section.heading || "section"}.paragraphs`);
    });
    (record.items || []).forEach(item => {
      add(item.title, strings, `items.${item.title || "item"}.title`);
      add(item.summary, strings, `items.${item.title || "item"}.summary`);
      add(item.commentary, strings, `items.${item.title || "item"}.commentary`);
      add(item.publicConsequence, strings, `items.${item.title || "item"}.publicConsequence`);
      add(item.improvementFrame, strings, `items.${item.title || "item"}.improvementFrame`);
    });
    return strings;
  }
  if (lane === "news-lab") {
    add(record.originalHeadline, strings, "originalHeadline");
    add(record.body, strings, "body");
    return strings;
  }
  return collectPublicStrings(record, strings).map((text, index) => ({ path: `content[${index}]`, text }));
}

function technicalEditorIssues(record = {}, lane = "general") {
  const publicStrings = technicalEditorPublicStrings(record, lane);
  const text = publicStrings.map(entry => typeof entry === "string" ? entry : entry.text).join(" ");
  const issues = [];
  if (!text.trim()) return ["empty-public-text"];
  if (/[ \t]{2,}/.test(text)) issues.push("extra-spacing");
  if (/\s+[,.!?;:]/.test(text)) issues.push("punctuation-spacing");
  if (/\.{3}|ÃƒÆ’|ÃƒÂ¢Ã¢â€šÂ¬|ÃƒÂ¯Ã‚Â¿Ã‚Â½|&#x27;/.test(text) || text.includes(String.fromCharCode(226, 8364))) {
    issues.push("encoding-or-ellipsis-artifact");
  }
  if (/\b(teh|recieve|recieved|seperate|goverment|responsiblity|occuring|additonal|siting|grammer)\b/i.test(text)) {
    issues.push("common-spelling-error");
  }
  const sentences = text
    .split(/(?<=[.!?])\s+/)
    .map(sentence => sentence.trim())
    .filter(Boolean);
  if (sentences.some(sentence => sentence.length > 360)) issues.push("overlong-sentence");
  const repeated = sentences
    .map(sentence => sentence.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim())
    .filter(sentence => sentence.length > 60)
    .filter((sentence, index, all) => all.indexOf(sentence) === index && all.filter(item => item === sentence).length >= 3);
  if (repeated.length) issues.push("repeated-sentence");
  if (lane === "newsletter" && (text.match(/\bpublic leadership, authority, and voter accountability\b/gi) || []).length > 3) {
    issues.push("newsletter-repetitive-matter-label");
  }
  if (lane === "creator-desk" && /\bThe story is this\b|source-specific detail/i.test(text)) {
    issues.push("creator-desk-source-note-leak");
  }
  if (lane === "creator-desk" && contentLaneStockFrameCount(text, lane) >= 2) {
    issues.push("creator-repeated-editorial-frame");
  }
  if (lane === "newsletter" && contentLaneStockFrameCount(text, lane) >= 2) {
    issues.push("newsletter-repeated-editorial-frame");
  }
  if (lane === "news-lab" && /\bMy read\b|\bMy view\b|\bReaders should\b|\bvalues lens\b/i.test(text)) {
    issues.push("news-lab-editorial-tone-leak");
  }
  return [...new Set(issues)];
}

function technicalEditorSummary(lane = "general") {
  const laneNames = {
    "creator-desk": "Creator Desk editorial/blog",
    newsletter: "weekly newsletter",
    "news-lab": "News Lab article"
  };
  return `Copy editor reviewed ${laneNames[lane] || lane} for spelling, sentence structure, punctuation, encoding artifacts, repetition, public-facing clarity, and lane-specific tone before save.`;
}

function editorLearningRuleForIssue(code = "", lane = "general") {
  const rules = {
    "empty-public-text": "Never save empty public writing; rebuild from selected story/source material before publication.",
    "extra-spacing": "Collapse repeated spaces during draft cleanup before the editor review.",
    "punctuation-spacing": "Remove spaces before punctuation and normalize punctuation before save.",
    "encoding-or-ellipsis-artifact": "Reject mojibake, ellipses, and clipped source fragments; regenerate from clean facts/titles.",
    "common-spelling-error": "Apply spelling correction before draft acceptance and add recurring misspellings to the editor dictionary.",
    "overlong-sentence": "Split long sentences into shorter public-facing sentences with one clear point each.",
    "repeated-sentence": "Rewrite repeated sentences instead of duplicating section copy across the same public item.",
    "newsletter-repetitive-matter-label": "Use short public labels and vary newsletter matter phrasing.",
    "creator-desk-source-note-leak": "Remove source-note/internal prompt language from Creator Desk public copy.",
    "creator-internal-language": "Creator Desk must never expose backend, Brain, Framework, source-direction, dossier, quality-gate, or confidence-scoring language to readers.",
    "newsletter-public-direction-language": "Newsletter public copy must not expose source-direction, dossier, Brain, Framework, confidence, or internal editorial-process language.",
    "newsletter-duplicate-story-reference": "Newsletter must dedupe story references across Top News, Quick Links, What To Watch, source directions, and section signals before rendering public HTML/text.",
    "creator-repeated-editorial-frame": "Creator Desk must vary openings, transitions, stance sentences, and closings instead of reusing the same editorial frame across dates.",
    "newsletter-repeated-editorial-frame": "Newsletter must vary week-to-week openings, transitions, matter labels, and closing language instead of using a reusable template voice.",
    "news-lab-editorial-tone-leak": "Keep News Lab neutral and fact-based; reserve opinion language for Creator Desk and Newsletter commentary.",
    "news-lab-process-language": "News Lab public articles must report the topic itself, not explain CE Media's reporting method, source clustering, or quality process.",
    "summary-repeats-body": "Summaries and article bodies must serve different jobs; rewrite the draft when the summary repeats body text.",
    "body-too-short": "Expand News Lab drafts with topic-specific facts, background, stakes, and next concrete development before publication.",
    "body-needs-intro-body-ending": "News Lab drafts must include a clear introduction, factual body, and ending rather than thin fragments.",
    "generic-weak-headline": "News Lab headlines must identify the actual event, person, organization, or decision; reject vague fallback titles that only say something brings questions or draws attention.",
    "missing-reporting-context": "News Lab articles should contain natural sourcing or official context without exposing internal process language.",
    "insufficient-full-article-facts": "The News Lab subsystem must keep searching/reading source articles when a draft lacks enough factual material.",
    "semantic-title-source-mismatch": "News Lab headlines must point to the same event and category as the source evidence; reject drafts where the title and source record describe different topics.",
    "headline-source-no-overlap": "News Lab headlines must share concrete event evidence with the source record; reject drafts where a CE headline appears attached to an unrelated source headline.",
    "mixed-source-topic": "News Lab sources must describe the same exact event/topic before the Brain combines them into one CE Media article.",
    "weak-topic-integrity": "When source overlap is weak, keep sources separate or request more same-event reporting before drafting.",
    "article-body-topic-drift": "Every paragraph in a News Lab article must stay anchored to the article's specific headline and source facts.",
    "paragraph-topic-contamination": "The copy editor must reject individual paragraphs that introduce unrelated actors, events, photo credits, source-page roundups, or separate news briefs into a CE Media article.",
    "image-missing-or-placeholder": "News Lab image selection must avoid placeholders and use a valid Pexels or controlled image before publication.",
    "image-missing-credit": "News Lab image selection must include visible photographer/source credit when using Pexels images.",
    "image-low-relevance": "News Lab image selection must cross-check image query, alt text, matched terms, category, and story terms before accepting a photo.",
    "image-topic-mismatch": "News Lab image selection must reject photos that do not match the article's topic, category, or concrete story terms."
  };
  return `${lane}: ${rules[code] || "Correct the issue before save and store the pattern as an editor learning signal."}`;
}

function editorFinding(code, lane, pathLabel, snippet, fix, severity = "medium") {
  return {
    code,
    lane,
    severity,
    path: pathLabel || "content",
    snippet: cleanArticleText(snippet || "", 220) || String(snippet || "").slice(0, 220),
    correction: fix,
    subsystemLesson: editorLearningRuleForIssue(code, lane)
  };
}

function technicalEditorFindings(record = {}, lane = "general") {
  const publicEntries = technicalEditorPublicStrings(record, lane);
  const text = publicEntries.map(entry => entry.text).join(" ");
  const findings = [];
  if (!text.trim()) return [editorFinding("empty-public-text", lane, "content", "", "Reject empty drafts and rebuild from source stories.", "high")];
  publicEntries.forEach(entry => {
    if (/[ \t]{2,}/.test(entry.text)) findings.push(editorFinding("extra-spacing", lane, entry.path, entry.text, "Collapse repeated spaces before save.", "low"));
    if (/\s+[,.!?;:]/.test(entry.text)) findings.push(editorFinding("punctuation-spacing", lane, entry.path, entry.text, "Remove spaces before punctuation.", "low"));
    if (/\.{3}|ÃƒÆ’Ã†â€™|ÃƒÆ’Ã‚Â¢ÃƒÂ¢Ã¢â‚¬Å¡Ã‚Â¬|ÃƒÆ’Ã‚Â¯Ãƒâ€šÃ‚Â¿Ãƒâ€šÃ‚Â½|&#x27;/.test(entry.text) || entry.text.includes(String.fromCharCode(226, 8364))) {
      findings.push(editorFinding("encoding-or-ellipsis-artifact", lane, entry.path, entry.text, "Normalize encoding artifacts and remove ellipses/clipped source fragments.", "high"));
    }
    const spelling = entry.text.match(/\b(teh|recieve|recieved|seperate|goverment|responsiblity|occuring|additonal|siting|grammer)\b/i);
    if (spelling) findings.push(editorFinding("common-spelling-error", lane, entry.path, entry.text, `Correct spelling error: ${spelling[0]}.`, "medium"));
  });
  const sentences = publicEntries.flatMap(entry => String(entry.text || "")
    .split(/(?<=[.!?])\s+/)
    .map(sentence => ({ path: entry.path, text: sentence.trim() }))
    .filter(item => item.text));
  sentences
    .filter(item => item.text.length > 360)
    .forEach(item => findings.push(editorFinding("overlong-sentence", lane, item.path, item.text, "Split overlong sentence into shorter, clearer sentences.", "medium")));
  const normalizedSentences = sentences
    .map(item => ({ ...item, key: item.text.toLowerCase().replace(/[^a-z0-9]+/g, " ").trim() }))
    .filter(item => item.key.length > 60);
  normalizedSentences
    .filter((item, index, all) => all.findIndex(match => match.key === item.key) === index && all.filter(match => match.key === item.key).length >= 3)
    .forEach(item => findings.push(editorFinding("repeated-sentence", lane, item.path, item.text, "Rewrite repeated sentence or remove duplicate section copy.", "medium")));
  if (lane === "newsletter" && (text.match(/\bpublic leadership, authority, and voter accountability\b/gi) || []).length > 3) {
    findings.push(editorFinding("newsletter-repetitive-matter-label", lane, "newsletter", text, "Use shorter public labels and vary matter wording.", "medium"));
  }
  if (lane === "newsletter" && newsletterDuplicateReferenceCount(record) > 0) {
    findings.push(editorFinding("newsletter-duplicate-story-reference", lane, "newsletter", text, "Remove duplicate newsletter story references across Top News, Quick Links, What To Watch, and source direction lists.", "medium"));
  }
  if (lane === "creator-desk" && /\bThe story is this\b|source-specific detail/i.test(text)) {
    findings.push(editorFinding("creator-desk-source-note-leak", lane, "creator-desk", text, "Remove source-note wording from public editorial copy.", "high"));
  }
  if (lane === "creator-desk" && contentLaneInternalLanguagePattern().test(text)) {
    findings.push(editorFinding("creator-internal-language", lane, "creator-desk", text, "Remove behind-the-scenes Brain, Framework, dossier, confidence, and process language from public editorial copy.", "high"));
  }
  if (lane === "creator-desk" && contentLaneStockFrameCount(text, lane) >= 2) {
    findings.push(editorFinding("creator-repeated-editorial-frame", lane, "creator-desk", text, "Rewrite repeated editorial frame language with story-specific transitions and conclusions.", "medium"));
  }
  if (lane === "newsletter" && contentLaneInternalLanguagePattern().test(text)) {
    findings.push(editorFinding("newsletter-public-direction-language", lane, "newsletter", text, "Remove source-direction, Brain, Framework, dossier, confidence, and process language from public newsletter copy.", "high"));
  }
  if (lane === "newsletter" && contentLaneStockFrameCount(text, lane) >= 2) {
    findings.push(editorFinding("newsletter-repeated-editorial-frame", lane, "newsletter", text, "Vary newsletter openings, transitions, matter labels, and closing language before publication.", "medium"));
  }
  if (lane === "news-lab" && /\bMy read\b|\bMy view\b|\bReaders should\b|\bvalues lens\b/i.test(text)) {
    findings.push(editorFinding("news-lab-editorial-tone-leak", lane, "news-lab", text, "Rewrite News Lab copy as neutral fact reporting, not opinion/editorial.", "high"));
  }
  if (lane === "news-lab" && /\bCE Media\b|reporting trail|base story|outlet-only claim|coverage separates|central issue is|next piece to watch|story has been picked up|source signals? reviewed|providing one of the source signals|central development in this .* report|as the current news event/i.test(text)) {
    findings.push(editorFinding("news-lab-process-language", lane, "news-lab", text, "Rewrite public article copy so it reports the topic, not the internal reporting process.", "high"));
  }
  if (lane === "news-lab" && record.summary && Array.isArray(record.body) && record.body.some(paragraph => newsLabTextOverlap(paragraph, record.summary) >= 0.82)) {
    findings.push(editorFinding("summary-repeats-body", lane, "summary/body", record.summary, "Rewrite the summary and first body paragraph so they do not repeat each other.", "medium"));
  }
  if (lane === "news-lab") {
    (record.qualityGate?.issues || []).forEach(code => {
      findings.push(editorFinding(code, lane, "qualityGate", (record.body || []).join(" "), "Apply the News Lab quality-gate repair before publication.", code === "insufficient-full-article-facts" ? "medium" : "high"));
    });
  }
  const seen = new Set();
  return findings.filter(finding => {
    const key = `${finding.code}:${finding.path}:${finding.snippet}`;
    if (seen.has(key)) return false;
    seen.add(key);
    return true;
  });
}

function newsLabImageEditorFindings(record = {}, lane = "news-lab") {
  if (lane !== "news-lab") return [];
  const image = record.image || {};
  const findings = [];
  const imageText = `${image.primary || ""} ${image.alt || ""} ${image.credit || ""} ${image.query || ""}`;
  if (!image.primary || image.license === "local-placeholder" || /placeholder|newsroom-hero|creator-bg/i.test(image.primary || "")) {
    findings.push(editorFinding("image-missing-or-placeholder", lane, "image.primary", imageText, "Select a valid story-relevant image before publication.", "high"));
  }
  if (image.license === "Pexels" && !/Photo by .+ via Pexels/i.test(image.credit || "")) {
    findings.push(editorFinding("image-missing-credit", lane, "image.credit", imageText, "Show photographer credit for the selected Pexels image.", "high"));
  }
  if (image.license === "Pixabay" && !/Image by .+ via Pixabay/i.test(image.credit || "")) {
    findings.push(editorFinding("image-missing-credit", lane, "image.credit", imageText, "Show creator credit for the selected Pixabay image.", "high"));
  }
  const storyTerms = typeof newsLabImageArticleTerms === "function" ? newsLabImageArticleTerms(record) : [];
  const imageHaystack = `${image.alt || ""} ${image.query || ""} ${(image.relevance?.matchedTerms || []).join(" ")}`.toLowerCase();
  const matchedTermCount = storyTerms.filter(term => imageHaystack.includes(term)).length;
  const relevanceScore = Number(image.relevance?.score || 0);
  if ((image.license === "Pexels" || image.license === "Pixabay") && relevanceScore > 0 && relevanceScore < 4) {
    findings.push(editorFinding("image-low-relevance", lane, "image.relevance", imageText, "Reject low-scoring licensed image matches and try a more specific query.", "medium"));
  }
  if ((image.license === "Pexels" || image.license === "Pixabay") && storyTerms.length >= 4 && matchedTermCount === 0 && !newsLabCategoryImageMatches(record, image)) {
    findings.push(editorFinding("image-topic-mismatch", lane, "image.alt", imageText, "Choose an image whose alt text/query matches the story category or concrete story terms.", "medium"));
  }
  return findings;
}

function newsLabCategoryImageMatches(story = {}, image = {}) {
  const category = newsLabCategory(story);
  const text = `${image.alt || ""} ${image.query || ""}`.toLowerCase();
  const categoryTerms = {
    sports: /sport|stadium|field|court|ball|player|team|match|game|golf|tennis|soccer|baseball|basketball|football|athlete|championship|playoff/,
    politics: /capitol|government|vote|ballot|election|press conference|white house|law|court/,
    world: /diplomacy|international|military|conflict|government|meeting|flag|world|security|vatican|catholic|church|religion/,
    local: /city|street|police|weather|storm|utility|community|fire|traffic|neighborhood/,
    entertainment: /concert|music|film|stage|artist|award|television|culture|performance/,
    business: /business|economy|market|city|finance|company|trade|regulation/,
    technology: /technology|business|regulation|software|privacy|platform|data|computer|industry|city/
  };
  return Boolean((categoryTerms[category] || /news|journalism|city/).test(text));
}

function contentLaneQualityRules(lane = "general") {
  const shared = [
    "remove mojibake, clipped sentences, ellipses, script fragments, and copied source noise",
    "preserve source links and story context while using original Censored Expressions wording",
    "dedupe repeated story/title references before public save",
    "run copy-editor review for spelling, sentence structure, punctuation, repetition, and public-facing polish"
  ];
  const laneRules = {
    "creator-desk": [
      "Creator Desk is opinion/editorial: tie values and judgment to the specific facts of each selected story",
      "do not expose backend instructions, subsystem labels, or internal quality directions to readers",
      "do not force unrelated stories into one paragraph or reuse a generic opinion frame",
      "vary openings, transitions, stance sentences, and closings from day to day"
    ],
    newsletter: [
      "Newsletter is recap plus forecast: summarize the prior Saturday-Friday week and preview the upcoming week",
      "source links guide topics and quick links; they are not the public body of the newsletter",
      "avoid duplicate story threads and keep public section labels reader-facing",
      "vary week-to-week openings, transitions, matter labels, and closing language"
    ],
    "news-lab": [
      "News Lab is fact-based reporting: remove Creator Desk opinion language and keep the article neutral",
      "cluster multiple outlets into one CE Media story when they cover the same topic",
      "cite a specific outlet only for unique or differing details, not for broadly accepted facts"
    ]
  };
  return [...shared, ...(laneRules[lane] || [])];
}

function applyContentLaneQualityGate(record = {}, lane = "general") {
  const prepared = polishContentLaneDraftForEditor(record, lane);
  const cleaned = technicalEditorDeep(cleanArchiveOutputDeep(prepared));
  const publicText = [
    cleaned.title,
    cleaned.summary,
    cleaned.html,
    cleaned.text,
    ...(Array.isArray(cleaned.body) ? cleaned.body : [])
  ].join(" ");
  const knownBadPattern = /\.{3}|ÃƒÆ’|ÃƒÂ¢Ã¢â€šÂ¬|ÃƒÂ¯Ã‚Â¿Ã‚Â½|&#x27;|fetch-start|fetch-done|headers|Comparing|Grizzli|\bbi\b|\bspo\b|\bDonal\b|\bUni\b|\bKi\b|not a placeholder|approved narrative|loudest room|The reader should be able to identify|The point is not to make every story say the same thing/i;
  const hasEncodingArtifact = publicText.includes(String.fromCharCode(226, 8364))
    || publicText.includes(String.fromCharCode(195))
    || publicText.includes(String.fromCharCode(65533));
  const laneIssues = [];
  if (knownBadPattern.test(publicText) || hasEncodingArtifact) laneIssues.push("known-public-artifact-pattern");
  if (lane === "news-lab" && /\b(My read|My view|Readers should|free people should|approved narrative)\b/i.test(publicText)) {
    laneIssues.push("news-lab-editorial-language");
  }
  if (lane === "news-lab" && /\bCE Media\b|reporting trail|base story|outlet-only claim|coverage separates|central issue is|next piece to watch|story has been picked up|source signals? reviewed|providing one of the source signals|central development in this .* report|as the current news event/i.test(publicText)) {
    laneIssues.push("news-lab-process-language");
  }
  if (lane === "creator-desk" && /\bSource Direction\b|subsystem|backend|quality gate/i.test(publicText)) {
    laneIssues.push("creator-internal-language");
  }
  if (lane === "creator-desk" && contentLaneInternalLanguagePattern().test(publicText)) {
    laneIssues.push("creator-internal-language");
  }
  if (lane === "creator-desk" && contentLaneStockFrameCount(publicText, lane) >= 2) {
    laneIssues.push("creator-repeated-editorial-frame");
  }
  if (lane === "newsletter" && /\bSource Direction\b|The practical question is|another round of approved language/i.test(publicText)) {
    laneIssues.push("newsletter-public-direction-language");
  }
  if (lane === "newsletter" && contentLaneInternalLanguagePattern().test(publicText)) {
    laneIssues.push("newsletter-public-direction-language");
  }
  if (lane === "newsletter" && contentLaneStockFrameCount(publicText, lane) >= 2) {
    laneIssues.push("newsletter-repeated-editorial-frame");
  }
  const editorFindings = technicalEditorFindings(cleaned, lane);
  const imageFindings = newsLabImageEditorFindings(cleaned, lane);
  const combinedFindings = [...editorFindings, ...imageFindings];
  const editorIssues = [...new Set(combinedFindings.map(finding => finding.code))];
  const allIssues = [...new Set([...laneIssues, ...editorIssues])];
  return {
    ...cleaned,
    contentLaneQuality: {
      lane,
      checkedAt: new Date().toISOString(),
      passed: allIssues.length === 0,
      issues: allIssues,
      laneIssues,
      technicalEditor: {
        passed: editorIssues.length === 0,
        issues: editorIssues,
        findings: combinedFindings.slice(0, 16),
        summary: technicalEditorSummary(lane),
        role: "newspaper-style technical editor"
      },
      rulesApplied: contentLaneQualityRules(lane)
    }
  };
}

function editorRewriteDraftForCompliance(record = {}, lane = "general", issues = []) {
  const cleaned = cleanArchiveOutputDeep(record);
  if (lane === "newsletter") {
    const revised = polishNewsletterIssue({
      ...cleaned,
      sourceDirections: [],
      sections: (cleaned.sections || []).map(section => ({
        ...section,
        signals: [],
        paragraphs: (section.paragraphs || [])
          .map(cleanNewsletterParagraph)
          .filter(Boolean)
          .filter((paragraph, index, all) => all.findIndex(item => item.toLowerCase() === paragraph.toLowerCase()) === index)
      })),
      topNews: uniqueNewsletterItems(cleaned.topNews || [], 3),
      quickLinks: uniqueNewsletterItems(cleaned.quickLinks || [], 5),
      upcoming: uniqueNewsletterItems(cleaned.upcoming || [], 8)
    });
    revised.html = newsletterHtml(revised);
    revised.text = newsletterText(revised);
    return revised;
  }
  if (lane === "creator-desk") {
    const items = (cleaned.items || []).map(sanitizeCreatorArchiveStory);
    const rebuilt = {
      ...cleaned,
      items,
      body: items.length ? buildCreatorEditorial(items) : cleaned.body
    };
    rebuilt.html = creatorDeskHtml(rebuilt);
    rebuilt.text = creatorDeskText(rebuilt);
    return rebuilt;
  }
  if (lane === "news-lab") {
    const repaired = typeof newsLabRepairStoryForPublication === "function"
      ? newsLabRepairStoryForPublication(cleaned)
      : cleaned;
    return {
      ...repaired,
      editorRepairReason: issues
    };
  }
  return cleaned;
}

function saveEditorLearningFromEnforcement(input = {}) {
  const lane = input.lane || "general";
  const initialFindings = input.initialFindings || [];
  const finalFindings = input.finalFindings || [];
  const initialIssues = [...new Set(initialFindings.map(finding => finding.code).filter(Boolean))];
  const finalIssues = [...new Set(finalFindings.map(finding => finding.code).filter(Boolean))];
  if (!initialIssues.length && !finalIssues.length) return null;
  const resolvedIssues = initialIssues.filter(issue => !finalIssues.includes(issue));
  const lessonRules = [...new Set(initialFindings.map(finding => finding.subsystemLesson).filter(Boolean))].slice(0, 8);
  const memory = learningMemory();
  const lesson = {
    at: new Date().toISOString(),
    source: "technical-editor",
    summary: `${lane} editor identified ${initialIssues.length} issue type(s) and ${resolvedIssues.length} resolved issue type(s).`,
    problem: initialFindings.map(finding => `${finding.code} at ${finding.path}`).slice(0, 10).join("; "),
    behaviorRule: lessonRules.join(" "),
    result: finalIssues.length
      ? `Editor rewrite still needs attention: ${finalIssues.join(", ")}.`
      : "Editor rewrite cleared the detected issue types before publication.",
    rationale: "The Brain and subsystems should treat editor findings as training signals for future drafts, not only as one-time cleanup.",
    appliesTo: [lane, "technical editor", "content quality"],
    tags: ["technical-editor", "content-quality", "subsystem-learning", lane]
  };
  memory.changeLessons = [...(memory.changeLessons || []), lesson].slice(-100);
  memory.engineeringLessons = [
    ...(memory.engineeringLessons || []),
    engineeringLessonFromCodexChange(lesson)
  ].slice(-150);
  writeJsonFile(learningFile, memory);
  return saveFrameworkActionLogEntry({
    type: "content-editor-learning",
    actionKey: `technical-editor-${lane}`,
    reason: "The newspaper-style editor found public writing issues and converted them into Brain/subsystem learning.",
    trigger: {
      lane,
      initialIssues,
      finalIssues
    },
    bounded: true,
    reversible: true,
    safeExecution: true,
    autonomous: true,
    status: finalIssues.length ? "editor-learning-needs-review" : "editor-learning-applied",
    verified: finalIssues.length === 0,
    beforeMetric: {
      issueTypeCount: initialIssues.length,
      findingCount: initialFindings.length
    },
    afterMetric: {
      issueTypeCount: finalIssues.length,
      findingCount: finalFindings.length,
      resolvedIssueTypeCount: resolvedIssues.length
    },
    details: {
      lane,
      initialFindings: initialFindings.slice(0, 12),
      finalFindings: finalFindings.slice(0, 12),
      learningRules: lessonRules
    },
    preventionMemory: `For ${lane}, use technical editor findings before publication: ${lessonRules.join(" ")}`
  });
}

function contentLaneSubsystemsForLane(lane = "general") {
  if (lane === "creator-desk") {
    return ["Creator Desk Writer", "Publishing Editor", "Editorial Coach", "Writing Intelligence"];
  }
  if (lane === "newsletter") {
    return ["Newsletter Writer", "Publishing Editor", "Editorial Coach", "Writing Intelligence"];
  }
  if (lane === "news-lab") {
    return ["Article Writer", "Publishing Editor", "Publisher Validator", "Writing Intelligence"];
  }
  return ["Publishing Editor", "Writing Intelligence"];
}

function contentLaneEditorDecisionRecord(input = {}) {
  const lane = input.lane || "general";
  const issues = [...new Set(input.issues || [])].filter(Boolean);
  const accepted = Boolean(input.accepted);
  const title = cleanArticleText(input.title || `${lane} public writing`, 180);
  const score = Number(input.score || (accepted ? 96 : 62));
  return {
    id: `content_lane_${lane}_${Date.now()}_${Math.random().toString(36).slice(2, 7)}`,
    learnedAt: new Date().toISOString(),
    title,
    category: lane,
    lane,
    score,
    issues,
    stage: "content-lane-technical-editor",
    earliestFailingStage: issues.length ? "Publishing Editor" : "Editor Approved",
    decision: accepted ? "approved-content-lane-writing" : "repaired-content-lane-writing",
    nextActions: issues.length
      ? issues.map(issue => editorLearningRuleForIssue(issue, lane)).slice(0, 8)
      : [`${lane}: Preserve this first-pass pattern and reuse the craft choices that passed technical/editorial review.`],
    targetSubsystems: contentLaneSubsystemsForLane(lane),
    repairAction: accepted ? "No repair required." : "Publishing Editor repaired the draft, then resubmitted it through the same lane gate.",
    outcome: accepted ? "first-pass-accepted" : "repair-reviewed",
    source: "content-lane-editor"
  };
}

function recordContentLaneWritingIntelligenceLearning(input = {}) {
  const lane = input.lane || "general";
  if (!["creator-desk", "newsletter"].includes(lane)) {
    return { skipped: true, reason: "lane-not-targeted-for-content-writing-intelligence", lane };
  }
  const initialIssues = [...new Set(input.initialIssues || [])].filter(Boolean);
  const finalIssues = [...new Set(input.finalIssues || [])].filter(Boolean);
  const records = [];
  if (!initialIssues.length && !finalIssues.length) {
    records.push(contentLaneEditorDecisionRecord({
      lane,
      title: input.title,
      accepted: true,
      score: 96,
      issues: []
    }));
  } else {
    records.push(contentLaneEditorDecisionRecord({
      lane,
      title: input.title,
      accepted: finalIssues.length === 0,
      score: finalIssues.length ? 58 : 88,
      issues: initialIssues
    }));
    if (finalIssues.length) {
      records.push(contentLaneEditorDecisionRecord({
        lane,
        title: input.title,
        accepted: false,
        score: 52,
        issues: finalIssues
      }));
    }
  }
  const result = recordNewsLabEditorDecisionLearning(records, {
    source: "content-lane-editor",
    lane,
    appliesTo: [lane, "creator-desk", "newsletter", "writing-intelligence"].filter((value, index, all) => all.indexOf(value) === index),
    purpose: "Share Creator Desk and Newsletter writing-quality decisions with the same Writing Intelligence memory used by News Lab."
  });
  saveFrameworkLearningProofEntry({
    category: "content-lane-writing-intelligence",
    event: `${lane} editor decisions were routed into shared Writing Intelligence.`,
    plainEnglish: "Creator Desk and Newsletter writing issues now update the same editor decision memory, writing pattern library, and writing technique registry used by News Lab, while keeping each lane's purpose separate.",
    realWorldData: {
      lane,
      initialIssues,
      finalIssues,
      acceptedFirstPass: !initialIssues.length && !finalIssues.length,
      recordCount: records.length
    },
    decisionMeasurement: {
      writingPatternLibraryUpdated: true,
      writingTechniqueRegistryUpdated: true,
      editorDecisionMemoryUpdated: true
    },
    resultMetric: {
      finalIssueCount: finalIssues.length,
      initialIssueCount: initialIssues.length
    },
    proceduralMemory: {
      futureUse: "Before future Creator Desk and Newsletter drafts, read Writing Intelligence, avoid repeated weak patterns, and apply lane-specific editorial standards before publication.",
      interventionNeeded: false
    }
  });
  return result;
}

function contentLaneWritingIntelligenceGuidance(lane = "general") {
  const memory = learningMemory();
  const writing = writingPatternLibrarySummary(memory);
  const techniques = writingTechniqueRegistrySummary(memory.writingTechniqueRegistry || readJsonFile(writingTechniqueRegistryFile, null));
  const editorMemory = memory.editorDecisionMemory || {};
  const topIssues = Object.entries(editorMemory.issueCounts || {})
    .sort((a, b) => Number(b[1] || 0) - Number(a[1] || 0))
    .slice(0, 8)
    .map(([issue, count]) => `${issue}:${count}`);
  const laneRules = contentLaneQualityRules(lane).slice(0, 8);
  return {
    lane,
    writingScore: Number(writing.overall || 0),
    weakestPattern: writing.weakestPattern || null,
    weakestTechniques: (techniques.weakestTechniques || []).slice(0, 5),
    topEditorIssues: topIssues,
    laneRules,
    directive: lane === "creator-desk"
      ? "Use opinion and values, but tie every judgment to the exact story facts; vary transitions and avoid reusable stock paragraphs."
      : lane === "newsletter"
        ? "Use recap plus forecast, but vary openings/transitions week to week and keep source links as direction rather than body copy."
        : "Use the shared writing memory before drafting and correct known weak patterns before editor review."
  };
}

function enforceContentEditor(record = {}, lane = "general") {
  const firstPass = applyContentLaneQualityGate(record, lane);
  if (firstPass.contentLaneQuality?.passed) {
    recordContentLaneWritingIntelligenceLearning({
      lane,
      title: firstPass.title || firstPass.subject || firstPass.feature?.headline || "",
      initialIssues: [],
      finalIssues: []
    });
    return {
      ...firstPass,
      editorEnforcement: {
        lane,
        checkedAt: new Date().toISOString(),
        action: "accepted-first-draft",
        attempts: 1,
        initialIssues: [],
        finalIssues: []
      }
    };
  }
  const initialIssues = firstPass.contentLaneQuality?.issues || [];
  const initialFindings = firstPass.contentLaneQuality?.technicalEditor?.findings || [];
  const rewrittenDraft = editorRewriteDraftForCompliance(firstPass, lane, initialIssues);
  const secondPass = applyContentLaneQualityGate(rewrittenDraft, lane);
  const finalFindings = secondPass.contentLaneQuality?.technicalEditor?.findings || [];
  recordContentLaneWritingIntelligenceLearning({
    lane,
    title: secondPass.title || secondPass.subject || secondPass.feature?.headline || firstPass.title || "",
    initialIssues,
    finalIssues: secondPass.contentLaneQuality?.issues || []
  });
  saveEditorLearningFromEnforcement({
    lane,
    initialFindings: [
      ...initialFindings,
      ...((firstPass.contentLaneQuality?.laneIssues || []).map(code => editorFinding(code, lane, "lane-rule", "", "Apply lane-specific public writing rule before save.", "high")))
    ],
    finalFindings: [
      ...finalFindings,
      ...((secondPass.contentLaneQuality?.laneIssues || []).map(code => editorFinding(code, lane, "lane-rule", "", "Apply lane-specific public writing rule before save.", "high")))
    ]
  });
  return {
    ...secondPass,
    editorEnforcement: {
      lane,
      checkedAt: new Date().toISOString(),
      action: secondPass.contentLaneQuality?.passed ? "forced-rewrite-and-approved" : "forced-rewrite-needs-owner-review",
      attempts: 2,
      initialIssues,
      finalIssues: secondPass.contentLaneQuality?.issues || [],
      rule: "Drafts that fail the newspaper-style technical editor or lane rules must be rewritten before save/publish."
    }
  };
}

function polishNewsletterIssue(newsletter = {}) {
  const paragraphSeen = new Set();
  const cleanParagraphs = paragraphs => (paragraphs || [])
    .map(cleanNewsletterParagraph)
    .filter(Boolean)
    .filter(paragraph => {
      const key = paragraph.toLowerCase().replace(/[^a-z0-9]+/g, " ").slice(0, 160);
      if (paragraphSeen.has(key)) return false;
      paragraphSeen.add(key);
      return true;
    });
  const sections = (newsletter.sections || []).map(section => ({
    ...section,
    intro: cleanNewsletterParagraph(section.intro || ""),
    paragraphs: cleanParagraphs(section.paragraphs || [])
  }));
  const featureParagraphs = cleanParagraphs(newsletter.feature?.paragraphs || sections[0]?.paragraphs || []);
  return dedupeNewsletterIssueLists({
    ...newsletter,
    editorNote: cleanNewsletterParagraph(newsletter.editorNote || ""),
    openingNote: cleanNewsletterParagraph(newsletter.openingNote || ""),
    sections,
    feature: newsletter.feature ? {
      ...newsletter.feature,
      headline: cleanNewsletterCopy(newsletter.feature.headline || ""),
      paragraphs: featureParagraphs.length ? featureParagraphs : sections[0]?.paragraphs || []
    } : newsletter.feature,
    topNews: uniqueNewsletterItems((newsletter.topNews || []).map(item => ({
      ...item,
      title: cleanNewsletterCopy(item.title || ""),
      brief: cleanNewsletterParagraph(item.brief || "")
    })), 3),
    quickLinks: uniqueNewsletterItems(newsletter.quickLinks || [], 5),
    upcoming: uniqueNewsletterItems(newsletter.upcoming || [], 8),
    sourceDirections: uniqueNewsletterItems(newsletter.sourceDirections || [], 7),
    previewBullets: cleanParagraphs(newsletter.previewBullets || []).slice(0, 3),
    callToAction: cleanNewsletterParagraph(newsletter.callToAction || "")
  });
}

function cleanNewsletterDeep(value) {
  if (typeof value === "string") return cleanNewsletterParagraph(value);
  if (Array.isArray(value)) return value.map(cleanNewsletterDeep);
  if (value && typeof value === "object") {
    return Object.fromEntries(Object.entries(value).map(([key, item]) => [key, cleanNewsletterDeep(item)]));
  }
  return value;
}

function rebuildNewsletterIssue(newsletter = {}) {
  return rebuildNewsletterIssueFromStoredStories(newsletter);
}

function brainRewriteNewsletterArchive(input = {}) {
  const newsletters = readJsonFile(newslettersFile, []);
  const list = Array.isArray(newsletters) ? newsletters : [newsletters].filter(Boolean);
  const before = {
    newsletterCount: list.length,
    oldPhraseCount: JSON.stringify(list).match(/The practical question is|another round of approved language|My read is that this is where commentary has to slow down/g)?.length || 0,
    duplicateTopNewsCount: list.reduce((sum, issue) => {
      const titles = (issue.topNews || []).map(item => cleanNewsletterCopy(item.title || ""));
      return sum + titles.length - new Set(titles).size;
    }, 0)
  };
  const rewritten = list.map(rebuildNewsletterIssue);
  writeJsonFile(newslettersFile, rewritten);
  const afterRaw = JSON.stringify(rewritten);
  const after = {
    newsletterCount: rewritten.length,
    oldPhraseCount: afterRaw.match(/The practical question is|another round of approved language|My read is that this is where commentary has to slow down/g)?.length || 0,
    duplicateTopNewsCount: rewritten.reduce((sum, issue) => {
      const titles = (issue.topNews || []).map(item => cleanNewsletterCopy(item.title || ""));
      return sum + titles.length - new Set(titles).size;
    }, 0)
  };
  return saveFrameworkActionLogEntry({
    type: "owner-feedback-content-execution",
    actionKey: "brain-rewrite-newsletter-archive",
    reason: "Owner feedback said newsletters were repeating generic editorial language and duplicating story threads.",
    trigger: {
      note: String(input.note || input.instruction || "").slice(0, 600),
      target: input.target || "newsletter"
    },
    bounded: true,
    reversible: true,
    safeExecution: true,
    autonomous: true,
    status: "content-archive-rewritten",
    verified: after.oldPhraseCount === 0 && after.duplicateTopNewsCount === 0,
    message: `Brain cleaned ${after.newsletterCount} newsletter issue(s), removed stock phrases, rebuilt html/text, and deduped top-news story threads.`,
    beforeMetric: before,
    afterMetric: after,
    details: {
      rewrittenWeekIds: rewritten.map(issue => issue.weekId || issue.id).filter(Boolean),
      affectedFile: "data/newsletters.json"
    },
    preventionMemory: "When owner feedback says weekly newsletters are generic, repetitive, or duplicating stories, immediately apply the daily editorial quality rules to current and past newsletter records, rebuild public html/text, and verify no stock phrase or duplicate top-news title remains."
  });
}

function newsletterHtml(newsletter) {
  const brand = newsletter.brand || newsletterBranding();
  const topNews = (newsletter.topNews || []).map(item => `
    <li>
      <strong>${escapeHtml(item.title)}</strong>
      <p>${escapeHtml(item.brief || "")}</p>
    </li>
  `).join("");
  const quickLinks = (newsletter.quickLinks || []).map(item => `
    <li><a href="${escapeHtml(item.url)}">${escapeHtml(item.label || item.title)}</a><span>${escapeHtml(item.source || "")}</span></li>
  `).join("");
  const featureParagraphs = (newsletter.feature?.paragraphs || newsletter.sections?.[0]?.paragraphs || [])
    .map(paragraph => `<p>${escapeHtml(paragraph)}</p>`)
    .join("");
  const forecastParagraphs = (newsletter.sections?.find(section => section.title === "What Comes Next")?.paragraphs || [])
    .map(paragraph => `<p>${escapeHtml(paragraph)}</p>`)
    .join("");
  const valuesParagraphs = (newsletter.sections?.find(section => section.title === "Values Lens")?.paragraphs || [])
    .map(paragraph => `<p>${escapeHtml(paragraph)}</p>`)
    .join("");
  const legacySections = !newsletter.feature ? newsletter.sections.map(section => `
    <section class="newsletter-article">
      <h3>${escapeHtml(section.title)}</h3>
      ${section.intro ? `<p>${escapeHtml(section.intro)}</p>` : ""}
      ${(section.paragraphs || []).map(paragraph => `<p>${escapeHtml(paragraph)}</p>`).join("")}
      ${section.signals?.length ? `<ul>${section.signals.map(signal => `<li><strong>${escapeHtml(signal.matter || signal.topic)}</strong><span>${escapeHtml(signal.source || "")}</span><p>${escapeHtml(signal.takeaway || signal.question || "")}</p></li>`).join("")}</ul>` : ""}
      ${section.items?.length ? `<ul>${section.items.map(item => `<li><a href="${escapeHtml(item.url)}">${escapeHtml(item.title)}</a><span>${escapeHtml(item.source)}</span><p>${escapeHtml(item.summary || "")}</p></li>`).join("")}</ul>` : ""}
    </section>
  `).join("") : "";

  const upcoming = newsletter.upcoming.map(item => `<li><a href="${escapeHtml(item.url)}">${escapeHtml(item.title)}</a><span>${escapeHtml(item.source)}</span></li>`).join("");

  return `
    <article class="newsletter-issue newsletter-magazine-issue">
      <header class="newsletter-masthead">
        <div class="newsletter-brand-lockup">
          <img src="${escapeHtml(brand.sealImage)}" alt="${escapeHtml(brand.name)} seal" />
          <div>
            <strong>${escapeHtml(brand.name)}</strong>
            <span>${escapeHtml(brand.tagline)}</span>
          </div>
        </div>
        <h2>${escapeHtml(newsletter.title)}</h2>
        <div class="newsletter-issue-meta">
          <span>${escapeHtml(newsletter.publicationDateLabel || newsletter.generatedLabel || newsletter.weekLabel)}</span>
          <span>${escapeHtml(newsletter.volume || "Weekly")}</span>
        </div>
      </header>
      <div class="newsletter-magazine-grid">
        <aside class="newsletter-sidebar">
          <section class="newsletter-opening-note">
            <h3>Opening Note</h3>
            <p>${escapeHtml(newsletter.openingNote || "")}</p>
          </section>
          <section>
            <h3>Top News</h3>
            <ul>${topNews}</ul>
          </section>
          <section>
            <h3>Quick Links</h3>
            <ul>${quickLinks}</ul>
          </section>
          <section>
            <h3>What To Watch</h3>
            <ul>${upcoming}</ul>
          </section>
        </aside>
        <main class="newsletter-feature">
          <p class="newsletter-kicker">${escapeHtml(newsletter.feature?.kicker || "Weekly Signal")}</p>
          <h3>${escapeHtml(newsletter.feature?.headline || newsletter.sections?.[0]?.title || newsletter.title)}</h3>
          ${newsletter.editorNote ? `<p class="newsletter-deck">${escapeHtml(newsletter.editorNote)}</p>` : ""}
          <div class="newsletter-columns">${featureParagraphs}</div>
          <section class="newsletter-forward">
            <h3>What Comes Next</h3>
            ${forecastParagraphs}
          </section>
          <section class="newsletter-forward">
            <h3>Values Lens</h3>
            ${valuesParagraphs}
          </section>
          <section class="newsletter-cta">
            <h3>Reader Call</h3>
            <p>${escapeHtml(newsletter.callToAction || "")}</p>
          </section>
          ${legacySections}
        </main>
      </div>
    </article>
  `;
}

function newsletterText(newsletter) {
  const brand = newsletter.brand || newsletterBranding();
  const sections = newsletter.sections.map(section => {
    const paragraphs = (section.paragraphs || []).join("\n\n");
    const items = (section.items || []).map(item => `- ${item.title} (${item.source})\n  ${item.url}`).join("\n");
    return `${section.title}\n${paragraphs}${items ? `\n\n${items}` : ""}`;
  }).join("\n\n");
  const upcoming = newsletter.upcoming.map(item => `- ${item.title} (${item.source})\n  ${item.url}`).join("\n");
  const topNews = (newsletter.topNews || []).map(item => `- ${item.title}: ${item.brief}`).join("\n");
  const quickLinks = (newsletter.quickLinks || []).map(item => `- ${item.label || item.title}: ${item.url}`).join("\n");
  return `${brand.name}\n${brand.tagline}\n\n${newsletter.title}\n${newsletter.publicationDateLabel || newsletter.generatedLabel || newsletter.weekLabel}\n\nOpening Note\n${newsletter.openingNote || ""}\n\nTop News\n${topNews}\n\nQuick Links\n${quickLinks}\n\n${newsletter.editorNote || ""}\n\n${sections}\n\nReader Call\n${newsletter.callToAction || ""}\n\nUpcoming Week Watchlist\n${upcoming}`;
}

function validateNewsletterAiDraft(draft, fallback) {
  if (!draft || typeof draft !== "object") return null;
  const title = String(draft.title || fallback.title || "").trim();
  const intro = String(draft.intro || "").trim();
  const sectionIntros = draft.sectionIntros && typeof draft.sectionIntros === "object" ? draft.sectionIntros : {};
  if (title.length < 8 && intro.length < 20) return null;
  const sections = fallback.sections.map(section => ({
    ...section,
    intro: String(sectionIntros[section.title] || section.intro || "").trim()
  }));
  return {
    title: title ? title.slice(0, 120) : fallback.title,
    editorNote: intro ? intro.slice(0, 420) : fallback.editorNote,
    sections
  };
}

function recentCodexLessonText(memory = learningMemory(), limit = 8) {
  return (memory.changeLessons || [])
    .slice(-limit)
    .map(lesson => lesson.behaviorRule || lesson.summary)
    .filter(Boolean)
    .join(" ");
}

async function generateNewsletterAiDraft(seed) {
  const memory = learningMemory();
  const writingGuidance = contentLaneWritingIntelligenceGuidance("newsletter");
  const systemPrompt = [
    "You write the Censored Expressions weekly newsletter.",
    "Make it public-facing and polished. Do not mention backend systems, AI, ranking, automation, prompts, or internal process.",
    "The newsletter must read like a polished magazine issue with a clear lead, smooth transitions, short sidebar briefs, a main narrative, and a forward-looking close.",
    "Use a consistent weekly email structure: opening note, main feature, quick links, forecast/watchlist, values lens, and one clear reader call-to-action.",
    "Write for skimmability with short paragraphs, clear headings, and mobile-first layout.",
    "The newsletter must be original weekly commentary: recap the prior week's news cycle, forecast the coming week, and apply the owner's values.",
    "Do not turn the newsletter into a reposted article list. The provided sources are direction signals only.",
    "The public newsletter should show only the publication date. Do not repeat coverage-window date ranges. Use natural phrases like this past week, leading up to this week, upcoming this week, and this week unless a specific date is essential to the story.",
    "Keep it concise: a short title, one short intro, and optional one-sentence intros for existing sections.",
    "Do not invent stories, links, sources, dates, or facts. Use only the provided section titles and story information.",
    `Learned style preferences: ${(memory.styleNotes || []).slice(0, 8).join(" ")}`,
    `Writing Intelligence guidance: ${JSON.stringify(writingGuidance).slice(0, 1800)}`,
    `Lexicon Intelligence guidance: ${JSON.stringify(lexiconIntelligenceSummary("newsletter")).slice(0, 1400)}`,
    `Recent Codex-taught lessons: ${recentCodexLessonText(memory, 6)}`,
    `Decision reasoning memory: ${reasoningDigest(memory, 6)}`,
    `Visitor search-interest signal (soft input only): ${searchInterestDigest(8) || "No search-interest signal yet."}`,
    "Use visitor search interest only as one weak signal for audience curiosity; never let it override news value, reporting strength, site values, or editorial judgment.",
    "Return JSON only with this shape: {\"title\":\"...\",\"intro\":\"...\",\"sectionIntros\":{\"Top Headlines\":\"...\"}}"
  ].join("\n");
  return validateNewsletterAiDraft(await runOpenAiJson(systemPrompt, seed, "Newsletter"), seed);
}

async function generateWeeklyNewsletter(force = false) {
  const week = workWeekWindow();
  const newsletters = readJsonFile(newslettersFile, []);
  const existing = newsletters.find(item => item.weekId === week.id);
  if (existing && !force) return existing;

  const payload = await getNewsPayload(true).catch(() => ({ stories: fallbackStories, status: "fallback" }));
  const memory = learningMemory();
  const rankedStories = rankStoriesWithLearning(payload.stories || fallbackStories, memory);
  const currentStories = rankedStories.filter(story => !newsletterStoryLooksStale(story, week));
  const stories = currentStories.length >= 6 ? currentStories : rankedStories;
  const commentary = buildNewsletterSections(stories, week);
  const newsletter = {
    id: `newsletter_${week.id}`,
    weekId: week.id,
    title: "Censored Expressions Weekly Signal",
    weekLabel: week.coveredRangeLabel || `${week.startLabel} - ${week.endLabel}`,
    generatedAt: new Date().toISOString(),
    publicationDateLabel: newsletterPublicationLabel(),
    workWeek: "Saturday through Friday",
    forecastWeekLabel: week.forecastRangeLabel,
    editorNote: "A weekly recap of this past week, followed by values-driven commentary and a forward-looking forecast for what is upcoming this week.",
    brand: newsletterBranding(),
    learning: learningSummary(memory),
    sections: commentary.sections,
    openingNote: commentary.openingNote,
    feature: {
      kicker: "Weekly Signal",
      headline: commentary.leadHeadline,
      paragraphs: commentary.mainNarrative
    },
    topNews: commentary.topBriefs,
    quickLinks: commentary.quickLinks,
    callToAction: commentary.callToAction,
    sourceDirections: commentary.signals,
    previewBullets: [
      commentary.mainNarrative[0],
      commentary.mainNarrative[1],
      commentary.forecast[0]
    ].filter(Boolean),
    upcoming: commentary.upcoming,
    volume: "Weekly Edition",
    status: "draft",
    sendStatus: "pending"
  };
  const aiDraft = await generateNewsletterAiDraft(newsletter);
  if (aiDraft) {
    newsletter.title = aiDraft.title;
    newsletter.editorNote = aiDraft.editorNote;
    newsletter.sections = aiDraft.sections;
    newsletter.aiModel = aiModelStatus();
  } else {
    newsletter.aiModel = { enabled: false, fallback: "Built-in newsletter rules used." };
  }
  const polishedNewsletter = polishNewsletterIssue(newsletter);
  polishedNewsletter.html = newsletterHtml(polishedNewsletter);
  polishedNewsletter.text = newsletterText(polishedNewsletter);
  const finalNewsletter = enforceContentEditor(polishedNewsletter, "newsletter");

  const next = [finalNewsletter, ...newsletters.filter(item => item.weekId !== week.id)].slice(0, 104);
  writeJsonFile(newslettersFile, next);
  return finalNewsletter;
}

async function sendNewsletterToSubscribers(newsletter) {
  const subscribers = readJsonFile(subscribersFile, []).filter(item => item.status === "active");
  if (!subscribers.length) return { status: "no_subscribers", sent: 0 };

  const webhookUrl = process.env.NEWSLETTER_WEBHOOK_URL;
  if (!webhookUrl) {
    return { status: "provider_not_configured", sent: 0, pending: subscribers.length };
  }

  const origin = process.env.PUBLIC_SITE_URL || "https://censoredexpressions.com";
  const webhookSecret = process.env.NEWSLETTER_WEBHOOK_SECRET || "";
  const headers = { "content-type": "application/json" };
  if (webhookSecret) headers["x-newsletter-webhook-secret"] = webhookSecret;

  const subscribersWithTokens = subscribers.map(subscriber => ({
    ...subscriber,
    unsubscribeToken: subscriber.unsubscribeToken || crypto.randomBytes(24).toString("hex")
  }));
  writeJsonFile(subscribersFile, readJsonFile(subscribersFile, []).map(subscriber => {
    const updated = subscribersWithTokens.find(item => item.email === subscriber.email);
    return updated ? { ...subscriber, unsubscribeToken: updated.unsubscribeToken } : subscriber;
  }));

  const results = await Promise.allSettled(subscribersWithTokens.map(subscriber => {
    const unsubscribeUrl = `${origin.replace(/\/$/, "")}/api/newsletter/unsubscribe?token=${encodeURIComponent(subscriber.unsubscribeToken)}`;
    return fetch(webhookUrl, {
      method: "POST",
      headers,
      body: JSON.stringify({
        to: subscriber.email,
        name: `${subscriber.firstName} ${subscriber.lastName}`,
        subject: newsletter.title,
        html: newsletter.html,
        text: newsletter.text,
        unsubscribeUrl
      })
    }).then(async providerResponse => {
      if (!providerResponse.ok) {
        const providerText = await providerResponse.text().catch(() => "");
        throw new Error(`Newsletter provider returned ${providerResponse.status}: ${providerText.slice(0, 200)}`);
      }
      return providerResponse;
    });
  }));

  return {
    status: "sent",
    sent: results.filter(result => result.status === "fulfilled").length,
    failed: results.filter(result => result.status !== "fulfilled").length
  };
}

async function runNewsletterCycle(reason = "scheduled") {
  const week = workWeekWindow();
  const newsletters = readJsonFile(newslettersFile, []);
  const existing = newsletters.find(item => item.weekId === week.id);
  if (existing?.sentAt && reason !== "manual") return existing;

  const newsletter = await generateWeeklyNewsletter(reason === "manual");
  const sendResult = await sendNewsletterToSubscribers(newsletter);
  const updated = {
    ...newsletter,
    status: "archived",
    sendStatus: sendResult.status,
    sentAt: new Date().toISOString(),
    sendResult
  };
  const next = [updated, ...readJsonFile(newslettersFile, []).filter(item => item.weekId !== week.id)];
  writeJsonFile(newslettersFile, next);
  return updated;
}

function shouldRunNewsletterNow(date = new Date()) {
  const eastern = easternDateParts(date);
  return eastern.weekday === "Sat" && eastern.hour >= 5;
}

function startNewsletterLoop() {
  setTimeout(() => {
    if (shouldRunNewsletterNow()) runNewsletterCycle("startup").catch(error => { runtimeState.lastError = error.message; });
  }, 5000);
  setInterval(() => {
    if (shouldRunNewsletterNow()) runNewsletterCycle("scheduled").catch(error => { runtimeState.lastError = error.message; });
  }, newsletterCheckMs);
}

