  if (/visa|palestinian football|palestinian soccer|federation|granted us visa|granted u\.s\. visa/.test(text)) return "security, diplomacy, and fair competition";
  if (/war|military|iran|israel|gaza|ukraine|russia|china|nato|foreign|global/.test(text)) return "foreign policy and national strength";
  if (/\btax\b|\bbudget\b|\bspending\b|\bdebt\b|\bwelfare\b|\bsubsid|\bbenefit\b|\baid\b/.test(text)) return "government spending and dependency";
  if (/border|immigration|migrant|asylum/.test(text)) return "border order and national responsibility";
  if (/court|judge|law|rights|constitution|supreme/.test(text)) return "law, liberty, and conscience";
  if (/school|student|parent|child|children|family|father|mother/.test(text)) return "family authority and children";
  if (/race|racial|black|white|diversity|equity|discrimination/.test(text)) return "race, agency, and equal dignity";
  if (/gender|sex|trans|pronoun|lgbt|homosexual|marriage/.test(text)) return "private choices and public pressure";
  if (/movie|music|celebrity|artist|streaming|culture|hollywood|concert|kanye|rolling stone|billboard/.test(text)) return "culture and what it normalizes";
  if (story.category === "politics") return "government authority and public trust";
