  const category = newsLabCategory(story);
  const lower = factText.toLowerCase();
  const weakSubject = /^(The|This|That|They|Them|It|Into|First|Born|Despite|About|When|Mean|Mean They|The Revolutionary|Perfect Kids|America The|Submit Your Questions|About America|Peace|White|Submit|Court|Security Roundup|Ars Live|That Doesn|Weather|Fourth|America|World|Large|Pictures|Video|Sources?|Officials?|Reports?|News|Story|Update)$/i;
