  if (/\bgoogle\b/.test(publicHeadlineText) && /\b(android|eu|european union|antitrust|fine|appeal)\b/.test(publicHeadlineText)) return "Google Loses Final Appeal Over EU Android Fine";
  if (/\bamish shah\b/.test(publicHeadlineText) && /\b(arizona|primary|jay feely|house district|phoenix)\b/.test(publicHeadlineText)) return "Amish Shah Wins Arizona Democratic House Primary";
  if (/\bparamount\b/.test(publicHeadlineText) && /\bwarner\b/.test(publicHeadlineText) && /\b(antitrust|lawsuit|deal|merger)\b/.test(publicHeadlineText)) return "Paramount-Warner Bros Deal Faces State Antitrust Challenge";
  if (/\bdelta\b/.test(publicHeadlineText) && /\bbasic business\b/.test(publicHeadlineText)) return "Delta Introduces Basic Business Fare Option";
