function writingPatternKeysForIssue(issue = "") {
  const text = String(issue || "").toLowerCase();
  const keys = new Set();
  if (/headline|title|truncated|word-salad|copied-headline|publisher-headline|source-no-overlap/.test(text)) keys.add("headline");
  if (/lead|opening|first sentence|gets to the point/.test(text)) keys.add("lead");
  if (/context|who|what|when|where|missing-reporting-context|insufficient-full-article-facts|empty-body|short-body|body/.test(text)) keys.add("structure");
  if (/transition|repeated|repetition|generic|template|process-language|abrupt/.test(text)) keys.add("transition");
  if (/source|claim|fact|evidence|attribution|contradiction|unsupported|topic-drift|topic-contamination/.test(text)) keys.add("evidence");
  if (/ending|conclusion|why-it-matters|next step|next confirmed/.test(text)) keys.add("ending");
  if (!keys.size && issue === "editor-approved") {
    ["lead", "structure", "transition", "evidence", "headline", "ending"].forEach(key => keys.add(key));
  }
  if (!keys.size) keys.add("structure");
  return [...keys];
}

function updateWritingPatternLibraryFromEditorRecords(existingLibrary = null, records = [], context = {}) {
  const library = {
    ...defaultWritingPatternLibrary(),
    ...(existingLibrary || {}),
    patterns: {
      ...defaultWritingPatternLibrary().patterns,
      ...((existingLibrary || {}).patterns || {})
    },
    lessons: [...((existingLibrary || {}).lessons || [])]
  };
  records.filter(Boolean).forEach(record => {
    const approved = /approved|passed/i.test(record.decision || "") || !(record.issues || []).length;
    const issues = (record.issues?.length ? record.issues : ["editor-approved"]).filter(Boolean);
    issues.forEach(issue => {
      writingPatternKeysForIssue(issue).forEach(key => {
        const current = {
          ...defaultWritingPatternLibrary().patterns[key],
          ...(library.patterns[key] || {})
        };
        if (approved) current.successes = Number(current.successes || 0) + 1;
        else current.failures = Number(current.failures || 0) + 1;
        current.relatedIssues = {
          ...(current.relatedIssues || {}),
          [issue]: Number(current.relatedIssues?.[issue] || 0) + 1
        };
        current.successRate = Number(((Number(current.successes || 0) / Math.max(1, Number(current.successes || 0) + Number(current.failures || 0))) * 100).toFixed(1));
        current.lastLearnedAt = record.learnedAt || new Date().toISOString();
        current.teachWriter = key === "headline"
          ? "Build the headline after the article/dossier is complete; do not rewrite from publisher headlines."
          : current.principle;
        library.patterns[key] = current;
      });
    });
    library.lessons.unshift({
      at: record.learnedAt || new Date().toISOString(),
      decision: approved ? "approved-pattern" : "repair-needed",
      category: record.category || "",
      stage: record.earliestFailingStage || record.stage || "Editor",
      patternKeys: [...new Set(issues.flatMap(issue => writingPatternKeysForIssue(issue)))],
      issues,
      scoreBand: Number(record.score || 0) >= 85 ? "strong" : Number(record.score || 0) >= 70 ? "usable" : "needs-repair",
      storedContent: false,
      lesson: approved
        ? "Promote the successful construction pattern, not the article wording."
        : "Teach the Writer the craft failure before the next draft reaches the Editor."
    });
  });
  library.updatedAt = new Date().toISOString();
  library.lessons = library.lessons.slice(0, 250);
  const patternValues = Object.values(library.patterns || {});
  library.overall = clampScore(patternValues.reduce((sum, item) => sum + Number(item.successRate || 0), 0) / Math.max(1, patternValues.length));
  library.weakestPattern = Object.entries(library.patterns || {})
    .map(([key, value]) => ({ key, ...value }))
    .sort((a, b) => Number(a.successRate || 0) - Number(b.successRate || 0))[0] || null;
  library.rule = "Writing Intelligence stores technique-level lessons only. Story Dossier stores facts. Publisher text is never a style template.";
  return library;
}


