function formatMarketCap(value = 0) {
  const number = Number(value || 0);
  if (!number) return "";
  if (number >= 1e12) return `$${(number / 1e12).toFixed(2)}T`;
  if (number >= 1e9) return `$${(number / 1e9).toFixed(1)}B`;
  return `$${Math.round(number).toLocaleString()}`;
}

function marketSnapshotMarketNewsFromCache() {
  const payload = readJsonFile(newsLabPublishedPayloadFile, {}) || {};
  const stories = Array.isArray(payload.ownedStories) ? payload.ownedStories : Array.isArray(payload.stories) ? payload.stories : [];
  const marketStories = stories
    .filter(story => story && story.category === "business" && /\b(market|markets|stock|stocks|shares|wall street|dow|nasdaq|s&p|earnings|fed|federal reserve|oil|gold|inflation|investor|investors)\b/i.test(`${story.title || ""} ${story.summary || ""}`))
    .slice(0, 6)
    .map(story => ({
      title: story.title || "Market story",
      url: story.id ? `./news-lab-story.html?id=${encodeURIComponent(story.id)}` : (story.url || "#"),
      source: "CE Media",
      type: "ce-market-story",
      published: story.originalPublishedAt || story.generatedAt || story.lastUpdatedAt || ""
    }));
  const fallback = [
    { title: "Markets: latest U.S. stock market news", url: "https://www.cnbc.com/markets/", source: "CNBC", type: "market-news", published: new Date().toISOString() },
    { title: "Markets: Wall Street and business headlines", url: "https://www.marketwatch.com/markets", source: "MarketWatch", type: "market-news", published: new Date().toISOString() }
  ];
  return marketStories.length ? marketStories : fallback;
}

